(662,	169,	'_wpcode_last_error',	'a:10:{s:4:\"type\";i:2;s:7:\"message\";s:79:\"session_start(): Session cannot be started after headers have already been sent\";s:4:\"file\";s:113:\"/app/wp-content/plugins/insert-headers-and-footers/includes/class-wpcode-snippet-execute.php(419) : eval()\'d code\";s:4:\"line\";i:638;s:8:\"wpc_type\";s:5:\"error\";s:16:\"doing_activation\";b:0;s:7:\"snippet\";O:14:\"WPCode_Snippet\":36:{s:9:\"post_type\";s:6:\"wpcode\";s:17:\"location_taxonomy\";s:15:\"wpcode_location\";s:18:\"code_type_taxonomy\";s:11:\"wpcode_type\";s:13:\"tags_taxonomy\";s:11:\"wpcode_tags\";s:2:\"id\";i:169;s:9:\"post_data\";O:7:\"WP_Post\":24:{s:2:\"ID\";i:169;s:11:\"post_author\";s:1:\"1\";s:9:\"post_date\";s:19:\"2026-05-20 19:39:20\";s:13:\"post_date_gmt\";s:19:\"2026-05-20 19:39:20\";s:12:\"post_content\";s:2601:\"if (!function_exists(\'chards_restore_session\')) {\r\n    function chards_restore_session() {\r\n        if (!session_id()) session_start();\r\n\r\n        /* ── Initialise action flags if not set ── */\r\n        if (!isset($_SESSION[\'REGISTER_CARD\']))  $_SESSION[\'REGISTER_CARD\']  = false;\r\n        if (!isset($_SESSION[\'SET_PIN\']))        $_SESSION[\'SET_PIN\']        = false;\r\n        if (!isset($_SESSION[\'REMOVE_PIN\']))     $_SESSION[\'REMOVE_PIN\']     = false;\r\n        if (!isset($_SESSION[\'PIN_TARGET_UID\'])) $_SESSION[\'PIN_TARGET_UID\'] = null;\r\n\r\n        /* Already logged in — nothing to do */\r\n        if (!empty($_SESSION[\'chards_user_id\'])) return;\r\n\r\n        /* No remember cookie — nothing to do */\r\n        $cookie_name = \'chards_remember\';\r\n		$raw_token = $_COOKIE[$cookie_name] ?? ($_GET[\'remember_token\'] ?? null);\r\n		if (empty($raw_token)) return;\r\n\r\n        /* ── DB ── */\r\n        try {\r\n            $pdo = new PDO(\r\n                \'mysql:host=db.fr-pari1.bengt.wasmernet.com;port=10272;dbname=dbGQr4derPM6nWoRL4jPwNPN;charset=utf8mb4\',\r\n                \'0074c9f9784980005ded7796ee74\',\r\n                \'06950074-c9fa-7db2-8000-c0aec36ba1ac\',\r\n                [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]\r\n            );\r\n        } catch (PDOException $e) { return; }\r\n\r\n        /* Find a matching non-expired token */\r\n        $stmt = $pdo->prepare(\"\r\n            SELECT t.id, t.user_id, u.username\r\n            FROM chards_remember_tokens t\r\n            JOIN chards_users u ON u.id = t.user_id\r\n            WHERE t.token_hash = ?\r\n              AND t.expires_at > NOW()\r\n            LIMIT 1\r\n        \");\r\n        $stmt->execute([hash(\'sha256\', $raw_token)]);\r\n        $row = $stmt->fetch();\r\n\r\n        if (!$row) {\r\n            /* Token invalid or expired — clear the cookie */\r\n            setcookie($cookie_name, \'\', time() - 3600, \'/\', \'\', true, true);\r\n            return;\r\n        }\r\n\r\n        /* ── Restore session ── */\r\n        $_SESSION[\'chards_user_id\']  = $row[\'user_id\'];\r\n        $_SESSION[\'chards_username\'] = $row[\'username\'];\r\n\r\n        /* Rolling expiry — extend token another 30 days on each visit */\r\n        $pdo->prepare(\"\r\n            UPDATE chards_remember_tokens\r\n            SET expires_at = DATE_ADD(NOW(), INTERVAL 30 DAY)\r\n            WHERE id = ?\r\n        \")->execute([$row[\'id\']]);\r\n\r\n        /* Refresh cookie expiry too */\r\n        setcookie($cookie_name, $raw_token, time() + (30 * 24 * 3600), \'/\', \'\', true, true);\r\n    }\r\n}\r\nadd_action(\'init\', \'chards_restore_session\');\";s:10:\"post_title\";s:12:\"cookie check\";s:12:\"post_excerpt\";s:0:\"\";s:11:\"post_status\";s:7:\"publish\";s:14:\"comment_status\";s:6:\"closed\";s:11:\"ping_status\";s:6:\"closed\";s:13:\"post_password\";s:0:\"\";s:9:\"post_name\";s:12:\"cookie-check\";s:7:\"to_ping\";s:0:\"\";s:6:\"pinged\";s:0:\"\";s:13:\"post_modified\";s:19:\"2026-07-28 20:25:59\";s:17:\"post_modified_gmt\";s:19:\"2026-07-28 20:25:59\";s:21:\"post_content_filtered\";s:0:\"\";s:11:\"post_parent\";i:0;s:4:\"guid\";s:56:\"https://chards.wasmer.app/index.php/wpcode/cookie-check/\";s:10:\"menu_order\";i:0;s:9:\"post_type\";s:6:\"wpcode\";s:14:\"post_mime_type\";s:0:\"\";s:13:\"comment_count\";s:1:\"0\";s:6:\"filter\";s:3:\"raw\";}s:5:\"title\";N;s:4:\"code\";N;s:9:\"code_type\";N;s:8:\"location\";s:10:\"everywhere\";s:11:\"auto_insert\";N;s:13:\"insert_number\";N;s:6:\"active\";N;s:4:\"tags\";N;s:29:\"\0WPCode_Snippet\0location_term\";O:7:\"WP_Term\":10:{s:7:\"term_id\";i:8;s:4:\"name\";s:10:\"everywhere\";s:4:\"slug\";s:10:\"everywhere\";s:10:\"term_group\";i:0;s:16:\"term_taxonomy_id\";i:8;s:8:\"taxonomy\";s:15:\"wpcode_location\";s:11:\"description\";s:0:\"\";s:6:\"parent\";i:0;s:5:\"count\";i:10;s:6:\"filter\";s:3:\"raw\";}s:30:\"\0WPCode_Snippet\0code_type_term\";N;s:26:\"\0WPCode_Snippet\0tags_terms\";N;s:25:\"\0WPCode_Snippet\0use_rules\";N;s:21:\"\0WPCode_Snippet\0rules\";N;s:24:\"\0WPCode_Snippet\0priority\";N;s:26:\"\0WPCode_Snippet\0library_id\";N;s:24:\"\0WPCode_Snippet\0cloud_id\";N;s:16:\"custom_shortcode\";N;s:31:\"\0WPCode_Snippet\0library_version\";N;s:20:\"\0WPCode_Snippet\0note\";N;s:25:\"\0WPCode_Snippet\0generator\";N;s:30:\"\0WPCode_Snippet\0generator_data\";N;s:15:\"compress_output\";N;s:11:\"device_type\";N;s:8:\"schedule\";N;s:13:\"compiled_code\";N;s:14:\"location_extra\";N;s:20:\"shortcode_attributes\";N;s:10:\"attributes\";N;s:12:\"load_as_file\";N;s:8:\"modified\";N;}s:10:\"error_line\";i:3;s:3:\"url\";s:16:\"http://localhost\";s:4:\"time\";i:1787251686;}'),
