(92,	1,	'2026-04-18 08:07:19',	'2026-04-18 08:07:19',	'<!-- wp:cover {\"url\":\"https://chards.wasmer.app/wp-content/uploads/2026/04/bg2-768x770-1.png\",\"id\":123,\"hasParallax\":true,\"dimRatio\":0,\"customOverlayColor\":\"#3d3b52\",\"isUserOverlayColor\":false,\"minHeight\":1929,\"minHeightUnit\":\"px\",\"contentPosition\":\"top center\",\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover has-parallax has-custom-content-position is-position-top-center\" style=\"min-height:1929px\"><div class=\"wp-block-cover__image-background wp-image-123 size-full has-parallax\" style=\"background-position:50% 50%;background-image:url(https://chards.wasmer.app/wp-content/uploads/2026/04/bg2-768x770-1.png)\"></div><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim-0 has-background-dim\" style=\"background-color:#3d3b52\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Write title…\",\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\"></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:shortcode -->\n[wpcode id=\"95\"]\n<!-- /wp:shortcode --></div></div>\n<!-- /wp:cover -->',	'pack Opening',	'',	'publish',	'closed',	'closed',	'',	'pack-opening',	'',	'',	'2026-05-15 18:50:39',	'2026-05-15 18:50:39',	'',	0,	'https://chards.wasmer.app/?page_id=92',	0,	'page',	'',	0),
