(134,	1,	'2026-05-03 20:16:38',	'2026-05-03 20:16:38',	'<!-- wp:cover {\"url\":\"https://chards.wasmer.app/wp-content/uploads/2026/04/bg2-768x770-1.png\",\"id\":123,\"hasParallax\":true,\"dimRatio\":50,\"customOverlayColor\":\"#3d3b52\",\"isUserOverlayColor\":false,\"minHeight\":2071,\"minHeightUnit\":\"px\",\"contentPosition\":\"top center\",\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover has-parallax has-custom-content-position is-position-top-center\" style=\"min-height:2071px\"><div class=\"wp-block-cover__image-background wp-image-123 size-full has-parallax\" style=\"background-position:50% 50%;background-image:url(https://chards.wasmer.app/wp-content/uploads/2026/04/bg2-768x770-1.png)\"></div><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\" style=\"background-color:#3d3b52\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:spacer {\"height\":\"73px\"} -->\n<div style=\"height:73px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:shortcode -->\n[wpcode id=\"135\"]\n<!-- /wp:shortcode --></div></div>\n<!-- /wp:cover -->',	'story',	'',	'publish',	'closed',	'closed',	'',	'story',	'',	'',	'2026-05-03 20:16:38',	'2026-05-03 20:16:38',	'',	0,	'https://chards.wasmer.app/?page_id=134',	0,	'page',	'',	0),
(135,	1,	'2026-05-03 20:16:29',	'2026-05-03 20:16:29',	'<?php\r\n/* ============================================================\r\n   CHARDS — Story Page\r\n   URL: /story.php?chapter=1&page=1\r\n   Pulls panels from chards_story_page view, grouped by page.\r\n============================================================ */\r\nchards_require_app_access(\'storybook\');\r\n$dsn = \'mysql:host=db.fr-pari1.bengt.wasmernet.com;port=10272;dbname=dbGQr4derPM6nWoRL4jPwNPN;charset=utf8mb4\';\r\ntry {\r\n    $pdo = new PDO($dsn, \'0074c9f9784980005ded7796ee74\', \'06950074-c9fa-7db2-8000-c0aec36ba1ac\', [\r\n        PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,\r\n        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,\r\n    ]);\r\n} catch (PDOException $e) {\r\n    $pdo = null;\r\n}\r\n\r\n/* --- fetch all chapters for the nav --- */\r\n$chapters = [];\r\nif ($pdo) {\r\n    $chapters = $pdo->query(\r\n        \"SELECT id, slug, name, release_date FROM chards_chapters WHERE is_active = 1 ORDER BY id ASC\"\r\n    )->fetchAll();\r\n}\r\n\r\n/* --- resolve current chapter --- */\r\n$chapter_id = isset($_GET[\'chapter\']) ? (int)$_GET[\'chapter\'] : ($chapters[0][\'id\'] ?? 1);\r\n$current_chapter = null;\r\nforeach ($chapters as $ch) {\r\n    if ($ch[\'id\'] === $chapter_id) { $current_chapter = $ch; break; }\r\n}\r\n\r\n/* --- fetch all panels for this chapter, grouped by page --- */\r\n$pages = [];  /* $pages[page_number][panel_number] = panel row */\r\nif ($pdo && $current_chapter) {\r\n    $stmt = $pdo->prepare(\r\n        \"SELECT * FROM chards_story_page WHERE chapter_id = ? ORDER BY panel_page, panel_number\"\r\n    );\r\n    $stmt->execute([$chapter_id]);\r\n    foreach ($stmt->fetchAll() as $panel) {\r\n        $pages[$panel[\'panel_page\']][$panel[\'panel_number\']] = $panel;\r\n    }\r\n}\r\n\r\n$total_pages  = count($pages);\r\n$current_page = max(1, min((int)($_GET[\'page\'] ?? 1), $total_pages ?: 1));\r\n?>\r\n<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n<meta charset=\"UTF-8\">\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n<title>Chards — <?= htmlspecialchars($current_chapter[\'name\'] ?? \'Story\') ?></title>\r\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n<link href=\"https://fonts.googleapis.com/css2?family=Cinzel+Decorative:wght@400;700&family=Crimson+Pro:ital,wght@0,300;0,400;1,300&display=swap\" rel=\"stylesheet\">\r\n<style>\r\n  /* ── RESET & BASE ── */\r\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\r\n\r\n  :root {\r\n    --ink:        #0f0b08;\r\n    --parchment:  #f5efe0;\r\n    --aged:       #e8dcc8;\r\n    --gold:       #c9a84c;\r\n    --gold-dim:   #7a5f28;\r\n    --shadow:     rgba(0,0,0,0.55);\r\n    --found:      #f5efe0;\r\n    --locked-bg:  #2a2520;\r\n    --locked-num: rgba(201,168,76,0.65);\r\n    --panel-r:    4px;\r\n  }\r\n\r\n  html, body {\r\n    height: 100%;\r\n    background: var(--ink);\r\n    color: var(--parchment);\r\n    font-family: \'Crimson Pro\', Georgia, serif;\r\n    overflow: hidden; /* no scroll — book is viewport-sized */\r\n  }\r\n\r\n  /* ── BACKGROUND TEXTURE ── */\r\n  body::before {\r\n    content: \'\';\r\n    position: fixed; inset: 0; z-index: 0;\r\n    background:\r\n      radial-gradient(ellipse at 20% 50%, rgba(100,70,20,0.15) 0%, transparent 60%),\r\n      radial-gradient(ellipse at 80% 20%, rgba(80,50,10,0.12) 0%, transparent 55%);\r\n    pointer-events: none;\r\n  }\r\n\r\n  /* ── LAYOUT ── */\r\n  .story-wrap {\r\n    position: relative; z-index: 1;\r\n    display: flex; flex-direction: column;\r\n    height: 100vh; padding: 16px 12px 12px;\r\n    gap: 12px;\r\n  }\r\n\r\n  /* ── HEADER ── */\r\n  .story-header {\r\n    display: flex; align-items: center; justify-content: space-between;\r\n    flex-shrink: 0;\r\n  }\r\n\r\n  .story-title {\r\n    font-family: \'Cinzel Decorative\', serif;\r\n    font-size: clamp(13px, 2vw, 20px);\r\n    color: var(--gold);\r\n    letter-spacing: 0.06em;\r\n    text-shadow: 0 0 20px rgba(201,168,76,0.4);\r\n  }\r\n\r\n  /* chapter selector */\r\n  .chapter-nav {\r\n    display: flex; gap: 6px; flex-wrap: wrap; justify-content: flex-end;\r\n  }\r\n  .chapter-btn {\r\n    font-family: \'Crimson Pro\', serif;\r\n    font-size: 13px;\r\n    padding: 4px 12px;\r\n    border-radius: 20px;\r\n    border: 1px solid var(--gold-dim);\r\n    background: transparent;\r\n    color: var(--parchment);\r\n    cursor: pointer;\r\n    text-decoration: none;\r\n    transition: background 0.2s, color 0.2s;\r\n    opacity: 0.7;\r\n  }\r\n  .chapter-btn:hover, .chapter-btn.active {\r\n    background: var(--gold);\r\n    color: var(--ink);\r\n    opacity: 1;\r\n    border-color: var(--gold);\r\n  }\r\n\r\n  /* ── BOOK CONTAINER ── */\r\n  .book-wrap {\r\n    flex: 1;\r\n    display: flex; align-items: center; justify-content: center;\r\n    position: relative;\r\n    min-height: 0;\r\n  }\r\n\r\n  /* Arrow buttons */\r\n  .page-arrow {\r\n    position: absolute; top: 50%; transform: translateY(-50%);\r\n    z-index: 20;\r\n    width: 40px; height: 40px;\r\n    border-radius: 50%;\r\n    border: 1.5px solid rgba(201,168,76,0.35);\r\n    background: rgba(15,11,8,0.7);\r\n    color: var(--gold);\r\n    font-size: 20px;\r\n    display: flex; align-items: center; justify-content: center;\r\n    cursor: pointer;\r\n    transition: background 0.2s, border-color 0.2s;\r\n    user-select: none;\r\n  }\r\n  .page-arrow:hover { background: rgba(201,168,76,0.15); border-color: var(--gold); }\r\n  .page-arrow.prev { left: 4px; }\r\n  .page-arrow.next { right: 4px; }\r\n  .page-arrow:disabled { opacity: 0.2; cursor: default; pointer-events: none; }\r\n\r\n  /* Book itself */\r\n  .book {\r\n    position: relative;\r\n    width: min(calc(100vw - 100px), calc((100vh - 120px) * 0.78));\r\n    aspect-ratio: 3 / 4; /* matches 3x4 grid */\r\n    perspective: 1200px;\r\n  }\r\n\r\n  /* Page — only one shown at a time, transitions via class */\r\n  .book-page {\r\n    position: absolute; inset: 0;\r\n    display: grid;\r\n    grid-template-columns: repeat(3, 1fr);\r\n    grid-template-rows: repeat(4, 1fr);\r\n\r\n\r\n    overflow: hidden;\r\n    box-shadow:\r\n      0 8px 40px rgba(0,0,0,0.7),\r\n      0 0 0 1px rgba(201,168,76,0.15),\r\n      inset 0 0 60px rgba(0,0,0,0.3);\r\n    opacity: 0;\r\n    pointer-events: none;\r\n    transform: rotateY(8deg) scale(0.97);\r\n    transition: opacity 0.45s ease, transform 0.45s ease;\r\n    will-change: transform, opacity;\r\n  }\r\n  .book-page.active {\r\n    opacity: 1;\r\n    pointer-events: auto;\r\n    transform: rotateY(0deg) scale(1);\r\n  }\r\n  .book-page.exit-left {\r\n    opacity: 0;\r\n    transform: rotateY(-12deg) scale(0.95);\r\n  }\r\n  .book-page.exit-right {\r\n    opacity: 0;\r\n    transform: rotateY(12deg) scale(0.95);\r\n  }\r\n\r\n  /* ── PANEL ── */\r\n  .panel {\r\n    position: relative;\r\n    overflow: hidden;\r\n\r\n    cursor: default;\r\n  }\r\n\r\n  /* Found panel */\r\n  .panel.found {\r\n    cursor: pointer;\r\n    background: #000;\r\n  }\r\n  .panel.found img {\r\n    width: 100%; height: 100%;\r\n    object-fit: cover;\r\n    display: block;\r\n    transition: transform 0.3s ease, filter 0.3s ease;\r\n  }\r\n  .panel.found:hover img {\r\n    transform: scale(1.04);\r\n    filter: brightness(1.1);\r\n  }\r\n\r\n  /* Unfound panel */\r\n  .panel.locked {\r\n    background: var(--locked-bg);\r\n    display: flex; align-items: center; justify-content: center;\r\n    border: 1px solid rgba(255,255,255,0.04);\r\n  }\r\n  .panel-number { font-weight: 700;\r\n    font-family: \'Cinzel Decorative\', serif;\r\n    font-size: clamp(12px, 2.5vw, 22px);\r\n    color: var(--locked-num);\r\n    user-select: none;\r\n  }\r\n\r\n  /* ── PAGE INDICATOR ── */\r\n  .page-indicator {\r\n    flex-shrink: 0;\r\n    display: flex; align-items: center; justify-content: center; gap: 8px;\r\n  }\r\n  .page-dot {\r\n    width: 6px; height: 6px; border-radius: 50%;\r\n    background: var(--gold-dim);\r\n    transition: background 0.2s, transform 0.2s;\r\n  }\r\n  .page-dot.active {\r\n    background: var(--gold);\r\n    transform: scale(1.4);\r\n  }\r\n\r\n  /* ── LIGHTBOX ── */\r\n  #panel-lightbox {\r\n    display: none; position: fixed; inset: 0; z-index: 1000;\r\n    align-items: center; justify-content: center;\r\n    background: rgba(10,7,4,0.88);\r\n    cursor: pointer;\r\n    backdrop-filter: blur(4px);\r\n  }\r\n  #panel-lightbox.open { display: flex; }\r\n\r\n  .lb-panel {\r\n    position: relative;\r\n    width: min(380px, 88vw);\r\n    cursor: default;\r\n    animation: lbIn 0.35s cubic-bezier(0.34,1.4,0.64,1) forwards;\r\n  }\r\n  @keyframes lbIn {\r\n    from { transform: scale(0.7); opacity: 0; }\r\n    to   { transform: scale(1);   opacity: 1; }\r\n  }\r\n  .lb-panel.closing { animation: lbOut 0.22s ease forwards; }\r\n  @keyframes lbOut {\r\n    from { transform: scale(1);   opacity: 1; }\r\n    to   { transform: scale(0.7); opacity: 0; }\r\n  }\r\n\r\n  .lb-img-wrap {\r\n    width: 100%;\r\n    aspect-ratio: 3 / 4;\r\n    border-radius: 8px;\r\n    overflow: hidden;\r\n    box-shadow: 0 20px 60px rgba(0,0,0,0.8);\r\n  }\r\n  .lb-img-wrap img {\r\n    width: 100%; height: 100%; object-fit: cover; display: block;\r\n  }\r\n\r\n  .lb-info {\r\n    margin-top: 12px;\r\n    text-align: center;\r\n  }\r\n  .lb-card-name {\r\n    font-family: \'Cinzel Decorative\', serif;\r\n    font-size: 17px;\r\n    color: var(--gold);\r\n    margin-bottom: 6px;\r\n  }\r\n  .lb-finder {\r\n    font-size: 15px;\r\n    color: rgba(245,239,224,0.55);\r\n    font-style: italic;\r\n  }\r\n  .lb-finder strong {\r\n    color: var(--parchment);\r\n    font-style: normal;\r\n  }\r\n  .lb-found-date {\r\n    font-size: 13px;\r\n    color: rgba(245,239,224,0.3);\r\n    margin-top: 3px;\r\n  }\r\n\r\n  .lb-close {\r\n    position: absolute; top: -12px; right: -12px;\r\n    width: 30px; height: 30px; border-radius: 50%;\r\n    background: rgba(15,11,8,0.9);\r\n    border: 1.5px solid rgba(201,168,76,0.3);\r\n    color: var(--gold);\r\n    font-size: 14px;\r\n    display: flex; align-items: center; justify-content: center;\r\n    cursor: pointer; z-index: 2;\r\n    transition: background 0.2s;\r\n  }\r\n  .lb-close:hover { background: rgba(201,168,76,0.2); }\r\n\r\n  /* no pages state */\r\n  .no-panels {\r\n    display: flex; align-items: center; justify-content: center;\r\n    height: 100%;\r\n    font-family: \'Cinzel Decorative\', serif;\r\n    font-size: 18px;\r\n    color: var(--gold-dim);\r\n    opacity: 0.6;\r\n  }\r\n</style>\r\n</head>\r\n<body>\r\n<div class=\"story-wrap\">\r\n\r\n  <!-- Header -->\r\n  <header class=\"story-header\">\r\n    <div class=\"story-title\">\r\n      <?= htmlspecialchars($current_chapter[\'name\'] ?? \'Chards — Story\') ?>\r\n    </div>\r\n	  <a href=\"/index.php/hub\" style=\"\r\n		  font-family: \'Crimson Pro\', serif;\r\n		  font-size: 13px;\r\n		  color: rgba(255,255,255,0.35);\r\n		  text-decoration: none;\r\n		  border: 1px solid rgba(255,255,255,0.1);\r\n		  border-radius: 20px;\r\n		  padding: 4px 14px;\r\n		  transition: color 0.2s, border-color 0.2s;\r\n		\" onmouseover=\"this.style.color=\'rgba(255,255,255,0.7)\';this.style.borderColor=\'rgba(255,255,255,0.3)\'\"\r\n		   onmouseout=\"this.style.color=\'rgba(255,255,255,0.35)\';this.style.borderColor=\'rgba(255,255,255,0.1)\'\">\r\n		  ⌂ Hub\r\n		</a>\r\n    <nav class=\"chapter-nav\">\r\n      <?php foreach ($chapters as $ch): ?>\r\n        <a href=\"?chapter=<?= $ch[\'id\'] ?>&page=1\"\r\n           class=\"chapter-btn <?= $ch[\'id\'] === $chapter_id ? \'active\' : \'\' ?>\">\r\n          <?= htmlspecialchars($ch[\'name\']) ?>\r\n        </a>\r\n      <?php endforeach; ?>\r\n    </nav>\r\n  </header>\r\n\r\n  <!-- Book -->\r\n  <div class=\"book-wrap\">\r\n    <button class=\"page-arrow prev\" id=\"btn-prev\" aria-label=\"Previous page\">&#8249;</button>\r\n\r\n    <div class=\"book\" id=\"book\">\r\n    <nav class=\"chapter-nav\">\r\n      <?php if (empty($pages)): ?>\r\n        <div class=\"no-panels\">No panels found for this chapter yet.</div>\r\n      <?php else: ?>\r\n        <?php foreach ($pages as $page_num => $panels): ?>\r\n          <div class=\"book-page <?= $page_num === $current_page ? \'active\' : \'\' ?>\"\r\n               data-page=\"<?= $page_num ?>\">\r\n            <?php for ($row = 1; $row <= 4; $row++): ?>\r\n              <?php for ($col = 1; $col <= 3; $col++): ?>\r\n                <?php\r\n                  $slot  = ($row - 1) * 3 + $col;  /* panel_number 1–12 */\r\n                  $panel = $panels[$slot] ?? null;\r\n                  $found = $panel && $panel[\'is_found\'];\r\n                ?>\r\n                <?php if ($found): ?>\r\n                  <div class=\"panel found\"\r\n                       data-name=\"<?= htmlspecialchars($panel[\'card_name\']) ?>\"\r\n                       data-img=\"<?= htmlspecialchars($panel[\'image_url\']) ?>\"\r\n                       data-finder=\"<?= htmlspecialchars($panel[\'finder_name\']) ?>\"\r\n                       data-found-at=\"<?= htmlspecialchars($panel[\'found_at\']) ?>\"\r\n                       data-panel=\"<?= $slot ?>\">\r\n                    <img src=\"<?= htmlspecialchars($panel[\'image_url\']) ?>\"\r\n                         alt=\"Panel <?= $slot ?>\">\r\n                  </div>\r\n                <?php else: ?>\r\n                  <div class=\"panel locked\">\r\n                    <span class=\"panel-number\"><?= $slot ?></span>\r\n                  </div>\r\n                <?php endif; ?>\r\n              <?php endfor; ?>\r\n            <?php endfor; ?>\r\n          </div>\r\n        <?php endforeach; ?>\r\n      <?php endif; ?>\r\n    </div>\r\n\r\n    <button class=\"page-arrow next\" id=\"btn-next\" aria-label=\"Next page\">&#8250;</button>\r\n  </div>\r\n\r\n  <!-- Page dots -->\r\n  <div class=\"page-indicator\" id=\"page-dots\">\r\n    <?php for ($i = 1; $i <= $total_pages; $i++): ?>\r\n      <div class=\"page-dot <?= $i === $current_page ? \'active\' : \'\' ?>\"\r\n           data-page=\"<?= $i ?>\"></div>\r\n    <?php endfor; ?>\r\n  </div>\r\n\r\n</div>\r\n\r\n<!-- Lightbox -->\r\n<div id=\"panel-lightbox\">\r\n  <div class=\"lb-panel\" id=\"lb-panel\">\r\n    <div class=\"lb-close\" id=\"lb-close\">✕</div>\r\n    <div class=\"lb-img-wrap\">\r\n      <img id=\"lb-img\" src=\"\" alt=\"Panel\">\r\n    </div>\r\n    <div class=\"lb-info\">\r\n      <div class=\"lb-card-name\" id=\"lb-name\"></div>\r\n      <div class=\"lb-finder\">Discovered by <strong id=\"lb-finder\"></strong></div>\r\n      <div class=\"lb-found-date\" id=\"lb-date\"></div>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<script>\r\n  const TOTAL_PAGES  = <?= $total_pages ?: 0 ?>;\r\n  let currentPage    = <?= $current_page ?>;\r\n\r\n  /* ── PAGE NAVIGATION ── */\r\n  const bookEl   = document.getElementById(\'book\');\r\n  const btnPrev  = document.getElementById(\'btn-prev\');\r\n  const btnNext  = document.getElementById(\'btn-next\');\r\n  const dots     = document.querySelectorAll(\'.page-dot\');\r\n\r\n  function getPageEl(n) {\r\n    return bookEl.querySelector(`.book-page[data-page=\"${n}\"]`);\r\n  }\r\n\r\n  function goTo(n, direction) {\r\n    if (n < 1 || n > TOTAL_PAGES || n === currentPage) return;\r\n\r\n    const outClass = direction === \'next\' ? \'exit-left\' : \'exit-right\';\r\n    const current  = getPageEl(currentPage);\r\n    const next     = getPageEl(n);\r\n\r\n    /* exit current */\r\n    current.classList.remove(\'active\');\r\n    current.classList.add(outClass);\r\n    current.addEventListener(\'transitionend\', function h() {\r\n      current.classList.remove(outClass);\r\n      current.removeEventListener(\'transitionend\', h);\r\n    });\r\n\r\n    /* enter next from opposite side */\r\n    next.style.transform = direction === \'next\' ? \'rotateY(12deg) scale(0.97)\' : \'rotateY(-12deg) scale(0.97)\';\r\n    next.style.opacity   = \'0\';\r\n    next.style.pointerEvents = \'none\';\r\n    /* force reflow */\r\n    void next.offsetWidth;\r\n    next.style.transform = \'\';\r\n    next.style.opacity   = \'\';\r\n    next.classList.add(\'active\');\r\n\r\n    /* update dots */\r\n    dots.forEach(d => d.classList.toggle(\'active\', parseInt(d.dataset.page) === n));\r\n\r\n    currentPage = n;\r\n    updateArrows();\r\n\r\n    /* update URL without reload */\r\n    const url = new URL(window.location);\r\n    url.searchParams.set(\'page\', n);\r\n    history.replaceState(null, \'\', url);\r\n  }\r\n\r\n  function updateArrows() {\r\n    btnPrev.disabled = currentPage <= 1;\r\n    btnNext.disabled = currentPage >= TOTAL_PAGES;\r\n  }\r\n\r\n  btnPrev.addEventListener(\'click\', () => goTo(currentPage - 1, \'prev\'));\r\n  btnNext.addEventListener(\'click\', () => goTo(currentPage + 1, \'next\'));\r\n\r\n  dots.forEach(d => d.addEventListener(\'click\', () => {\r\n    const n = parseInt(d.dataset.page);\r\n    goTo(n, n > currentPage ? \'next\' : \'prev\');\r\n  }));\r\n\r\n  updateArrows();\r\n\r\n  /* ── SWIPE ── */\r\n  let swipeStartX = null;\r\n  const SWIPE_THRESHOLD = 50;\r\n\r\n  bookEl.addEventListener(\'pointerdown\', e => { swipeStartX = e.clientX; });\r\n  bookEl.addEventListener(\'pointerup\', e => {\r\n    if (swipeStartX === null) return;\r\n    const dx = e.clientX - swipeStartX;\r\n    swipeStartX = null;\r\n    if (Math.abs(dx) < SWIPE_THRESHOLD) return;\r\n    dx < 0 ? goTo(currentPage + 1, \'next\') : goTo(currentPage - 1, \'prev\');\r\n  });\r\n\r\n  /* ── LIGHTBOX ── */\r\n  const lightbox  = document.getElementById(\'panel-lightbox\');\r\n  const lbPanel   = document.getElementById(\'lb-panel\');\r\n  const lbImg     = document.getElementById(\'lb-img\');\r\n  const lbName    = document.getElementById(\'lb-name\');\r\n  const lbFinder  = document.getElementById(\'lb-finder\');\r\n  const lbDate    = document.getElementById(\'lb-date\');\r\n  const lbClose   = document.getElementById(\'lb-close\');\r\n\r\n  function openLightbox(panel) {\r\n    lbImg.src        = panel.dataset.img;\r\n    lbName.textContent   = panel.dataset.name;\r\n    lbFinder.textContent = panel.dataset.finder;\r\n\r\n    /* format the found_at date nicely */\r\n    const d = new Date(panel.dataset.foundAt);\r\n    lbDate.textContent = isNaN(d) ? \'\' : d.toLocaleDateString(\'en-GB\', {\r\n      day: \'numeric\', month: \'long\', year: \'numeric\'\r\n    });\r\n\r\n    lbPanel.classList.remove(\'closing\');\r\n    lightbox.classList.add(\'open\');\r\n  }\r\n\r\n  function closeLightbox() {\r\n    lbPanel.classList.add(\'closing\');\r\n    lbPanel.addEventListener(\'animationend\', function h() {\r\n      lightbox.classList.remove(\'open\');\r\n      lbPanel.classList.remove(\'closing\');\r\n      lbPanel.removeEventListener(\'animationend\', h);\r\n    });\r\n  }\r\n\r\n  /* delegate click to found panels */\r\n  bookEl.addEventListener(\'click\', e => {\r\n    const panel = e.target.closest(\'.panel.found\');\r\n    if (panel) openLightbox(panel);\r\n  });\r\n\r\n  lightbox.addEventListener(\'click\', e => { if (e.target === lightbox) closeLightbox(); });\r\n  lbClose.addEventListener(\'click\',  e => { e.stopPropagation(); closeLightbox(); });\r\n\r\n  /* keyboard: left/right arrows, escape */\r\n  document.addEventListener(\'keydown\', e => {\r\n    if (lightbox.classList.contains(\'open\')) {\r\n      if (e.key === \'Escape\') closeLightbox();\r\n      return;\r\n    }\r\n    if (e.key === \'ArrowRight\') goTo(currentPage + 1, \'next\');\r\n    if (e.key === \'ArrowLeft\')  goTo(currentPage - 1, \'prev\');\r\n  });\r\n</script>\r\n</body>\r\n</html>',	'storybook',	'',	'publish',	'closed',	'closed',	'',	'storybook',	'',	'',	'2026-07-27 19:13:35',	'2026-07-27 19:13:35',	'',	0,	'https://chards.wasmer.app/?post_type=wpcode&#038;p=135',	0,	'wpcode',	'',	0),
(136,	1,	'2026-05-04 19:44:24',	'2026-05-04 19:44:24',	'<?php\r\n/* ============================================================\r\n   CHARDS — Admin Page (Snippet B)\r\n   Story Cards + Collectibles + Fragmenta tabs.\r\n   Deploy via Code Snippets on a private WordPress page.\r\n   AJAX handlers live in Snippet A (Run Everywhere).\r\n============================================================ */\r\nchards_require_app_access(\'admin\');\r\n/* ── DB ── */\r\nif (!function_exists(\'chards_admin_db\')) {\r\n    function chards_admin_db() {\r\n        static $pdo;\r\n        if ($pdo) return $pdo;\r\n        try {\r\n            $pdo = new PDO(\r\n                \'mysql:host=db.fr-pari1.bengt.wasmernet.com;port=10272;dbname=dbGQr4derPM6nWoRL4jPwNPN;charset=utf8mb4\',\r\n                \'0074c9f9784980005ded7796ee74\',\r\n                \'06950074-c9fa-7db2-8000-c0aec36ba1ac\',\r\n                [\r\n                    PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,\r\n                    PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,\r\n                ]\r\n            );\r\n        } catch (PDOException $e) { $pdo = null; }\r\n        return $pdo;\r\n    }\r\n}\r\n\r\nif (defined(\'DOING_AJAX\') && DOING_AJAX) return;\r\n\r\n/* ── ACTIVE TAB ── */\r\n$active_tab = isset($_GET[\'tab\']) ? $_GET[\'tab\'] : \'cards\';\r\n\r\n/* ── FETCH SHARED DATA ── */\r\n$chapters = chards_admin_db()->query(\"SELECT * FROM chards_chapters ORDER BY id ASC\")->fetchAll();\r\n$rarities = chards_admin_db()->query(\"SELECT * FROM chards_rarities ORDER BY sort_order ASC\")->fetchAll();\r\n\r\n/* ── CARDS TAB DATA ── */\r\n$filter_chapter = isset($_GET[\'chapter\']) ? (int)$_GET[\'chapter\'] : ($chapters[0][\'id\'] ?? 0);\r\n$cards = [];\r\nif ($filter_chapter) {\r\n    $stmt = chards_admin_db()->prepare(\"\r\n        SELECT c.*, r.label AS rarity_label, r.color_hex\r\n        FROM chards_cards c\r\n        JOIN chards_rarities r ON r.id = c.rarity_id\r\n        WHERE c.card_type = \'story\' AND c.chapter_id = ?\r\n        ORDER BY c.panel_page, c.panel_number\r\n    \");\r\n    $stmt->execute([$filter_chapter]);\r\n    $cards = $stmt->fetchAll();\r\n}\r\n$editing = null;\r\nif (isset($_GET[\'edit\'])) {\r\n    $stmt = chards_admin_db()->prepare(\"SELECT * FROM chards_cards WHERE id = ? AND card_type = \'story\'\");\r\n    $stmt->execute([(int)$_GET[\'edit\']]);\r\n    $editing = $stmt->fetch();\r\n}\r\n$editing_collectible = null;\r\n$editing_tiers = [];\r\nif (isset($_GET[\'edit_coll\'])) {\r\n    $base_id = (int)$_GET[\'edit_coll\'];\r\n    $row = chards_admin_db()->prepare(\"SELECT * FROM chards_cards WHERE id = ?\");\r\n    $row->execute([$base_id]);\r\n    $card_row = $row->fetch();\r\n    if ($card_row) {\r\n        $root_id = $card_row[\'base_card_id\'] ?: $card_row[\'id\'];\r\n        $tier_stmt = chards_admin_db()->prepare(\"\r\n            SELECT c.*, r.label AS rarity_label, r.color_hex, r.sort_order AS rarity_order\r\n            FROM chards_cards c\r\n            JOIN chards_rarities r ON r.id = c.rarity_id\r\n            WHERE (c.id = ? OR c.base_card_id = ?) AND c.card_type = \'collectible\'\r\n            ORDER BY r.sort_order ASC\r\n        \");\r\n        $tier_stmt->execute([$root_id, $root_id]);\r\n        $editing_tiers = $tier_stmt->fetchAll();\r\n        $editing_collectible = $editing_tiers[0] ?? null;\r\n    }\r\n}\r\n\r\n/* ── FRAGMENTA TAB DATA ── */\r\n$frag_types = chards_admin_db()->query(\"\r\n    SELECT ft.*\r\n    FROM chards_fragmenta_types ft\r\n    ORDER BY ft.id ASC\r\n\")->fetchAll();\r\n\r\n$fragmenta = chards_admin_db()->query(\"\r\n    SELECT f.*, ft.name AS type_name, u.username AS owner_name\r\n    FROM chards_fragmenta f\r\n    LEFT JOIN chards_fragmenta_types ft ON ft.id = f.type_id\r\n    LEFT JOIN chards_users u            ON u.id  = f.owner_user_id\r\n    ORDER BY f.id DESC\r\n\")->fetchAll();\r\n\r\n$editing_type = null;\r\nif (isset($_GET[\'edit_type\'])) {\r\n    $stmt = chards_admin_db()->prepare(\"SELECT * FROM chards_fragmenta_types WHERE id = ?\");\r\n    $stmt->execute([(int)$_GET[\'edit_type\']]);\r\n    $editing_type = $stmt->fetch();\r\n}\r\n?>\r\n\r\n<style>\r\n#chards-admin *, #chards-admin *::before, #chards-admin *::after { box-sizing: border-box; }\r\n#chards-admin {\r\n  --bg:        #0d0b09;\r\n  --surface:   #151210;\r\n  --surface2:  #1e1a16;\r\n  --border:    rgba(201,168,76,0.15);\r\n  --border-hi: rgba(201,168,76,0.4);\r\n  --gold:      #c9a84c;\r\n  --gold-dim:  #7a5f28;\r\n  --parch:     #e8dcc8;\r\n  --muted:     rgba(232,220,200,0.45);\r\n  --ok:        #4a8c5c;\r\n  --err:       #8c4a4a;\r\n  --inp:       #0f0d0a;\r\n  --r:         6px;\r\n  font-family: \'Crimson Pro\', Georgia, serif;\r\n  font-size: 16px;\r\n  color: var(--parch);\r\n  background: var(--bg);\r\n  min-height: 80vh;\r\n  padding: 32px 24px;\r\n}\r\n#chards-admin .ca-layout {\r\n  display: grid;\r\n  grid-template-columns: 220px 1fr;\r\n  gap: 32px;\r\n  max-width: 1100px;\r\n  margin: 0 auto;\r\n}\r\n@media(max-width:700px){ #chards-admin .ca-layout { grid-template-columns: 1fr; } }\r\n\r\n/* sidebar */\r\n#chards-admin .ca-sidebar {\r\n  background: var(--surface); border: 1px solid var(--border);\r\n  border-radius: 8px; padding: 20px 0;\r\n  align-self: start; position: sticky; top: 80px;\r\n}\r\n#chards-admin .ca-logo {\r\n  font-family: \'Cinzel Decorative\', serif; font-size: 13px; color: var(--gold);\r\n  padding: 0 16px 16px; border-bottom: 1px solid var(--border);\r\n  margin-bottom: 12px; letter-spacing:.05em;\r\n}\r\n#chards-admin .ca-logo span { display:block; font-family:\'Crimson Pro\',serif; font-size:11px; color:var(--muted); margin-top:2px; }\r\n#chards-admin .ca-slabel { font-size:10px; letter-spacing:.12em; text-transform:uppercase; color:var(--gold-dim); padding:0 16px; margin-bottom:4px; }\r\n#chards-admin .ca-slink {\r\n  display:block; width:100%; padding:7px 16px;\r\n  font-family:\'Crimson Pro\',serif; font-size:14px;\r\n  color:var(--parch); background:transparent; border:none;\r\n  cursor:pointer; text-align:left; text-decoration:none;\r\n  opacity:.75; transition:background .15s,color .15s,opacity .15s;\r\n  border-left: 2px solid transparent;\r\n}\r\n#chards-admin .ca-slink:hover,\r\n#chards-admin .ca-slink.active { background:rgba(201,168,76,.1); color:var(--gold); opacity:1; border-left-color:var(--gold); }\r\n\r\n/* tab switcher */\r\n#chards-admin .ca-tabs {\r\n  display: flex; gap: 4px;\r\n  border-bottom: 1px solid var(--border);\r\n  margin-bottom: 28px;\r\n}\r\n#chards-admin .ca-tab {\r\n  font-family: \'Cinzel Decorative\', serif; font-size: 11px;\r\n  letter-spacing: .06em; color: var(--muted);\r\n  padding: 10px 18px; border: none; background: transparent;\r\n  cursor: pointer; border-bottom: 2px solid transparent;\r\n  margin-bottom: -1px; transition: color .15s, border-color .15s;\r\n  text-decoration: none; display: inline-block;\r\n}\r\n#chards-admin .ca-tab:hover { color: var(--parch); }\r\n#chards-admin .ca-tab.active { color: var(--gold); border-bottom-color: var(--gold); }\r\n\r\n/* main */\r\n#chards-admin .ca-main { min-width: 0; }\r\n#chards-admin .ca-title { font-family:\'Cinzel Decorative\',serif; font-size:17px; color:var(--gold); margin-bottom:2px; }\r\n#chards-admin .ca-sub   { font-size:13px; color:var(--muted); margin-bottom:24px; }\r\n\r\n/* message */\r\n#chards-admin .ca-msg { padding:10px 14px; border-radius:var(--r); font-size:14px; margin-bottom:18px; border-left:3px solid; }\r\n#chards-admin .ca-msg.ok   { background:rgba(74,140,92,.12);  border-color:var(--ok);  color:#8fcc9f; }\r\n#chards-admin .ca-msg.err  { background:rgba(140,74,74,.12);  border-color:var(--err); color:#cc8f8f; }\r\n#chards-admin .ca-msg.info { background:rgba(60,60,100,.12);  border-color:#5555aa;   color:#aaaadd; }\r\n\r\n/* progress */\r\n#chards-admin .ca-progress { display:flex; align-items:center; gap:10px; font-size:13px; color:var(--muted); margin-bottom:18px; }\r\n#chards-admin .ca-pbar     { flex:1; height:4px; background:var(--surface2); border-radius:2px; overflow:hidden; }\r\n#chards-admin .ca-pfill    { height:100%; background:linear-gradient(90deg,var(--gold-dim),var(--gold)); border-radius:2px; }\r\n\r\n/* card grid */\r\n#chards-admin .ca-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(120px,1fr)); gap:8px; margin-bottom:32px; }\r\n#chards-admin .ca-thumb { background:var(--surface2); border:1px solid var(--border); border-radius:var(--r); overflow:hidden; cursor:pointer; transition:border-color .2s,transform .2s; position:relative; text-decoration:none; display:block; }\r\n#chards-admin .ca-thumb:hover { border-color:var(--border-hi); transform:translateY(-2px); }\r\n#chards-admin .ca-thumb.editing { border-color:var(--gold); }\r\n#chards-admin .ca-thumb img { width:100%; aspect-ratio:3/4; object-fit:cover; display:block; }\r\n#chards-admin .ca-thumb-empty { width:100%; aspect-ratio:3/4; background:var(--inp); display:flex; align-items:center; justify-content:center; font-family:\'Cinzel Decorative\',serif; font-size:18px; color:var(--surface2); }\r\n#chards-admin .ca-thumb-info { padding:5px 7px; }\r\n#chards-admin .ca-thumb-slot { font-size:10px; color:var(--gold-dim); font-family:monospace; }\r\n#chards-admin .ca-thumb-name { font-size:11px; color:var(--parch); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }\r\n#chards-admin .ca-badge { position:absolute; top:4px; right:4px; font-size:9px; padding:2px 5px; border-radius:10px; font-family:monospace; }\r\n#chards-admin .badge-found   { background:rgba(74,140,92,.85);  color:#cfffd8; }\r\n#chards-admin .badge-missing { background:rgba(20,16,12,.85);   color:var(--muted); }\r\n\r\n/* form card */\r\n#chards-admin .ca-form { background:var(--surface); border:1px solid var(--border); border-radius:8px; padding:24px 28px; margin-bottom:32px; }\r\n#chards-admin .ca-form-title { font-family:\'Cinzel Decorative\',serif; font-size:12px; color:var(--gold); margin-bottom:18px; padding-bottom:10px; border-bottom:1px solid var(--border); }\r\n#chards-admin .ca-fgrid { display:grid; grid-template-columns:1fr 1fr; gap:12px 18px; }\r\n#chards-admin .ca-fgrid .full { grid-column:1/-1; }\r\n@media(max-width:600px){ #chards-admin .ca-fgrid { grid-template-columns:1fr; } #chards-admin .ca-fgrid .full { grid-column:1; } }\r\n#chards-admin .ca-field { display:flex; flex-direction:column; gap:4px; }\r\n#chards-admin .ca-field label { font-size:10px; letter-spacing:.1em; text-transform:uppercase; color:var(--gold-dim); }\r\n#chards-admin .ca-field input,\r\n#chards-admin .ca-field select,\r\n#chards-admin .ca-field textarea { background:var(--inp); border:1px solid var(--border); border-radius:var(--r); padding:7px 11px; color:var(--parch); font-family:\'Crimson Pro\',serif; font-size:15px; outline:none; width:100%; transition:border-color .15s; }\r\n#chards-admin .ca-field input:focus,\r\n#chards-admin .ca-field select:focus,\r\n#chards-admin .ca-field textarea:focus { border-color:var(--border-hi); }\r\n#chards-admin .ca-field textarea { resize:vertical; min-height:65px; }\r\n#chards-admin .ca-field select option { background:var(--surface2); }\r\n\r\n/* image preview */\r\n#chards-admin .ca-preview { margin-top:6px; width:72px; height:96px; border-radius:4px; overflow:hidden; border:1px solid var(--border); background:var(--inp); display:flex; align-items:center; justify-content:center; }\r\n#chards-admin .ca-preview img { width:100%; height:100%; object-fit:cover; display:block; }\r\n#chards-admin .ca-preview-empty { font-size:9px; color:var(--muted); text-align:center; padding:4px; }\r\n\r\n/* checkbox */\r\n#chards-admin .ca-check { display:flex; align-items:center; gap:8px; padding:10px 0; }\r\n#chards-admin .ca-check input { width:16px; height:16px; accent-color:var(--gold); cursor:pointer; }\r\n#chards-admin .ca-check label { font-size:14px; color:var(--parch); cursor:pointer; }\r\n\r\n/* buttons */\r\n#chards-admin .ca-btn-row { display:flex; gap:8px; margin-top:18px; flex-wrap:wrap; }\r\n#chards-admin .ca-btn { padding:9px 22px; border-radius:var(--r); cursor:pointer; border:none; font-family:\'Cinzel Decorative\',serif; font-size:11px; letter-spacing:.04em; transition:background .2s; text-decoration:none; display:inline-block; }\r\n#chards-admin .ca-btn-primary  { background:var(--gold); color:var(--bg); }\r\n#chards-admin .ca-btn-primary:hover { background:#d4b560; }\r\n#chards-admin .ca-btn-ghost    { background:transparent; border:1px solid var(--border); color:var(--muted); font-family:\'Crimson Pro\',serif; font-size:14px; }\r\n#chards-admin .ca-btn-ghost:hover { border-color:var(--border-hi); color:var(--parch); }\r\n#chards-admin .ca-btn-danger   { background:transparent; border:1px solid rgba(140,74,74,0.5); color:rgba(204,143,143,0.8); font-family:\'Crimson Pro\',serif; font-size:13px; padding:7px 16px; }\r\n#chards-admin .ca-btn-danger:hover { border-color:rgba(140,74,74,0.9); color:#cc8f8f; }\r\n#chards-admin .ca-btn-lock     { background:transparent; border:1px solid rgba(85,85,170,0.5); color:rgba(170,170,220,0.8); font-family:\'Crimson Pro\',serif; font-size:13px; padding:7px 16px; }\r\n#chards-admin .ca-btn-lock:hover { border-color:rgba(85,85,170,0.9); color:#aaaadd; }\r\n\r\n/* Fragmenta table */\r\n#chards-admin .ca-table { width:100%; border-collapse:collapse; font-size:14px; margin-bottom:8px; }\r\n#chards-admin .ca-table th { font-family:\'Cinzel Decorative\',serif; font-size:9px; letter-spacing:.1em; color:var(--gold-dim); text-transform:uppercase; padding:8px 10px; border-bottom:1px solid var(--border); text-align:left; }\r\n#chards-admin .ca-table td { padding:10px 10px; border-bottom:1px solid rgba(201,168,76,0.06); vertical-align:middle; }\r\n#chards-admin .ca-table tr:last-child td { border-bottom:none; }\r\n#chards-admin .ca-table tr:hover td { background:rgba(201,168,76,0.03); }\r\n#chards-admin .ca-uid { font-family:monospace; font-size:13px; color:var(--gold); letter-spacing:.04em; }\r\n#chards-admin .ca-pill { display:inline-block; font-size:10px; font-family:monospace; padding:2px 7px; border-radius:10px; }\r\n#chards-admin .pill-locked   { background:rgba(140,74,74,.2);  color:#cc8f8f; }\r\n#chards-admin .pill-unlocked { background:rgba(74,140,92,.2);  color:#8fcc9f; }\r\n#chards-admin .pill-unowned  { background:rgba(60,50,30,.4);   color:var(--muted); }\r\n\r\n/* Log drawer */\r\n#chards-admin .ca-log { background:var(--surface2); border:1px solid var(--border); border-radius:var(--r); padding:14px 16px; margin-top:8px; font-size:13px; display:none; }\r\n#chards-admin .ca-log.open { display:block; }\r\n#chards-admin .ca-log-row { display:flex; gap:12px; padding:5px 0; border-bottom:1px solid var(--border); }\r\n#chards-admin .ca-log-row:last-child { border-bottom:none; }\r\n#chards-admin .ca-log-time { color:var(--muted); font-family:monospace; font-size:11px; flex-shrink:0; }\r\n#chards-admin .ca-log-empty { color:var(--muted); font-style:italic; }\r\n</style>\r\n\r\n<link href=\"https://fonts.googleapis.com/css2?family=Cinzel+Decorative:wght@400;700&family=Crimson+Pro:ital,wght@0,300;0,400;1,300&display=swap\" rel=\"stylesheet\">\r\n\r\n<div id=\"chards-admin\">\r\n<div class=\"ca-layout\">\r\n\r\n  <!-- ── Sidebar ── -->\r\n  <aside class=\"ca-sidebar\">\r\n    <div class=\"ca-logo\">Chards <span>Admin Panel</span></div>\r\n\r\n    <?php if ($active_tab === \'cards\'): ?>\r\n    <div style=\"padding:0 0 8px\">\r\n      <div class=\"ca-slabel\">Chapters</div>\r\n      <?php foreach ($chapters as $ch): ?>\r\n        <a href=\"?tab=cards&chapter=<?= $ch[\'id\'] ?>\"\r\n           class=\"ca-slink <?= $ch[\'id\'] === $filter_chapter ? \'active\' : \'\' ?>\">\r\n          <?= htmlspecialchars($ch[\'name\']) ?>\r\n        </a>\r\n      <?php endforeach; ?>\r\n    </div>\r\n    <div style=\"padding:8px 0 0; border-top:1px solid var(--border); margin-top:8px\">\r\n      <div class=\"ca-slabel\">Actions</div>\r\n      <a href=\"#ca-add-card\"        class=\"ca-slink\">+ Add Story Card</a>\r\n      <a href=\"#ca-add-collectible\" class=\"ca-slink\">+ Add Collectible / Event</a>\r\n      <a href=\"#ca-add-chapter\"     class=\"ca-slink\">+ Add Chapter</a>\r\n    </div>\r\n    <?php elseif ($active_tab === \'fragmenta\'): ?>\r\n    <div style=\"padding:0 0 8px\">\r\n      <div class=\"ca-slabel\">Fragmenta</div>\r\n      <a href=\"#ca-frag-list\"      class=\"ca-slink\">NFC Cards</a>\r\n      <a href=\"#ca-register-frag\"  class=\"ca-slink\">+ Register Card</a>\r\n      <a href=\"#ca-frag-types\"     class=\"ca-slink\">Types</a>\r\n      <a href=\"#ca-add-frag-type\"  class=\"ca-slink\">+ Add Type</a>\r\n    </div>\r\n    <?php endif; ?>\r\n  </aside>\r\n\r\n  <!-- ── Main ── -->\r\n  <main class=\"ca-main\">\r\n\r\n    <!-- Tab switcher -->\r\n    <div class=\"ca-tabs\">\r\n      <a href=\"?tab=cards&chapter=<?= $filter_chapter ?>\"\r\n         class=\"ca-tab <?= $active_tab === \'cards\' ? \'active\' : \'\' ?>\">Story &amp; Cards</a>\r\n      <a href=\"?tab=fragmenta\"\r\n         class=\"ca-tab <?= $active_tab === \'fragmenta\' ? \'active\' : \'\' ?>\">Fragmenta</a>\r\n    </div>\r\n\r\n\r\n    <?php if ($active_tab === \'cards\'): /* ════════════ CARDS TAB ════════════ */ ?>\r\n\r\n      <!-- Card grid -->\r\n      <?php if ($filter_chapter && !empty($chapters)):\r\n        $ch_name = \'\';\r\n        foreach ($chapters as $ch) if ($ch[\'id\'] === $filter_chapter) $ch_name = $ch[\'name\'];\r\n        $found_count = count(array_filter($cards, fn($c) => !$c[\'is_available\']));\r\n        $pct         = count($cards) ? round($found_count / count($cards) * 100) : 0;\r\n      ?>\r\n        <div class=\"ca-title\"><?= htmlspecialchars($ch_name) ?></div>\r\n        <div class=\"ca-sub\">Story Cards &mdash; <?= count($cards) ?> total</div>\r\n        <div class=\"ca-progress\">\r\n          <span><?= $found_count ?> / <?= count($cards) ?> found</span>\r\n          <div class=\"ca-pbar\"><div class=\"ca-pfill\" style=\"width:<?= $pct ?>%\"></div></div>\r\n          <span><?= $pct ?>%</span>\r\n          <form method=\"POST\" action=\"\" style=\"margin:0\">\r\n            <input type=\"hidden\" name=\"action\" value=\"reset_finds\">\r\n            <input type=\"hidden\" name=\"reset_chapter_id\" value=\"<?= $filter_chapter ?>\">\r\n            <button type=\"button\" data-ca-reset=\"1\" class=\"ca-btn ca-btn-danger\" style=\"font-size:12px;padding:4px 12px\">\r\n              ↺ Reset Finds\r\n            </button>\r\n          </form>\r\n        </div>\r\n\r\n        <div class=\"ca-grid\">\r\n          <?php foreach ($cards as $card):\r\n            $is_coll   = $card[\'card_type\'] === \'collectible\';\r\n            $edit_url  = $is_coll\r\n              ? \"?tab=cards&chapter={$filter_chapter}&edit_coll={$card[\'id\']}#ca-edit-tiers\"\r\n              : \"?tab=cards&chapter={$filter_chapter}&edit={$card[\'id\']}#ca-edit-card\";\r\n            $is_editing = ($is_coll && isset($editing_collectible[\'id\']) && ($card[\'id\'] == $editing_collectible[\'id\'] || $card[\'base_card_id\'] == ($editing_collectible[\'base_card_id\'] ?: $editing_collectible[\'id\'])))\r\n              || (!$is_coll && isset($editing[\'id\']) && $editing[\'id\'] === $card[\'id\']);\r\n          ?>\r\n          <a href=\"<?= $edit_url ?>\" class=\"ca-thumb <?= $is_editing ? \'editing\' : \'\' ?>\">\r\n            <?php if ($card[\'image_url\']): ?>\r\n              <img src=\"<?= htmlspecialchars($card[\'image_url\']) ?>\" alt=\"Panel\" loading=\"lazy\">\r\n            <?php else: ?>\r\n              <div class=\"ca-thumb-empty\"><?= $card[\'panel_number\'] ?></div>\r\n            <?php endif; ?>\r\n            <span class=\"ca-badge <?= $card[\'is_available\'] ? \'badge-missing\' : \'badge-found\' ?>\">\r\n              <?= $card[\'is_available\'] ? \'OPEN\' : \'FOUND\' ?>\r\n            </span>\r\n            <div class=\"ca-thumb-info\">\r\n              <div class=\"ca-thumb-slot\">P<?= $card[\'panel_page\'] ?>&middot;<?= str_pad($card[\'panel_number\'],2,\'0\',STR_PAD_LEFT) ?></div>\r\n              <div class=\"ca-thumb-name\"><?= htmlspecialchars($card[\'name\']) ?></div>\r\n            </div>\r\n          </a>\r\n          <?php endforeach; ?>\r\n        </div>\r\n      <?php endif; ?>\r\n\r\n      <!-- Edit story card -->\r\n      <?php if ($editing): ?>\r\n      <div class=\"ca-form\" id=\"ca-edit-card\">\r\n        <div class=\"ca-form-title\">Edit Story Card &mdash; #<?= $editing[\'id\'] ?></div>\r\n        <form method=\"POST\" action=\"\" id=\"ca-form-edit-story\">\r\n          <input type=\"hidden\" name=\"action\"  value=\"edit_card\">\r\n          <input type=\"hidden\" name=\"card_id\" value=\"<?= $editing[\'id\'] ?>\">\r\n          <div class=\"ca-fgrid\">\r\n            <div class=\"ca-field full\"><label>Card Name</label><input type=\"text\" name=\"name\" value=\"<?= htmlspecialchars($editing[\'name\']) ?>\" required></div>\r\n            <div class=\"ca-field full\"><label>Description</label><textarea name=\"description\"><?= htmlspecialchars($editing[\'description\']) ?></textarea></div>\r\n            <div class=\"ca-field full\"><label>Flavour Text</label><textarea name=\"flavour_text\" style=\"min-height:50px\"><?= htmlspecialchars($editing[\'flavour_text\']) ?></textarea></div>\r\n            <div class=\"ca-field\">\r\n              <label>Chapter</label>\r\n              <select name=\"chapter_id\">\r\n                <?php foreach ($chapters as $ch): ?>\r\n                  <option value=\"<?= $ch[\'id\'] ?>\" <?= $ch[\'id\'] === (int)$editing[\'chapter_id\'] ? \'selected\' : \'\' ?>><?= htmlspecialchars($ch[\'name\']) ?></option>\r\n                <?php endforeach; ?>\r\n              </select>\r\n            </div>\r\n            <div class=\"ca-field\">\r\n              <label>Rarity</label>\r\n              <select name=\"rarity_id\">\r\n                <?php foreach ($rarities as $r): ?>\r\n                  <option value=\"<?= $r[\'id\'] ?>\" <?= $r[\'id\'] === (int)$editing[\'rarity_id\'] ? \'selected\' : \'\' ?>><?= htmlspecialchars($r[\'label\']) ?></option>\r\n                <?php endforeach; ?>\r\n              </select>\r\n            </div>\r\n            <div class=\"ca-field\"><label>Card Number</label><input type=\"number\" name=\"card_number\" value=\"<?= $editing[\'card_number\'] ?>\" min=\"1\"></div>\r\n            <div class=\"ca-field\"><label>Artist</label><input type=\"text\" name=\"artist\" value=\"<?= htmlspecialchars($editing[\'artist\'] ?? \'\') ?>\"></div>\r\n            <div class=\"ca-field\"><label>Panel Page</label><input type=\"number\" name=\"panel_page\" value=\"<?= $editing[\'panel_page\'] ?>\" min=\"1\"></div>\r\n            <div class=\"ca-field\"><label>Panel Number (1–12)</label><input type=\"number\" name=\"panel_number\" value=\"<?= $editing[\'panel_number\'] ?>\" min=\"1\" max=\"12\"></div>\r\n            <div class=\"ca-field full\">\r\n              <label>Image URL</label>\r\n              <input type=\"url\" name=\"image_url\" id=\"edit-img-url\" value=\"<?= htmlspecialchars($editing[\'image_url\']) ?>\">\r\n              <div class=\"ca-preview\">\r\n                <?php if ($editing[\'image_url\']): ?><img src=\"<?= htmlspecialchars($editing[\'image_url\']) ?>\" id=\"edit-img-preview\"><?php else: ?><span class=\"ca-preview-empty\">No image</span><?php endif; ?>\r\n              </div>\r\n            </div>\r\n            <div class=\"ca-field full\">\r\n              <div class=\"ca-check\">\r\n                <input type=\"checkbox\" name=\"is_active\" id=\"edit-active\" value=\"1\" <?= $editing[\'is_active\'] ? \'checked\' : \'\' ?>>\r\n                <label for=\"edit-active\">Active (visible in pack pool)</label>\r\n              </div>\r\n            </div>\r\n          </div>\r\n          <div class=\"ca-btn-row\">\r\n            <button type=\"button\" class=\"ca-btn ca-btn-primary\" data-ca-submit=\"ca-form-edit-story\" data-ca-sub=\"edit_card\" data-ca-msg=\"edit-story-msg\">Save Changes</button>\r\n            <a href=\"?tab=cards&chapter=<?= $filter_chapter ?>\" class=\"ca-btn ca-btn-ghost\">Cancel</a>\r\n          </div>\r\n          <div class=\"ca-msg\" id=\"edit-story-msg\" style=\"display:none\"></div>\r\n        </form>\r\n      </div>\r\n      <?php endif; ?>\r\n\r\n      <!-- Add story card -->\r\n      <div class=\"ca-form\" id=\"ca-add-card\">\r\n        <div class=\"ca-form-title\">Add New Story Card</div>\r\n        <form method=\"POST\" action=\"\" id=\"ca-form-add-story\">\r\n          <input type=\"hidden\" name=\"action\" value=\"add_card\">\r\n          <div class=\"ca-fgrid\">\r\n            <div class=\"ca-field full\"><label>Card Name</label><input type=\"text\" name=\"name\" placeholder=\"e.g. The Nightfall — Page 1, Panel 3\" required></div>\r\n            <div class=\"ca-field full\"><label>Description</label><textarea name=\"description\" placeholder=\"What is depicted in this panel?\"></textarea></div>\r\n            <div class=\"ca-field full\"><label>Flavour Text</label><textarea name=\"flavour_text\" style=\"min-height:50px\" placeholder=\"A quote or atmospheric line…\"></textarea></div>\r\n            <div class=\"ca-field\">\r\n              <label>Chapter</label>\r\n              <select name=\"chapter_id\">\r\n                <?php foreach ($chapters as $ch): ?><option value=\"<?= $ch[\'id\'] ?>\" <?= $ch[\'id\'] === $filter_chapter ? \'selected\' : \'\' ?>><?= htmlspecialchars($ch[\'name\']) ?></option><?php endforeach; ?>\r\n              </select>\r\n            </div>\r\n            <div class=\"ca-field\">\r\n              <label>Rarity</label>\r\n              <select name=\"rarity_id\">\r\n                <?php foreach ($rarities as $r): ?><option value=\"<?= $r[\'id\'] ?>\"><?= htmlspecialchars($r[\'label\']) ?></option><?php endforeach; ?>\r\n              </select>\r\n            </div>\r\n            <div class=\"ca-field\"><label>Card Number</label><input type=\"number\" name=\"card_number\" placeholder=\"1\" min=\"1\"></div>\r\n            <div class=\"ca-field\"><label>Artist</label><input type=\"text\" name=\"artist\" placeholder=\"Optional\"></div>\r\n            <div class=\"ca-field\"><label>Panel Page</label><input type=\"number\" name=\"panel_page\" placeholder=\"1\" min=\"1\" required></div>\r\n            <div class=\"ca-field\"><label>Panel Number (1–12)</label><input type=\"number\" name=\"panel_number\" placeholder=\"1\" min=\"1\" max=\"12\" required></div>\r\n            <div class=\"ca-field full\">\r\n              <label>Image URL</label>\r\n              <input type=\"url\" name=\"image_url\" id=\"add-img-url\" placeholder=\"https://...\" required>\r\n              <div class=\"ca-preview\" id=\"add-preview-wrap\"><span class=\"ca-preview-empty\">Preview</span></div>\r\n            </div>\r\n          </div>\r\n          <div class=\"ca-btn-row\">\r\n            <button type=\"button\" class=\"ca-btn ca-btn-primary\" data-ca-submit=\"ca-form-add-story\" data-ca-sub=\"add_card\" data-ca-msg=\"add-story-msg\">Add Card</button>\r\n          </div>\r\n          <div class=\"ca-msg\" id=\"add-story-msg\" style=\"display:none\"></div>\r\n        </form>\r\n      </div>\r\n\r\n      <!-- Tier editor -->\r\n      <?php if ($editing_collectible && !empty($editing_tiers)): ?>\r\n      <div class=\"ca-form\" id=\"ca-edit-tiers\">\r\n        <div class=\"ca-form-title\">Edit Tiers — <?= htmlspecialchars($editing_collectible[\'name\']) ?></div>\r\n        <div style=\"display:grid; gap:16px;\">\r\n          <?php foreach ($editing_tiers as $tier): ?>\r\n          <div style=\"background:var(--surface2);border:1px solid var(--border);border-radius:var(--r);padding:16px;border-left:3px solid <?= htmlspecialchars($tier[\'color_hex\'] ?? \'#c9a84c\') ?>\">\r\n            <div style=\"display:flex;gap:16px;align-items:flex-start;\">\r\n              <div style=\"flex-shrink:0\">\r\n                <div class=\"ca-preview\" id=\"tier-preview-<?= $tier[\'id\'] ?>\" style=\"width:60px;height:80px\">\r\n                  <?php if ($tier[\'image_url\']): ?><img src=\"<?= htmlspecialchars($tier[\'image_url\']) ?>\" id=\"tier-img-<?= $tier[\'id\'] ?>\"><?php else: ?><span class=\"ca-preview-empty\">No art</span><?php endif; ?>\r\n                </div>\r\n              </div>\r\n              <form method=\"POST\" action=\"\" id=\"ca-tier-form-<?= $tier[\'id\'] ?>\" style=\"flex:1;display:grid;grid-template-columns:1fr 1fr;gap:10px 16px;\">\r\n                <input type=\"hidden\" name=\"action\"  value=\"update_tier\">\r\n                <input type=\"hidden\" name=\"tier_id\" value=\"<?= $tier[\'id\'] ?>\">\r\n                <div style=\"grid-column:1/-1;display:flex;align-items:center;gap:10px;margin-bottom:4px\">\r\n                  <span style=\"font-family:\'Cinzel Decorative\',serif;font-size:11px;color:<?= htmlspecialchars($tier[\'color_hex\'] ?? \'#c9a84c\') ?>\"><?= htmlspecialchars($tier[\'rarity_label\']) ?></span>\r\n                  <?php if (!$tier[\'is_active\']): ?><span style=\"font-size:10px;color:var(--muted);font-family:monospace\">PLACEHOLDER</span><?php else: ?><span style=\"font-size:10px;color:#8fcc9f;font-family:monospace\">ACTIVE</span><?php endif; ?>\r\n                </div>\r\n                <div class=\"ca-field\" style=\"grid-column:1/-1\">\r\n                  <label>Image URL</label>\r\n                  <input type=\"url\" name=\"image_url\" id=\"tier-url-<?= $tier[\'id\'] ?>\" value=\"<?= htmlspecialchars($tier[\'image_url\']) ?>\" placeholder=\"https://...\">\r\n                </div>\r\n                <div style=\"grid-column:1/-1;display:flex;align-items:center;justify-content:space-between\">\r\n                  <div class=\"ca-check\">\r\n                    <input type=\"checkbox\" name=\"is_active\" id=\"tier-active-<?= $tier[\'id\'] ?>\" value=\"1\" <?= $tier[\'is_active\'] ? \'checked\' : \'\' ?>>\r\n                    <label for=\"tier-active-<?= $tier[\'id\'] ?>\">Active in pack pool</label>\r\n                  </div>\r\n                  <button type=\"button\" class=\"ca-btn ca-btn-primary\" style=\"padding:6px 16px;font-size:10px\"\r\n                          data-ca-submit=\"ca-tier-form-<?= $tier[\'id\'] ?>\" data-ca-sub=\"update_tier\" data-ca-msg=\"tier-msg-<?= $tier[\'id\'] ?>\">Save</button>\r\n                </div>\r\n                <div class=\"ca-msg\" id=\"tier-msg-<?= $tier[\'id\'] ?>\" style=\"display:none;grid-column:1/-1;margin-top:4px\"></div>\r\n              </form>\r\n            </div>\r\n          </div>\r\n          <?php endforeach; ?>\r\n        </div>\r\n        <div class=\"ca-btn-row\" style=\"margin-top:16px\">\r\n          <a href=\"?tab=cards&chapter=<?= $filter_chapter ?>\" class=\"ca-btn ca-btn-ghost\">Close</a>\r\n        </div>\r\n      </div>\r\n      <?php endif; ?>\r\n\r\n      <!-- Add collectible / event -->\r\n      <div class=\"ca-form\" id=\"ca-add-collectible\">\r\n        <div class=\"ca-form-title\">Add Collectible / Event Card</div>\r\n        <form method=\"POST\" action=\"\" id=\"ca-form-add-coll\">\r\n          <input type=\"hidden\" name=\"action\" value=\"add_collectible\">\r\n          <div class=\"ca-fgrid\">\r\n            <div class=\"ca-field full\"><label>Card Name</label><input type=\"text\" name=\"name\" placeholder=\"e.g. Kael, the Fragment Bearer\" required></div>\r\n            <div class=\"ca-field full\"><label>Description</label><textarea name=\"description\" placeholder=\"Who or what is depicted?\"></textarea></div>\r\n            <div class=\"ca-field full\"><label>Flavour Text</label><textarea name=\"flavour_text\" style=\"min-height:50px\" placeholder=\"An atmospheric quote…\"></textarea></div>\r\n            <div class=\"ca-field\">\r\n              <label>Card Type</label>\r\n              <select name=\"card_type\" id=\"coll-type\">\r\n                <option value=\"collectible\">Collectible</option>\r\n                <option value=\"event\">Event</option>\r\n              </select>\r\n            </div>\r\n            <div class=\"ca-field\">\r\n              <label>Chapter</label>\r\n              <select name=\"chapter_id\">\r\n                <?php foreach ($chapters as $ch): ?><option value=\"<?= $ch[\'id\'] ?>\" <?= $ch[\'id\'] === $filter_chapter ? \'selected\' : \'\' ?>><?= htmlspecialchars($ch[\'name\']) ?></option><?php endforeach; ?>\r\n              </select>\r\n            </div>\r\n            <div class=\"ca-field\">\r\n              <label>Rarity</label>\r\n              <select name=\"rarity_id\">\r\n                <?php foreach ($rarities as $r): ?><option value=\"<?= $r[\'id\'] ?>\" style=\"color:<?= htmlspecialchars($r[\'color_hex\'] ?? \'#e8dcc8\') ?>\"><?= htmlspecialchars($r[\'label\']) ?></option><?php endforeach; ?>\r\n              </select>\r\n            </div>\r\n            <div class=\"ca-field\"><label>Card Number (optional)</label><input type=\"number\" name=\"card_number\" placeholder=\"e.g. 42\" min=\"1\"></div>\r\n            <div class=\"ca-field\"><label>Print Run (blank = unlimited)</label><input type=\"number\" name=\"print_run\" placeholder=\"Leave blank for unlimited\" min=\"1\"></div>\r\n            <div class=\"ca-field\"><label>Artist</label><input type=\"text\" name=\"artist\" placeholder=\"Optional\"></div>\r\n            <div class=\"ca-field full\">\r\n              <label>Image URL</label>\r\n              <input type=\"url\" name=\"image_url\" id=\"coll-img-url\" placeholder=\"https://...\" required>\r\n              <div class=\"ca-preview\" id=\"coll-preview-wrap\"><span class=\"ca-preview-empty\">Preview</span></div>\r\n            </div>\r\n          </div>\r\n          <div class=\"ca-btn-row\">\r\n            <button type=\"button\" class=\"ca-btn ca-btn-primary\" data-ca-submit=\"ca-form-add-coll\" data-ca-sub=\"add_collectible\" data-ca-msg=\"add-coll-msg\">Add Card</button>\r\n          </div>\r\n          <div class=\"ca-msg\" id=\"add-coll-msg\" style=\"display:none\"></div>\r\n        </form>\r\n      </div>\r\n\r\n      <!-- Add chapter -->\r\n      <div class=\"ca-form\" id=\"ca-add-chapter\">\r\n        <div class=\"ca-form-title\">Add New Chapter</div>\r\n        <form method=\"POST\" action=\"\" id=\"ca-form-add-chapter\">\r\n          <input type=\"hidden\" name=\"action\" value=\"add_chapter\">\r\n          <div class=\"ca-fgrid\">\r\n            <div class=\"ca-field full\"><label>Chapter Name</label><input type=\"text\" name=\"chapter_name\" placeholder=\"e.g. Chapter 1: The Nightfall\" required></div>\r\n            <div class=\"ca-field\"><label>Release Date</label><input type=\"date\" name=\"release_date\"></div>\r\n            <div class=\"ca-field\">\r\n              <div class=\"ca-check\" style=\"padding-top:22px\">\r\n                <input type=\"checkbox\" name=\"is_active\" id=\"ch-active\" value=\"1\">\r\n                <label for=\"ch-active\">Active (packs available now)</label>\r\n              </div>\r\n            </div>\r\n          </div>\r\n          <div class=\"ca-btn-row\">\r\n            <button type=\"button\" class=\"ca-btn ca-btn-primary\" data-ca-submit=\"ca-form-add-chapter\" data-ca-sub=\"add_chapter\" data-ca-msg=\"add-chapter-msg\">Add Chapter</button>\r\n          </div>\r\n          <div class=\"ca-msg\" id=\"add-chapter-msg\" style=\"display:none\"></div>\r\n        </form>\r\n      </div>\r\n\r\n\r\n    <?php elseif ($active_tab === \'fragmenta\'): /* ════════════ FRAGMENTA TAB ════════════ */ ?>\r\n\r\n      <div class=\"ca-title\">Fragmenta</div>\r\n      <div class=\"ca-sub\">NFC Cards &amp; Types &mdash; <?= count($fragmenta) ?> registered</div>\r\n\r\n      <!-- ── Fragmenta list ── -->\r\n      <div class=\"ca-form\" id=\"ca-frag-list\">\r\n        <div class=\"ca-form-title\">Registered Fragmenta</div>\r\n        <?php if (empty($fragmenta)): ?>\r\n          <p style=\"color:var(--muted);font-size:14px\">No Fragmenta registered yet.</p>\r\n        <?php else: ?>\r\n        <div style=\"overflow-x:auto\">\r\n          <table class=\"ca-table\">\r\n            <thead>\r\n              <tr>\r\n                <th>UID</th>\r\n                <th>Type</th>\r\n                <th>Owner</th>\r\n                <th>Status</th>\r\n                <th>Last Used</th>\r\n                <th>Actions</th>\r\n              </tr>\r\n            </thead>\r\n            <tbody>\r\n              <?php foreach ($fragmenta as $f): ?>\r\n              <tr id=\"frag-row-<?= $f[\'id\'] ?>\">\r\n                <td><span class=\"ca-uid\"><?= htmlspecialchars($f[\'uid\']) ?></span></td>\r\n                <td style=\"font-size:13px\"><?= htmlspecialchars($f[\'type_name\'] ?? \'—\') ?></td>\r\n                <td style=\"font-size:13px;color:var(--muted)\"><?= $f[\'owner_name\'] ? htmlspecialchars($f[\'owner_name\']) : \'<span style=\"opacity:.5\">Unassigned</span>\' ?></td>\r\n                <td>\r\n                  <span class=\"ca-pill <?= $f[\'is_locked\'] ? \'pill-locked\' : \'pill-unlocked\' ?>\"\r\n                        id=\"frag-status-<?= $f[\'id\'] ?>\">\r\n                    <?= $f[\'is_locked\'] ? \'Locked\' : \'Active\' ?>\r\n                  </span>\r\n                </td>\r\n                <td style=\"font-size:12px;font-family:monospace;color:var(--muted)\">\r\n                  <?= $f[\'last_used_at\'] ? htmlspecialchars($f[\'last_used_at\']) : \'—\' ?>\r\n                </td>\r\n                <td>\r\n                  <div style=\"display:flex;gap:6px;flex-wrap:wrap\">\r\n                    <button class=\"ca-btn ca-btn-lock\"\r\n                            onclick=\"toggleLock(<?= $f[\'id\'] ?>, this)\"\r\n                            id=\"frag-lock-btn-<?= $f[\'id\'] ?>\">\r\n                      <?= $f[\'is_locked\'] ? \'Unlock\' : \'Lock\' ?>\r\n                    </button>\r\n                    <button class=\"ca-btn ca-btn-ghost\" style=\"font-size:12px;padding:5px 12px\"\r\n                            onclick=\"toggleLog(<?= $f[\'id\'] ?>)\">\r\n                      Log\r\n                    </button>\r\n                    <button class=\"ca-btn ca-btn-danger\"\r\n                            onclick=\"deleteFragmenta(<?= $f[\'id\'] ?>, \'<?= htmlspecialchars(addslashes($f[\'uid\'])) ?>\')\">\r\n                      Delete\r\n                    </button>\r\n                  </div>\r\n                  <!-- inline log drawer -->\r\n                  <div class=\"ca-log\" id=\"frag-log-<?= $f[\'id\'] ?>\">\r\n                    <div style=\"font-size:11px;color:var(--gold-dim);margin-bottom:8px;font-family:\'Cinzel Decorative\',serif;letter-spacing:.06em\">PACK OPEN LOG</div>\r\n                    <div id=\"frag-log-body-<?= $f[\'id\'] ?>\">\r\n                      <span class=\"ca-log-empty\">Loading…</span>\r\n                    </div>\r\n                  </div>\r\n                </td>\r\n              </tr>\r\n              <?php endforeach; ?>\r\n            </tbody>\r\n          </table>\r\n        </div>\r\n        <?php endif; ?>\r\n      </div>\r\n\r\n      <!-- ── Register new Fragmenta ── -->\r\n      <div class=\"ca-form\" id=\"ca-register-frag\">\r\n        <div class=\"ca-form-title\">Register New Fragmenta</div>\r\n        <form method=\"POST\" action=\"\" id=\"ca-form-register-frag\">\r\n          <input type=\"hidden\" name=\"action\" value=\"register_fragmenta\">\r\n          <div class=\"ca-fgrid\">\r\n            <div class=\"ca-field full\">\r\n			  <label>NFC UID</label>\r\n			  <div style=\"display:flex;gap:8px;align-items:flex-start;flex-direction:column;width:100%\">\r\n				<div style=\"display:flex;gap:8px;width:100%\">\r\n				  <input type=\"text\" name=\"uid\" id=\"frag-uid-input\"\r\n						 placeholder=\"e.g. 04:A3:B2:1F or tap Generate\"\r\n						 required style=\"font-family:monospace;flex:1\">\r\n				  <button type=\"button\" class=\"ca-btn ca-btn-ghost\"\r\n						  style=\"flex-shrink:0;white-space:nowrap\"\r\n							id=\"frag-uid-generate\">⟳ Generate</button>\r\n					<button type=\"button\" class=\"ca-btn ca-btn-ghost\"\r\n							id=\"frag-uid-copy\"\r\n							style=\"flex-shrink:0;white-space:nowrap;display:none\">⎘ Copy</button>\r\n				</div>\r\n			  </div>\r\n			</div>\r\n            <div class=\"ca-field full\">\r\n              <label>Fragmenta Type</label>\r\n              <select name=\"type_id\" required>\r\n                <option value=\"\">— Select type —</option>\r\n                <?php foreach ($frag_types as $ft): ?>\r\n                  <option value=\"<?= $ft[\'id\'] ?>\">\r\n                    <?= htmlspecialchars($ft[\'name\']) ?>\r\n                    (<?= $ft[\'cooldown_minutes\'] ?>min · <?= $ft[\'cards_per_pack\'] ?> cards · <?= ($ft[\'story_chance\'] * 100) ?>% story)\r\n                  </option>\r\n                <?php endforeach; ?>\r\n              </select>\r\n            </div>\r\n          </div>\r\n          <div class=\"ca-btn-row\">\r\n            <button type=\"button\" class=\"ca-btn ca-btn-primary\"\r\n                    data-ca-submit=\"ca-form-register-frag\" data-ca-sub=\"register_fragmenta\" data-ca-msg=\"register-frag-msg\">\r\n              Register\r\n            </button>\r\n          </div>\r\n          <div class=\"ca-msg\" id=\"register-frag-msg\" style=\"display:none\"></div>\r\n        </form>\r\n      </div>\r\n\r\n      <!-- ── Fragmenta Types list ── -->\r\n      <div class=\"ca-form\" id=\"ca-frag-types\">\r\n        <div class=\"ca-form-title\">Fragmenta Types</div>\r\n        <?php if (empty($frag_types)): ?>\r\n          <p style=\"color:var(--muted);font-size:14px\">No types defined yet.</p>\r\n        <?php else: ?>\r\n        <div style=\"overflow-x:auto\">\r\n          <table class=\"ca-table\">\r\n            <thead>\r\n              <tr>\r\n                <th>Name</th>\r\n                <th>Cooldown</th>\r\n                <th>Cards / Pack</th>\r\n                <th>Story Chance</th>\r\n                <th>Min Rarity</th>\r\n                <th>Actions</th>\r\n              </tr>\r\n            </thead>\r\n            <tbody>\r\n              <?php foreach ($frag_types as $ft): ?>\r\n              <tr id=\"type-row-<?= $ft[\'id\'] ?>\">\r\n                <td style=\"font-weight:600\"><?= htmlspecialchars($ft[\'name\']) ?></td>\r\n                <td style=\"font-family:monospace;font-size:13px\"><?= $ft[\'cooldown_minutes\'] ?>m</td>\r\n                <td style=\"font-family:monospace;font-size:13px\"><?= $ft[\'cards_per_pack\'] ?></td>\r\n                <td style=\"font-family:monospace;font-size:13px\"><?= ($ft[\'story_chance\'] * 100) ?>%</td>\r\n                <td style=\"font-size:13px;color:var(--muted)\"><?= htmlspecialchars($ft[\'minimum_rarity\'] ?? \'—\') ?></td>\r\n                <td>\r\n                  <div style=\"display:flex;gap:6px\">\r\n                    <a href=\"?tab=fragmenta&edit_type=<?= $ft[\'id\'] ?>#ca-add-frag-type\"\r\n                       class=\"ca-btn ca-btn-ghost\" style=\"font-size:12px;padding:5px 12px\">Edit</a>\r\n                    <button class=\"ca-btn ca-btn-danger\"\r\n                            onclick=\"deleteType(<?= $ft[\'id\'] ?>, \'<?= htmlspecialchars(addslashes($ft[\'name\'])) ?>\')\">\r\n                      Delete\r\n                    </button>\r\n                  </div>\r\n                </td>\r\n              </tr>\r\n              <?php endforeach; ?>\r\n            </tbody>\r\n          </table>\r\n        </div>\r\n        <?php endif; ?>\r\n      </div>\r\n\r\n      <!-- ── Add / Edit Fragmenta Type ── -->\r\n      <div class=\"ca-form\" id=\"ca-add-frag-type\">\r\n        <div class=\"ca-form-title\">\r\n          <?= $editing_type ? \'Edit Type — \' . htmlspecialchars($editing_type[\'name\']) : \'Add Fragmenta Type\' ?>\r\n        </div>\r\n        <form method=\"POST\" action=\"\" id=\"ca-form-frag-type\">\r\n          <input type=\"hidden\" name=\"action\" value=\"<?= $editing_type ? \'edit_fragmenta_type\' : \'add_fragmenta_type\' ?>\">\r\n          <?php if ($editing_type): ?>\r\n            <input type=\"hidden\" name=\"type_id\" value=\"<?= $editing_type[\'id\'] ?>\">\r\n          <?php endif; ?>\r\n          <div class=\"ca-fgrid\">\r\n            <div class=\"ca-field full\">\r\n              <label>Type Name</label>\r\n              <input type=\"text\" name=\"type_name\"\r\n                     value=\"<?= htmlspecialchars($editing_type[\'name\'] ?? \'\') ?>\"\r\n                     placeholder=\"e.g. Standard, Premium, Founder\" required>\r\n            </div>\r\n            <div class=\"ca-field\">\r\n              <label>Cooldown (minutes)</label>\r\n              <input type=\"number\" name=\"cooldown_minutes\" min=\"1\"\r\n                     value=\"<?= $editing_type[\'cooldown_minutes\'] ?? 420 ?>\"\r\n                     placeholder=\"420\" required>\r\n            </div>\r\n            <div class=\"ca-field\">\r\n              <label>Cards per Pack</label>\r\n              <input type=\"number\" name=\"cards_per_pack\" min=\"1\" max=\"20\"\r\n                     value=\"<?= $editing_type[\'cards_per_pack\'] ?? 5 ?>\"\r\n                     placeholder=\"5\" required>\r\n            </div>\r\n            <div class=\"ca-field\">\r\n              <label>Story Chance (0–1, e.g. 0.10 = 10%)</label>\r\n              <input type=\"number\" name=\"story_chance\" min=\"0\" max=\"1\" step=\"0.01\"\r\n                     value=\"<?= $editing_type[\'story_chance\'] ?? 0.10 ?>\"\r\n                     placeholder=\"0.10\" required>\r\n            </div>\r\n           <div class=\"ca-field\">\r\n			  <label>Minimum Rarity (integer threshold)</label>\r\n			  <input type=\"number\" name=\"minimum_rarity\" min=\"0\"\r\n					 value=\"<?= $editing_type[\'minimum_rarity\'] ?? 0 ?>\"\r\n					 placeholder=\"0 = no minimum\">\r\n			</div>\r\n          </div>\r\n          <div class=\"ca-btn-row\">\r\n            <button type=\"button\" class=\"ca-btn ca-btn-primary\"\r\n                    data-ca-submit=\"ca-form-frag-type\"\r\n                    data-ca-sub=\"<?= $editing_type ? \'edit_fragmenta_type\' : \'add_fragmenta_type\' ?>\"\r\n                    data-ca-msg=\"frag-type-msg\">\r\n              <?= $editing_type ? \'Save Changes\' : \'Add Type\' ?>\r\n            </button>\r\n            <?php if ($editing_type): ?>\r\n              <a href=\"?tab=fragmenta\" class=\"ca-btn ca-btn-ghost\">Cancel</a>\r\n            <?php endif; ?>\r\n          </div>\r\n          <div class=\"ca-msg\" id=\"frag-type-msg\" style=\"display:none\"></div>\r\n        </form>\r\n      </div>\r\n\r\n    <?php endif; /* end tab switch */ ?>\r\n\r\n  </main>\r\n</div>\r\n</div>\r\n\r\n',	'admin',	'',	'publish',	'closed',	'closed',	'',	'admin-login',	'',	'',	'2026-07-27 19:13:58',	'2026-07-27 19:13:58',	'',	0,	'https://chards.wasmer.app/?post_type=wpcode&#038;p=136',	0,	'wpcode',	'',	0),
(137,	1,	'2026-05-04 19:45:05',	'2026-05-04 19:45:05',	'<!-- wp:cover {\"url\":\"https://chards.wasmer.app/wp-content/uploads/2026/04/bg2-768x770-1.png\",\"id\":123,\"hasParallax\":true,\"dimRatio\":50,\"customOverlayColor\":\"#3d3b52\",\"isUserOverlayColor\":false,\"minHeight\":2071,\"minHeightUnit\":\"px\",\"contentPosition\":\"top center\",\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover has-parallax has-custom-content-position is-position-top-center\" style=\"min-height:2071px\"><div class=\"wp-block-cover__image-background wp-image-123 size-full has-parallax\" style=\"background-position:50% 50%;background-image:url(https://chards.wasmer.app/wp-content/uploads/2026/04/bg2-768x770-1.png)\"></div><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\" style=\"background-color:#3d3b52\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:spacer {\"height\":\"73px\"} -->\n<div style=\"height:73px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:shortcode -->\n[wpcode id=\"136\"]\n<!-- /wp:shortcode --></div></div>\n<!-- /wp:cover -->',	'settings page',	'',	'publish',	'closed',	'closed',	'',	'admin',	'',	'',	'2026-05-04 19:53:17',	'2026-05-04 19:53:17',	'',	0,	'https://chards.wasmer.app/?page_id=137',	0,	'page',	'',	0),
(140,	1,	'2026-05-10 06:48:32',	'2026-05-10 06:48:32',	'/* ============================================================\r\n   Chards — User & Fragmenta Helper Functions\r\n   Include this wherever pack opening logic runs.\r\n   All functions use the $pdo connection passed as argument.\r\n============================================================ */\r\n\r\n\r\n/* ============================================================\r\n   FREE ACCOUNT LIMITS (hardcoded — change here to adjust)\r\n============================================================ */\r\nif (!defined(\'FREE_COOLDOWN_MINUTES\')) define(\'FREE_COOLDOWN_MINUTES\', 1440);\r\nif (!defined(\'FREE_STORY_CHANCE\'))    define(\'FREE_STORY_CHANCE\',    0);\r\nif (!defined(\'FREE_CARDS_PER_PACK\'))  define(\'FREE_CARDS_PER_PACK\',  5);\r\n\r\n\r\n/* ============================================================\r\n   USER HELPERS\r\n============================================================ */\r\n\r\n/**\r\n * Find a user by username.\r\n */\r\nif (!function_exists(\'chards_get_user_by_username\')) {\r\nfunction chards_get_user_by_username($pdo, $username) {\r\n    $stmt = $pdo->prepare(\"SELECT * FROM chards_users WHERE username = ?\");\r\n    $stmt->execute([$username]);\r\n    return $stmt->fetch() ?: null;\r\n}\r\n}\r\n\r\n\r\n/**\r\n * Find a user by id.\r\n */\r\nif (!function_exists(\'chards_get_user\')) {\r\nfunction chards_get_user($pdo, $user_id) {\r\n    $stmt = $pdo->prepare(\"SELECT * FROM chards_users WHERE id = ?\");\r\n    $stmt->execute([$user_id]);\r\n    return $stmt->fetch() ?: null;\r\n}\r\n}\r\n\r\n\r\n/**\r\n * Register a new user. Returns new user id or throws on duplicate.\r\n */\r\nif (!function_exists(\'chards_register_user\')) {\r\n	function chards_register_user($pdo, $username, $password, $email) {\r\n		$token = bin2hex(random_bytes(32));\r\n		$stmt = $pdo->prepare(\"\r\n			INSERT INTO chards_users\r\n				(username, password_hash, email, is_active, email_verified, confirm_token, confirm_token_expiry)\r\n			VALUES (?, ?, ?, 1, 0, ?, DATE_ADD(NOW(), INTERVAL 24 HOUR))\r\n		\");\r\n		$stmt->execute([\r\n			$username,\r\n			password_hash($password, PASSWORD_BCRYPT),\r\n			strtolower(trim($email)),\r\n			$token,\r\n		]);\r\n		return [\r\n			\'id\'    => (int) $pdo->lastInsertId(),\r\n			\'token\' => $token,\r\n		];\r\n	}\r\n}\r\n\r\nif (!function_exists(\'chards_confirm_email\')) {\r\n	function chards_confirm_email($pdo, $token) {\r\n		$stmt = $pdo->prepare(\"\r\n			UPDATE chards_users\r\n			SET email_verified = 1, confirm_token = NULL, confirm_token_expiry = NULL\r\n			WHERE confirm_token = ?\r\n			  AND email_verified = 0\r\n			  AND confirm_token_expiry > NOW()\r\n		\");\r\n		$stmt->execute([$token]);\r\n		return $stmt->rowCount() > 0;\r\n	}\r\n}\r\n\r\n/**\r\n * Verify a user\'s password.\r\n */\r\nif (!function_exists(\'chards_verify_password\')) {\r\nfunction chards_verify_password($password, $hash) {\r\n    return password_verify($password, $hash);\r\n}\r\n}\r\n\r\n\r\n/**\r\n * Verify a user\'s PIN (for Fragmenta sharing).\r\n */\r\nif (!function_exists(\'chards_verify_pin\')) {\r\nfunction chards_verify_pin($pin, $hash) {\r\n    return password_verify($pin, $hash);\r\n}\r\n}\r\n\r\n\r\n/**\r\n * Set or update a user\'s PIN.\r\n */\r\nif (!function_exists(\'chards_set_pin\')) {\r\n	function chards_set_pin($pdo, $user_id, $pin) {\r\n		$pdo->prepare(\"UPDATE chards_users SET pin_hash = ? WHERE id = ?\")\r\n			->execute([password_hash($pin, PASSWORD_BCRYPT), $user_id]);\r\n	}\r\n}\r\n\r\n\r\n\r\n/* ============================================================\r\n   FRAGMENTA HELPERS\r\n============================================================ */\r\n\r\n/**\r\n * Look up a Fragmenta by its NFC UID.\r\n * Returns the Fragmenta row joined with its type.\r\n */\r\nif (!function_exists(\'chards_get_fragmenta_by_uid\')) {\r\nfunction chards_get_fragmenta_by_uid($pdo, $uid) {\r\n    $stmt = $pdo->prepare(\"\r\n        SELECT f.*,\r\n               ft.slug             AS type_slug,\r\n               ft.name             AS type_name,\r\n               ft.cooldown_minutes,\r\n               ft.cards_per_pack,\r\n               ft.story_chance,\r\n               ft.minimum_rarity\r\n        FROM chards_fragmenta f\r\n        JOIN chards_fragmenta_types ft ON ft.id = f.type_id\r\n        WHERE f.uid = ?\r\n    \");\r\n    $stmt->execute([$uid]);\r\n    return $stmt->fetch() ?: null;\r\n}\r\n}\r\n\r\n\r\n/**\r\n * Claim an unregistered Fragmenta for a user.\r\n * Returns true on success, false if already claimed.\r\n */\r\nif (!function_exists(\'chards_claim_fragmenta\')) {\r\nfunction chards_claim_fragmenta($pdo, $uid, $user_id) {\r\n    $stmt = $pdo->prepare(\"\r\n        UPDATE chards_fragmenta\r\n        SET owner_user_id = ?, registered_at = NOW()\r\n        WHERE uid = ? AND owner_user_id IS NULL\r\n    \");\r\n    $stmt->execute([$user_id, $uid]);\r\n    return $stmt->rowCount() > 0;\r\n}\r\n}\r\n\r\n\r\n/**\r\n * Check if a user is authorised to use a Fragmenta.\r\n *\r\n * Rules:\r\n *   - Owner can always use it (unless locked, in which case only owner can)\r\n *   - Non-owner can use it if is_locked = 0 AND they provide the owner\'s PIN\r\n *\r\n * Returns: \'owner\' | \'guest\' | \'locked\' | \'invalid_pin\' | \'unregistered\'\r\n */\r\nif (!function_exists(\'chards_check_fragmenta_access\')) {\r\nfunction chards_check_fragmenta_access($pdo, $fragmenta, $user_id, $pin = null) {\r\n    if ($fragmenta[\'owner_user_id\'] === null) return \'unregistered\';\r\n\r\n    $is_owner = (int)$fragmenta[\'owner_user_id\'] === $user_id;\r\n\r\n    if ($is_owner) return \'owner\';\r\n\r\n    /* Non-owner access */\r\n    if ($fragmenta[\'is_locked\']) return \'locked\';\r\n\r\n    /* Non-owner needs to supply owner\'s PIN */\r\n    $owner = chards_get_user($pdo, (int)$fragmenta[\'owner_user_id\']);\r\n    if (!$owner || !$owner[\'pin_hash\']) return \'no_pin_set\'; /* owner hasn\'t enabled sharing */\r\n\r\n    if ($pin === null || !chards_verify_pin($pin, $owner[\'pin_hash\'])) return \'invalid_pin\';\r\n\r\n    return \'guest\';\r\n}\r\n}\r\n\r\n\r\n\r\n/* ============================================================\r\n   PACK ALLOWANCE CHECKS\r\n============================================================ */\r\n\r\n/**\r\n * Check if a free (no Fragmenta) account can open a pack.\r\n * Free accounts have a 24h cooldown (FREE_COOLDOWN_MINUTES) between packs.\r\n *\r\n * Returns array:\r\n *   [\'allowed\' => bool, \'reason\' => string, \'resets_in\' => int (seconds)]\r\n */\r\nif (!function_exists(\'chards_free_can_open\')) {\r\nfunction chards_free_can_open($pdo, $user_id) {\r\n    $stmt = $pdo->prepare(\"\r\n        SELECT MAX(opened_at) FROM chards_pack_log\r\n        WHERE user_id      = ?\r\n          AND fragmenta_id IS NULL\r\n    \");\r\n    $stmt->execute([$user_id]);\r\n    $last_opened = $stmt->fetchColumn();\r\n\r\n    if (!$last_opened) {\r\n        return [\'allowed\' => true, \'reason\' => \'\', \'resets_in\' => 0];\r\n    }\r\n\r\n    $cooldown_secs = FREE_COOLDOWN_MINUTES * 60;\r\n    $next_open     = strtotime($last_opened) + $cooldown_secs;\r\n    $resets_in     = $next_open - time();\r\n\r\n    if ($resets_in > 0) {\r\n        return [\r\n            \'allowed\'   => false,\r\n            \'reason\'    => \'cooldown\',\r\n            \'resets_in\' => $resets_in,\r\n        ];\r\n    }\r\n\r\n    return [\'allowed\' => true, \'reason\' => \'\', \'resets_in\' => 0];\r\n}\r\n}\r\n\r\n\r\n/**\r\n * Check if a Fragmenta can be used for a pack opening.\r\n * The cooldown_minutes value IS the limit — no separate daily counter.\r\n *\r\n * Returns array:\r\n *   [\'allowed\' => bool, \'reason\' => string, \'resets_in\' => int (seconds)]\r\n */\r\nif (!function_exists(\'chards_fragmenta_can_open\')) {\r\nfunction chards_fragmenta_can_open($pdo, $fragmenta) {\r\n    $cooldown_secs = (int)$fragmenta[\'cooldown_minutes\'] * 60;\r\n\r\n    if (!$fragmenta[\'last_used_at\']) {\r\n        return [\'allowed\' => true, \'reason\' => \'\', \'resets_in\' => 0];\r\n    }\r\n\r\n    $last_used = strtotime($fragmenta[\'last_used_at\']);\r\n    $next_open = $last_used + $cooldown_secs;\r\n    $resets_in = $next_open - time();\r\n\r\n    if ($resets_in > 0) {\r\n        return [\r\n            \'allowed\'   => false,\r\n            \'reason\'    => \'cooldown\',\r\n            \'resets_in\' => $resets_in,\r\n        ];\r\n    }\r\n\r\n    return [\'allowed\' => true, \'reason\' => \'\', \'resets_in\' => 0];\r\n}\r\n}\r\n\r\n\r\n/**\r\n * Record a pack opening in the log and update Fragmenta last_used_at.\r\n * Call this immediately after a pack is generated.\r\n */\r\nif (!function_exists(\'chards_log_pack_open\')) {\r\nfunction chards_log_pack_open($pdo, $user_id, $pack_id, $fragmenta_id = null) {\r\n    $pdo->prepare(\"\r\n        INSERT INTO chards_pack_log (user_id, fragmenta_id, pack_id)\r\n        VALUES (?, ?, ?)\r\n    \")->execute([$user_id, $fragmenta_id, $pack_id]);\r\n\r\n    if ($fragmenta_id !== null) {\r\n        $pdo->prepare(\"\r\n            UPDATE chards_fragmenta SET last_used_at = NOW() WHERE id = ?\r\n        \")->execute([$fragmenta_id]);\r\n    }\r\n}\r\n}\r\n\r\n\r\n/**\r\n * Get all Fragmenta owned by a user, with type info.\r\n */\r\nif (!function_exists(\'chards_get_user_fragmenta\')) {\r\nfunction chards_get_user_fragmenta($pdo, $user_id) {\r\n    $stmt = $pdo->prepare(\"\r\n        SELECT f.*,\r\n               ft.name            AS type_name,\r\n               ft.cooldown_minutes,\r\n               ft.cards_per_pack,\r\n               ft.story_chance,\r\n               ft.minimum_rarity,\r\n               /* packs used on this Fragmenta in last 24h */\r\n               (SELECT COUNT(*) FROM chards_pack_log pl\r\n                WHERE pl.fragmenta_id = f.id\r\n                  AND pl.opened_at > NOW() - INTERVAL 24 HOUR) AS recent_packs\r\n        FROM chards_fragmenta f\r\n        JOIN chards_fragmenta_types ft ON ft.id = f.type_id\r\n        WHERE f.owner_user_id = ?\r\n        ORDER BY f.registered_at ASC\r\n    \");\r\n    $stmt->execute([$user_id]);\r\n    return $stmt->fetchAll();\r\n}\r\n}\r\n\r\n\r\n/**\r\n * Get the effective pack config for a session.\r\n * Pass $fragmenta = null for a free account.\r\n *\r\n * Returns array with all pack-opening parameters resolved.\r\n */\r\nif (!function_exists(\'chards_get_pack_config\')) {\r\nfunction chards_get_pack_config($fragmenta) {\r\n    if ($fragmenta === null) {\r\n        return [\r\n            \'cooldown_minutes\' => FREE_COOLDOWN_MINUTES,\r\n            \'cards_per_pack\'   => FREE_CARDS_PER_PACK,\r\n            \'story_chance\'     => FREE_STORY_CHANCE,\r\n            \'minimum_rarity\'   => 0,\r\n            \'is_free\'          => true,\r\n        ];\r\n    }\r\n    return [\r\n        \'cooldown_minutes\' => (int)$fragmenta[\'cooldown_minutes\'],\r\n        \'cards_per_pack\'   => (int)$fragmenta[\'cards_per_pack\'],\r\n        \'story_chance\'     => (int)$fragmenta[\'story_chance\'],\r\n        \'minimum_rarity\'   => (int)$fragmenta[\'minimum_rarity\'],\r\n        \'is_free\'          => false,\r\n    ];\r\n}\r\n}',	'user helper',	'',	'publish',	'closed',	'closed',	'',	'user-helper',	'',	'',	'2026-07-27 18:40:50',	'2026-07-27 18:40:50',	'',	0,	'https://chards.wasmer.app/?post_type=wpcode&#038;p=140',	0,	'wpcode',	'',	0),
(141,	1,	'2026-05-10 06:49:47',	'2026-05-10 06:49:47',	'<!-- wp:cover {\"url\":\"https://chards.wasmer.app/wp-content/uploads/2026/04/bg2-768x770-1.png\",\"id\":123,\"hasParallax\":true,\"dimRatio\":50,\"customOverlayColor\":\"#3d3b52\",\"isUserOverlayColor\":false,\"minHeight\":2071,\"minHeightUnit\":\"px\",\"contentPosition\":\"top center\",\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover has-parallax has-custom-content-position is-position-top-center\" style=\"min-height:2071px\"><div class=\"wp-block-cover__image-background wp-image-123 size-full has-parallax\" style=\"background-position:50% 50%;background-image:url(https://chards.wasmer.app/wp-content/uploads/2026/04/bg2-768x770-1.png)\"></div><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\" style=\"background-color:#3d3b52\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:spacer {\"height\":\"73px\"} -->\n<div style=\"height:73px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:shortcode -->\n[wpcode id=\"140\"]\n<!-- /wp:shortcode --></div></div>\n<!-- /wp:cover -->',	'user helper',	'',	'publish',	'closed',	'closed',	'',	'user-helper',	'',	'',	'2026-05-10 07:00:40',	'2026-05-10 07:00:40',	'',	0,	'https://chards.wasmer.app/?page_id=141',	0,	'page',	'',	0),
(143,	1,	'2026-05-10 07:55:14',	'2026-05-10 07:55:14',	'/* ============================================================\r\n   CHARDS — ARC Registration Dialogue (Login/Register)\r\n   Aldric Voss, Senior Registrar of the Aenephsy Regulation Compendium\r\n   \r\n   Scenarios handled:\r\n   A. No session, no NFC — standard login/register\r\n   B. No session, unassigned NFC — register + claim\r\n   C. No session, assigned NFC — login + borrow/claim\r\n   D. Logged in, unassigned NFC — claim card\r\n   E. Logged in, NFC assigned to someone else — borrow with PIN\r\n   F. Logged in, own NFC — redirect to pack opening (handled before this page loads)\r\n   \r\n   The NFC UID is read from \\$_SESSION[\'cardID\'] set by landing.php.\r\n   No UID = scenario A (standard login button).\r\n============================================================ */\r\n\r\nif (!session_id()) session_start();\r\n\r\nchards_require_app_access(\'login\');\r\n/* ── DB connection ── */\r\n$dsn = \'mysql:host=db.fr-pari1.bengt.wasmernet.com;port=10272;dbname=dbGQr4derPM6nWoRL4jPwNPN;charset=utf8mb4\';\r\ntry {\r\n    $pdo = new PDO($dsn, \'0074c9f9784980005ded7796ee74\', \'06950074-c9fa-7db2-8000-c0aec36ba1ac\', [\r\n        PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,\r\n        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,\r\n    ]);\r\n} catch (PDOException $e) {\r\n    $pdo = null;\r\n}\r\n\r\n/* ── Handle email confirmation link ── */\r\n$verify_result = null;\r\nif (isset($_GET[\'verify\']) && $pdo) {\r\n    $verify_result = chards_confirm_email($pdo, trim($_GET[\'verify\']));\r\n}\r\n\r\n/* ── Read scenario pre-computed by landing.php ── */\r\n$nfc_uid      = $_SESSION[\'cardID\']           ?? null;\r\n$scenario     = $_SESSION[\'arc_scenario\']     ?? \'A\';\r\n$fragmenta    = $_SESSION[\'arc_fragmenta\']    ?? null;\r\n$logged_in    = !empty($_SESSION[\'chards_user_id\']);\r\n$user_id      = $logged_in ? (int)$_SESSION[\'chards_user_id\'] : null;\r\n$username     = $logged_in ? ($_SESSION[\'chards_username\'] ?? null) : null;\r\n\r\n/* Guard: logged_in with no username means a corrupt/stale session — clear and bounce */\r\nif ($logged_in && $username === null) {\r\n    session_unset();\r\n    session_destroy();\r\n    setcookie(\'chards_remember\', \'\', time() - 3600, \'/\', \'\', true, true);\r\n    header(\'Location: /index.php/\');\r\n    exit;\r\n}\r\n$owner_username = $_SESSION[\'arc_fragmenta_owner\'] ?? \'\';\r\n\r\n/* Safety: scenario F and free should never reach this page\r\n   (landing.php redirects them directly) — but just in case */\r\nif ($scenario === \'F\' || ($logged_in && !$nfc_uid && $scenario === \'free\')) {\r\n    header(\'Location: /index.php/hub\');\r\n    exit;\r\n}\r\n\r\n/* ── Aldric\'s dialogue lines per scenario ── */\r\n$dialogues = [\r\n    \'A\' => [\r\n        \'greeting\'  => \"Ah. Another one. Please, do sit down — the process won\'t take long if you cooperate.\",\r\n        \'sub\'       => \"The ARC requires all citizens to be registered before accessing any Aenephsy-related services. Your name, if you please.\",\r\n        \'mode\'      => \'login_or_register\',\r\n    ],\r\n    \'B\' => [\r\n        \'greeting\'  => \"An unregistered Fragmenta. Again.\",\r\n        \'sub\'       => \"Do you have any idea how many incidents began with those exact words? This shard needs to be logged before it can be used. I\'ll need your details first — are you already registered with the ARC?\",\r\n        \'mode\'      => \'login_or_register_then_claim\',\r\n    ],\r\n    \'C\' => [\r\n        \'greeting\'  => \"This Fragmenta is already on record.\",\r\n        \'sub\'       => \"It is registered to \" . ($fragmenta[\'owner_user_id\'] ? \"another citizen\" : \"no one\") . \". Are you its registered owner, or are you borrowing it?\",\r\n        \'mode\'      => \'owner_or_borrow\',\r\n    ],\r\n    \'D\' => [\r\n        \'greeting\'  => \"Welcome back, \" . ($username ?? \'Citizen\') . \".\",\r\n        \'sub\'       => \"I see you\'ve brought an unregistered Fragmenta. Shall I log it under your name? Once registered, it cannot be transferred without ARC involvement.\",\r\n        \'mode\'      => \'claim_confirm\',\r\n    ],\r\n    \'E\' => [\r\n        \'greeting\'  => \"That Fragmenta belongs to another registered citizen.\",\r\n        \'sub\'       => \"If you have been granted temporary access, the owner will have provided you with a clearance PIN. Present it now.\",\r\n        \'mode\'      => \'pin_only\',\r\n    ],\r\n     \'no_pin_set\' => [\r\n        \'greeting\'  => \"This Fragmenta has not been cleared for shared access.\",\r\n        \'sub\'       => \"The registered owner has not configured a clearance PIN. Sharing cannot be authorised until they do so. If you are the owner, log in and set a PIN from your account settings.\",\r\n        \'mode\'      => \'no_sharing\',\r\n    ],\r\n    \'pin_manage\' => [\r\n        \'greeting\'  => \"Identity confirmed.\",\r\n        \'sub\'       => \"You may now set or update the clearance PIN for this Fragmenta. This PIN will be required by anyone borrowing your card.\",\r\n        \'mode\'      => \'pin_manage\',\r\n    ],\r\n    \'pin_remove\' => [\r\n        \'greeting\'  => \"Identity confirmed.\",\r\n        \'sub\'       => \"You are about to remove the clearance PIN from this Fragmenta. Once removed, no one will be able to borrow it until a new PIN is set.\",\r\n        \'mode\'      => \'pin_remove\',\r\n    ],\r\n    \'already_owned\' => [\r\n        \'greeting\'  => \"That Fragmenta is already registered to you.\",\r\n        \'sub\'       => \"There is nothing further to do here. Everything is in order.\",\r\n        \'mode\'      => \'no_sharing\',\r\n    ],\r\n    \'register_taken\' => [\r\n        \'greeting\'  => \"That Fragmenta is already registered to another citizen.\",\r\n        \'sub\'       => \"I cannot transfer registration without the current owner\'s involvement. If you believe this is an error, contact the ARC directly.\",\r\n        \'mode\'      => \'no_sharing\',\r\n    ],\r\n    \'pin_not_owner\' => [\r\n        \'greeting\'  => \"That Fragmenta does not belong to you.\",\r\n        \'sub\'       => \"PIN management is restricted to the registered owner only.\",\r\n        \'mode\'      => \'no_sharing\',\r\n    ],\r\n];\r\n\r\n$current = $dialogues[$scenario];\r\n/* owner_username already set from $_SESSION[\'arc_fragmenta_owner\'] above */\r\n?>\r\n\r\n<link href=\"https://fonts.googleapis.com/css2?family=Cinzel:wght@400;600&family=IM+Fell+English:ital@0;1&family=JetBrains+Mono:wght@400;500&display=swap\" rel=\"stylesheet\">\r\n\r\n<style>\r\n/* ── ALDRIC DIALOGUE PANEL ── */\r\n#arc-overlay {\r\n  position: fixed;\r\n  inset: 0;\r\n  z-index: 99998;\r\n  background: rgba(5, 3, 2, 0.75);\r\n  backdrop-filter: blur(3px);\r\n  opacity: 0;\r\n  pointer-events: none;\r\n  transition: opacity 0.4s ease;\r\n}\r\n#arc-overlay.open {\r\n  opacity: 1;\r\n  pointer-events: auto;\r\n}\r\n\r\n#arc-panel {\r\n  position: fixed;\r\n  top: 50%;\r\n  left: 50%;\r\n  transform: translateX(-50%) translateY(-50%) scale(0.95);\r\n  opacity: 0;\r\n  pointer-events: none;\r\n  width: min(480px, 95vw);\r\n  height: auto;\r\n  max-height: 90vh;\r\n  z-index: 99999;\r\n  background: #0e0b08;\r\n  border-right: 1px solid rgba(201,168,76,0.2);\r\n  box-shadow: 4px 0 40px rgba(0,0,0,0.7);\r\n  display: flex;\r\n  flex-direction: column;\r\n  transform: translateX(-100%);\r\n  transition: transform 0.35s cubic-bezier(0.34,1.4,0.64,1), opacity 0.35s ease;\r\n  overflow: hidden;\r\n}\r\n#arc-panel.open {\r\n  transform: translateX(-50%) translateY(-50%) scale(1);\r\n  opacity: 1;\r\n  pointer-events: auto;\r\n}\r\n\r\n/* Aged paper texture overlay */\r\n#arc-panel::before {\r\n  content: \'\';\r\n  position: absolute;\r\n  inset: 0;\r\n  background:\r\n    repeating-linear-gradient(\r\n      0deg,\r\n      transparent,\r\n      transparent 28px,\r\n      rgba(201,168,76,0.03) 28px,\r\n      rgba(201,168,76,0.03) 29px\r\n    );\r\n  pointer-events: none;\r\n  z-index: 0;\r\n}\r\n\r\n/* ARC header bar */\r\n.arc-header {\r\n  position: relative;\r\n  z-index: 1;\r\n  padding: 16px 20px 14px;\r\n  border-bottom: 1px solid rgba(201,168,76,0.15);\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  flex-shrink: 0;\r\n}\r\n.arc-logo {\r\n  font-family: \'Cinzel\', serif;\r\n  font-size: 11px;\r\n  letter-spacing: 0.2em;\r\n  color: rgba(201,168,76,0.6);\r\n  text-transform: uppercase;\r\n}\r\n.arc-logo span {\r\n  display: block;\r\n  font-size: 9px;\r\n  letter-spacing: 0.15em;\r\n  color: rgba(201,168,76,0.35);\r\n  margin-top: 2px;\r\n}\r\n.arc-close {\r\n  width: 28px; height: 28px;\r\n  border-radius: 50%;\r\n  border: 1px solid rgba(201,168,76,0.2);\r\n  background: transparent;\r\n  color: rgba(201,168,76,0.5);\r\n  font-size: 14px;\r\n  cursor: pointer;\r\n  display: flex; align-items: center; justify-content: center;\r\n  transition: border-color 0.2s, color 0.2s;\r\n}\r\n.arc-close:hover {\r\n  border-color: rgba(201,168,76,0.5);\r\n  color: rgba(201,168,76,0.9);\r\n}\r\n\r\n/* Character section */\r\n.arc-character {\r\n  position: relative;\r\n  z-index: 1;\r\n  display: flex;\r\n  gap: 16px;\r\n  padding: 20px 20px 0;\r\n  flex-shrink: 0;\r\n}\r\n.arc-portrait {\r\n  flex-shrink: 0;\r\n  width: 80px; height: 80px;\r\n  border-radius: 6px;\r\n  border: 1px solid rgba(201,168,76,0.25);\r\n  background: #1a1510;\r\n  overflow: hidden;\r\n  position: relative;\r\n}\r\n.arc-portrait img {\r\n  width: 100%; height: 100%;\r\n  object-fit: cover;\r\n  display: block;\r\n}\r\n.arc-portrait-placeholder {\r\n  width: 100%; height: 100%;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  font-family: \'Cinzel\', serif;\r\n  font-size: 24px;\r\n  color: rgba(201,168,76,0.2);\r\n}\r\n.arc-npc-info {\r\n  display: flex;\r\n  flex-direction: column;\r\n  justify-content: center;\r\n  gap: 3px;\r\n}\r\n.arc-npc-name {\r\n  font-family: \'Cinzel\', serif;\r\n  font-size: 14px;\r\n  color: rgba(232,220,200,0.9);\r\n  letter-spacing: 0.05em;\r\n}\r\n.arc-npc-title {\r\n  font-family: \'IM Fell English\', serif;\r\n  font-style: italic;\r\n  font-size: 12px;\r\n  color: rgba(201,168,76,0.55);\r\n  line-height: 1.4;\r\n}\r\n\r\n/* Speech bubble */\r\n.arc-speech {\r\n  position: relative;\r\n  z-index: 1;\r\n  margin: 14px 20px 0;\r\n  padding: 16px 18px;\r\n  background: rgba(26,21,16,0.8);\r\n  border: 1px solid rgba(201,168,76,0.15);\r\n  border-radius: 0 8px 8px 8px;\r\n  flex-shrink: 0;\r\n}\r\n.arc-speech::before {\r\n  content: \'\';\r\n  position: absolute;\r\n  top: -1px; left: -1px;\r\n  width: 0; height: 0;\r\n  border-top: 10px solid rgba(201,168,76,0.15);\r\n  border-right: 10px solid transparent;\r\n}\r\n.arc-speech::after {\r\n  content: \'\';\r\n  position: absolute;\r\n  top: 0; left: 0;\r\n  width: 0; height: 0;\r\n  border-top: 9px solid #1a1510;\r\n  border-right: 9px solid transparent;\r\n}\r\n.arc-greeting {\r\n  font-family: \'IM Fell English\', serif;\r\n  font-size: 20px;\r\n  color: rgba(232,220,200,0.95);\r\n  line-height: 1.55;\r\n  margin-bottom: 8px;\r\n}\r\n.arc-sub {\r\n  font-family: \'IM Fell English\', serif;\r\n  font-style: italic;\r\n  font-size: 17px;\r\n  color: rgba(201,168,76,0.7);\r\n  line-height: 1.55;\r\n}\r\n\r\n/* Scrollable form area */\r\n.arc-body {\r\n  position: relative;\r\n  z-index: 1;\r\n  flex: 1;\r\n  overflow-y: auto;\r\n  padding: 20px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 14px;\r\n}\r\n.arc-body::-webkit-scrollbar { width: 4px; }\r\n.arc-body::-webkit-scrollbar-track { background: transparent; }\r\n.arc-body::-webkit-scrollbar-thumb { background: rgba(201,168,76,0.2); border-radius: 2px; }\r\n\r\n/* Step sections */\r\n.arc-step {\r\n  display: none;\r\n  flex-direction: column;\r\n  gap: 12px;\r\n  animation: arcFadeIn 0.25s ease forwards;\r\n}\r\n.arc-step.active { display: flex; }\r\n@keyframes arcFadeIn {\r\n  from { opacity: 0; transform: translateY(6px); }\r\n  to   { opacity: 1; transform: translateY(0); }\r\n}\r\n\r\n/* Form elements */\r\n.arc-field {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 5px;\r\n}\r\n.arc-field label {\r\n  font-family: \'JetBrains Mono\', monospace;\r\n  font-size: 9px;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: rgba(201,168,76,0.5);\r\n}\r\n.arc-field input {\r\n  background: rgba(10,8,6,0.8);\r\n  border: 1px solid rgba(201,168,76,0.2);\r\n  border-radius: 4px;\r\n  padding: 9px 12px;\r\n  color: rgba(232,220,200,0.9);\r\n  font-family: \'IM Fell English\', serif;\r\n  font-size: 17px;\r\n  outline: none;\r\n  width: 100%;\r\n  transition: border-color 0.15s;\r\n}\r\n.arc-field input:focus { border-color: rgba(201,168,76,0.5); }\r\n.arc-field input::placeholder { color: rgba(201,168,76,0.2); font-style: italic; }\r\n\r\n/* Buttons */\r\n.arc-btn-row {\r\n  display: flex;\r\n  gap: 8px;\r\n  flex-wrap: wrap;\r\n}\r\n.arc-btn {\r\n  font-family: \'Cinzel\', serif;\r\n  font-size: 11px;\r\n  letter-spacing: 0.08em;\r\n  padding: 10px 20px;\r\n  border-radius: 4px;\r\n  cursor: pointer;\r\n  border: none;\r\n  transition: background 0.2s, transform 0.1s;\r\n  text-decoration: none;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n}\r\n.arc-btn:active { transform: scale(0.97); }\r\n.arc-btn-primary {\r\n  background: rgba(201,168,76,0.9);\r\n  color: #0a0806;\r\n}\r\n.arc-btn-primary:hover { background: rgba(201,168,76,1); }\r\n.arc-btn-ghost {\r\n  background: transparent;\r\n  border: 1px solid rgba(201,168,76,0.25);\r\n  color: rgba(201,168,76,0.7);\r\n}\r\n.arc-btn-ghost:hover {\r\n  border-color: rgba(201,168,76,0.5);\r\n  color: rgba(201,168,76,0.95);\r\n}\r\n\r\n/* Divider */\r\n.arc-divider {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 10px;\r\n  font-family: \'JetBrains Mono\', monospace;\r\n  font-size: 9px;\r\n  letter-spacing: 0.1em;\r\n  color: rgba(201,168,76,0.25);\r\n}\r\n.arc-divider::before, .arc-divider::after {\r\n  content: \'\';\r\n  flex: 1;\r\n  height: 1px;\r\n  background: rgba(201,168,76,0.12);\r\n}\r\n\r\n/* Error / info messages */\r\n.arc-notice {\r\n  padding: 10px 14px;\r\n  border-radius: 4px;\r\n  font-family: \'IM Fell English\', serif;\r\n  font-style: italic;\r\n  font-size: 13px;\r\n  border-left: 2px solid;\r\n  display: none;\r\n}\r\n.arc-notice.show { display: block; }\r\n.arc-notice.err  { background: rgba(140,50,50,0.15); border-color: #8c3232; color: #cc8f8f; }\r\n.arc-notice.ok   { background: rgba(50,100,60,0.15); border-color: #326432; color: #8fcc9f; }\r\n.arc-notice.info { background: rgba(60,60,100,0.15); border-color: #323280; color: #9f9fcc; }\r\n\r\n/* Aldric\'s response line (updated dynamically) */\r\n.arc-aldric-response {\r\n  font-family: \'IM Fell English\', serif;\r\n  font-style: italic;\r\n  font-size: 13px;\r\n  color: rgba(201,168,76,0.75);\r\n  line-height: 1.55;\r\n  padding: 10px 14px;\r\n  border-left: 2px solid rgba(201,168,76,0.25);\r\n  display: none;\r\n}\r\n.arc-aldric-response.show { display: block; }\r\n\r\n/* Stamp — success state */\r\n.arc-stamp {\r\n  text-align: center;\r\n  padding: 20px;\r\n  display: none;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  gap: 12px;\r\n}\r\n.arc-stamp.show { display: flex; }\r\n.arc-stamp-seal {\r\n  width: 80px; height: 80px;\r\n  border-radius: 50%;\r\n  border: 3px solid rgba(201,168,76,0.4);\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  font-family: \'Cinzel\', serif;\r\n  font-size: 28px;\r\n  color: rgba(201,168,76,0.6);\r\n  box-shadow: 0 0 20px rgba(201,168,76,0.1), inset 0 0 20px rgba(201,168,76,0.05);\r\n}\r\n.arc-stamp-text {\r\n  font-family: \'Cinzel\', serif;\r\n  font-size: 12px;\r\n  letter-spacing: 0.12em;\r\n  color: rgba(201,168,76,0.6);\r\n  text-transform: uppercase;\r\n}\r\n.arc-stamp-sub {\r\n  font-family: \'IM Fell English\', serif;\r\n  font-style: italic;\r\n  font-size: 13px;\r\n  color: rgba(232,220,200,0.55);\r\n  text-align: center;\r\n  line-height: 1.5;\r\n}\r\n\r\n/* Footer */\r\n.arc-footer {\r\n  position: relative;\r\n  z-index: 1;\r\n  padding: 12px 20px;\r\n  border-top: 1px solid rgba(201,168,76,0.1);\r\n  font-family: \'JetBrains Mono\', monospace;\r\n  font-size: 9px;\r\n  letter-spacing: 0.1em;\r\n  color: rgba(201,168,76,0.2);\r\n  text-align: center;\r\n  flex-shrink: 0;\r\n}\r\n</style>\r\n\r\n<!-- Overlay -->\r\n<div id=\"arc-overlay\"></div>\r\n\r\n<!-- Panel -->\r\n<div id=\"arc-panel\">\r\n\r\n  <!-- Header -->\r\n  <div class=\"arc-header\">\r\n    <div class=\"arc-logo\">\r\n      ARC\r\n      <span>Aenephsy Regulation Compendium</span>\r\n    </div>\r\n    <button class=\"arc-close\" id=\"arc-close-btn\" aria-label=\"Close\">✕</button>\r\n  </div>\r\n\r\n  <!-- Character -->\r\n  <div class=\"arc-character\">\r\n    <div class=\"arc-portrait\">\r\n      <?php if (false): /* Replace false with image check when portrait is ready */ ?>\r\n        <img src=\"/path/to/aldric-portrait.jpg\" alt=\"Aldric Voss\">\r\n      <?php else: ?>\r\n        <div class=\"arc-portrait-placeholder\">⚗</div>\r\n      <?php endif; ?>\r\n    </div>\r\n    <div class=\"arc-npc-info\">\r\n      <div class=\"arc-npc-name\">Aldric Voss</div>\r\n      <div class=\"arc-npc-title\">Senior Registrar<br>Aenephsy Regulation Compendium</div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Speech -->\r\n  <div class=\"arc-speech\">\r\n    <div class=\"arc-greeting\">\"<?= htmlspecialchars($current[\'greeting\']) ?>\"</div>\r\n    <div class=\"arc-sub\"><?= htmlspecialchars($current[\'sub\']) ?></div>\r\n  </div>\r\n\r\n  <!-- Body — steps rendered per scenario -->\r\n  <div class=\"arc-body\">\r\n\r\n    <?php if ($verify_result !== null): ?>\r\n      <div class=\"arc-notice show <?= $verify_result ? \'ok\' : \'err\' ?>\" style=\"margin-bottom:14px;\">\r\n        <?= $verify_result\r\n            ? \'Your registration has been confirmed. You may now log in.\'\r\n            : \'This confirmation link is invalid or has already been used.\' ?>\r\n      </div>\r\n    <?php endif; ?>\r\n\r\n    <?php if ($current[\'mode\'] === \'login_or_register\' || $current[\'mode\'] === \'login_or_register_then_claim\'): ?>\r\n\r\n      <!-- STEP 1A: Choose login or register -->\r\n      <div class=\"arc-step active\" id=\"step-choose\">\r\n        <div class=\"arc-btn-row\">\r\n          <button class=\"arc-btn arc-btn-primary\" onclick=\"arcShowStep(\'step-login\')\">\r\n            I am registered\r\n          </button>\r\n          <button class=\"arc-btn arc-btn-ghost\" onclick=\"arcShowStep(\'step-register\')\">\r\n            New citizen\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- STEP 1B: Login -->\r\n      <div class=\"arc-step\" id=\"step-login\">\r\n        <div class=\"arc-aldric-response show\">\r\n          \"Very well. Your credentials, please — username and passphrase.\"\r\n        </div>\r\n        <div class=\"arc-field\">\r\n          <label>Username</label>\r\n          <input type=\"text\" id=\"login-username\" placeholder=\"Your registered name…\" autocomplete=\"username\">\r\n        </div>\r\n        <div class=\"arc-field\">\r\n          <label>Passphrase</label>\r\n          <input type=\"password\" id=\"login-password\" placeholder=\"••••••••\" autocomplete=\"current-password\">\r\n        </div>\r\n        <div class=\"arc-notice\" id=\"login-error\"></div>\r\n        <div class=\"arc-btn-row\">\r\n          <button class=\"arc-btn arc-btn-primary\" onclick=\"arcDoLogin()\">Present credentials</button>\r\n          <button class=\"arc-btn arc-btn-ghost\" onclick=\"arcShowStep(\'step-choose\')\">Back</button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- STEP 1C: Register -->\r\n      <div class=\"arc-step\" id=\"step-register\">\r\n        <div class=\"arc-aldric-response show\">\r\n          \"A new citizen. Welcome — though I use that term loosely until the paperwork is complete. Full details, if you please.\"\r\n        </div>\r\n        <div class=\"arc-field\">\r\n          <label>Choose a username</label>\r\n          <input type=\"text\" id=\"reg-username\" placeholder=\"Your name in the registry…\">\r\n        </div>\r\n        <div class=\"arc-field\">\r\n          <label>Email address</label>\r\n          <input type=\"email\" id=\"reg-email\" placeholder=\"For ARC correspondence…\">\r\n        </div>\r\n        <div class=\"arc-field\">\r\n          <label>Passphrase</label>\r\n          <input type=\"password\" id=\"reg-password\" placeholder=\"Choose wisely…\">\r\n        </div>\r\n        <div class=\"arc-field\">\r\n          <label>Confirm passphrase</label>\r\n          <input type=\"password\" id=\"reg-password2\" placeholder=\"Once more…\">\r\n        </div>\r\n        <div class=\"arc-notice\" id=\"reg-error\"></div>\r\n        <div class=\"arc-btn-row\">\r\n          <button class=\"arc-btn arc-btn-primary\" onclick=\"arcDoRegister()\">Submit registration</button>\r\n          <button class=\"arc-btn arc-btn-ghost\" onclick=\"arcShowStep(\'step-choose\')\">Back</button>\r\n        </div>\r\n      </div>\r\n\r\n    <?php elseif ($current[\'mode\'] === \'owner_or_borrow\'): ?>\r\n\r\n      <!-- SCENARIO C: Owner or borrower -->\r\n      <div class=\"arc-step active\" id=\"step-choose\">\r\n        <div class=\"arc-btn-row\">\r\n          <button class=\"arc-btn arc-btn-primary\" onclick=\"arcShowStep(\'step-login\')\">\r\n            I am the owner\r\n          </button>\r\n          <button class=\"arc-btn arc-btn-ghost\" onclick=\"arcShowStep(\'step-borrow-login\')\">\r\n            I am borrowing it\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Owner login -->\r\n      <div class=\"arc-step\" id=\"step-login\">\r\n        <div class=\"arc-aldric-response show\">\r\n          \"Then identify yourself. Username and passphrase.\"\r\n        </div>\r\n        <div class=\"arc-field\">\r\n          <label>Username</label>\r\n          <input type=\"text\" id=\"login-username\" placeholder=\"Your registered name…\" autocomplete=\"username\">\r\n        </div>\r\n        <div class=\"arc-field\">\r\n          <label>Passphrase</label>\r\n          <input type=\"password\" id=\"login-password\" placeholder=\"••••••••\" autocomplete=\"current-password\">\r\n        </div>\r\n        <div class=\"arc-notice\" id=\"login-error\"></div>\r\n        <div class=\"arc-btn-row\">\r\n          <button class=\"arc-btn arc-btn-primary\" onclick=\"arcDoLogin()\">Present credentials</button>\r\n          <button class=\"arc-btn arc-btn-ghost\" onclick=\"arcShowStep(\'step-choose\')\">Back</button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Borrower — needs owner PIN -->\r\n      <div class=\"arc-step\" id=\"step-borrow-login\">\r\n        <div class=\"arc-aldric-response show\">\r\n          \"<?= $owner_username ? \"This Fragmenta belongs to <strong>{$owner_username}</strong>. \" : \"\" ?>If they have granted you access, they will have given you a clearance PIN.\"\r\n        </div>\r\n        <div class=\"arc-field\">\r\n          <label>Your username</label>\r\n          <input type=\"text\" id=\"borrow-username\" placeholder=\"Your registered name…\">\r\n        </div>\r\n        <div class=\"arc-field\">\r\n          <label>Your passphrase</label>\r\n          <input type=\"password\" id=\"borrow-password\" placeholder=\"••••••••\">\r\n        </div>\r\n        <div class=\"arc-field\">\r\n          <label>Owner\'s clearance PIN</label>\r\n          <input type=\"password\" id=\"borrow-pin\" placeholder=\"4-digit PIN…\" maxlength=\"10\">\r\n        </div>\r\n        <div class=\"arc-notice\" id=\"borrow-error\"></div>\r\n        <div class=\"arc-btn-row\">\r\n          <button class=\"arc-btn arc-btn-primary\" onclick=\"arcDoBorrow()\">Request access</button>\r\n          <button class=\"arc-btn arc-btn-ghost\" onclick=\"arcShowStep(\'step-choose\')\">Back</button>\r\n        </div>\r\n      </div>\r\n\r\n    <?php elseif ($current[\'mode\'] === \'claim_confirm\'): ?>\r\n\r\n      <!-- SCENARIO D: Logged in, claim unassigned NFC -->\r\n      <div class=\"arc-step active\" id=\"step-claim\">\r\n        <div class=\"arc-btn-row\">\r\n          <button class=\"arc-btn arc-btn-primary\" onclick=\"arcDoClaim()\">\r\n            Register to my name\r\n          </button>\r\n          <button class=\"arc-btn arc-btn-ghost\" onclick=\"arcClosePanel()\">\r\n            Not now\r\n          </button>\r\n        </div>\r\n        <div class=\"arc-notice\" id=\"claim-error\"></div>\r\n      </div>\r\n\r\n    <?php elseif ($current[\'mode\'] === \'no_sharing\'): ?>\r\n\r\n      <!-- NO PIN SET — sharing not enabled -->\r\n      <div class=\"arc-step active\" id=\"step-no-sharing\">\r\n        <div class=\"arc-aldric-response show\">\r\n          \"I suggest contacting the owner directly. There is nothing more I can do here.\"\r\n        </div>\r\n        <div class=\"arc-btn-row\">\r\n          <button class=\"arc-btn arc-btn-ghost\" onclick=\"arcClosePanel()\">Understood</button>\r\n        </div>\r\n      </div>\r\n\r\n     <?php elseif ($current[\'mode\'] === \'pin_manage\'): ?>\r\n\r\n      <!-- PIN MANAGE — set or update PIN -->\r\n      <div class=\"arc-step active\" id=\"step-pin-manage\">\r\n        <div class=\"arc-field\">\r\n          <label>New Clearance PIN</label>\r\n          <input type=\"password\" id=\"pin-manage-input\" placeholder=\"Enter new PIN…\" maxlength=\"10\">\r\n        </div>\r\n        <div class=\"arc-field\">\r\n          <label>Confirm PIN</label>\r\n          <input type=\"password\" id=\"pin-manage-confirm\" placeholder=\"Confirm PIN…\" maxlength=\"10\">\r\n        </div>\r\n        <div class=\"arc-notice\" id=\"pin-manage-error\"></div>\r\n        <div class=\"arc-btn-row\">\r\n          <button class=\"arc-btn arc-btn-primary\" onclick=\"arcDoPinManage()\">Set PIN</button>\r\n          <button class=\"arc-btn arc-btn-ghost\" onclick=\"arcDismiss()\">Cancel</button>\r\n        </div>\r\n      </div>\r\n\r\n    <?php elseif ($current[\'mode\'] === \'pin_remove\'): ?>\r\n\r\n      <!-- PIN REMOVE — confirm removal -->\r\n      <div class=\"arc-step active\" id=\"step-pin-remove\">\r\n        <div class=\"arc-aldric-response show\">\r\n          \"Are you certain? This will disable borrowing until a new PIN is set.\"\r\n        </div>\r\n        <div class=\"arc-notice\" id=\"pin-remove-error\"></div>\r\n        <div class=\"arc-btn-row\">\r\n          <button class=\"arc-btn arc-btn-primary\" onclick=\"arcDoPinRemove()\">Remove PIN</button>\r\n          <button class=\"arc-btn arc-btn-ghost\" onclick=\"arcDismiss()\">Cancel</button>\r\n        </div>\r\n      </div>\r\n\r\n    <?php elseif ($current[\'mode\'] === \'pin_only\'): ?>\r\n\r\n      <!-- SCENARIO E: Logged in, someone else\'s NFC — PIN only -->\r\n      <div class=\"arc-step active\" id=\"step-pin\">\r\n        <div class=\"arc-field\">\r\n          <label>Owner\'s clearance PIN</label>\r\n          <input type=\"password\" id=\"pin-input\" placeholder=\"Enter PIN…\" maxlength=\"10\">\r\n        </div>\r\n        <div class=\"arc-notice\" id=\"pin-error\"></div>\r\n        <div class=\"arc-btn-row\">\r\n          <button class=\"arc-btn arc-btn-primary\" onclick=\"arcDoPin()\">Submit PIN</button>\r\n        </div>\r\n      </div>\r\n\r\n    <?php endif; ?>\r\n\r\n    <!-- Set PIN step (shown after first login with a Fragmenta if no PIN set) -->\r\n    <div class=\"arc-step\" id=\"step-set-pin\">\r\n      <div class=\"arc-aldric-response show\">\r\n        \"One final matter. If you intend to share this Fragmenta with other citizens, the ARC requires you to set a clearance PIN. They will need it to borrow your card. You may skip this for now.\"\r\n      </div>\r\n      <div class=\"arc-field\">\r\n        <label>Set a clearance PIN (optional)</label>\r\n        <input type=\"password\" id=\"new-pin\" placeholder=\"Leave blank to skip…\" maxlength=\"10\">\r\n      </div>\r\n      <div class=\"arc-btn-row\">\r\n        <button class=\"arc-btn arc-btn-primary\" onclick=\"arcDoSetPin()\">Confirm</button>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Success stamp -->\r\n    <div class=\"arc-stamp\" id=\"arc-success\">\r\n      <div class=\"arc-stamp-seal\">✦</div>\r\n      <div class=\"arc-stamp-text\">Clearance Granted</div>\r\n      <div class=\"arc-stamp-sub\" id=\"arc-success-msg\">\r\n        \"Everything in order. You may proceed. And citizen — do try not to lose it.\"\r\n      </div>\r\n      <button class=\"arc-btn arc-btn-primary\" onclick=\"arcProceed()\">Proceed</button>\r\n    </div>\r\n\r\n  </div><!-- /arc-body -->\r\n\r\n  <div class=\"arc-footer\">\r\n    ARC Registration Terminal &nbsp;·&nbsp; Ref. <?= strtoupper(substr(md5(microtime()), 0, 8)) ?>\r\n  </div>\r\n\r\n</div><!-- /arc-panel -->\r\n\r\n<script>\r\n(function() {\r\n\r\n  var panel   = document.getElementById(\'arc-panel\');\r\n  var overlay = document.getElementById(\'arc-overlay\');\r\n  var scenario   = \'<?= $scenario ?>\';\r\n  var nfcUid     = \'<?= htmlspecialchars($nfc_uid ?? \'\') ?>\';\r\n  var redirectTo = \'/index.php/hub\';\r\n\r\n  /* ── Open / Close ── */\r\n  function arcOpenPanel() {\r\n    panel.classList.add(\'open\');\r\n    overlay.classList.add(\'open\');\r\n    document.body.style.overflow = \'hidden\';\r\n  }\r\n\r\n window.arcClosePanel = arcDismiss;\r\n	\r\n  function arcDismiss() {\r\n    panel.classList.remove(\'open\');\r\n    overlay.classList.remove(\'open\');\r\n    document.body.style.overflow = \'\';\r\n    setTimeout(function() {\r\n      var dest = <?= $logged_in ? \"\'/index.php/hub/\'\" : \"\'/index.php/\'\" ?>;\r\n      window.location.href = dest;\r\n    }, 450);\r\n  }\r\n\r\n  document.getElementById(\'arc-close-btn\').addEventListener(\'click\', arcDismiss);\r\n  overlay.addEventListener(\'click\', arcDismiss);\r\n\r\n  /* ── Step navigation ── */\r\n  window.arcShowStep = function(stepId) {\r\n    document.querySelectorAll(\'.arc-step\').forEach(function(s) {\r\n      s.classList.remove(\'active\');\r\n    });\r\n    var el = document.getElementById(stepId);\r\n    if (el) el.classList.add(\'active\');\r\n  };\r\n\r\n  /* ── Show notice ── */\r\n  function arcNotice(id, msg, type) {\r\n    var el = document.getElementById(id);\r\n    if (!el) return;\r\n    el.textContent = msg;\r\n    el.className   = \'arc-notice show \' + (type || \'err\');\r\n  }\r\n  function arcClearNotice(id) {\r\n    var el = document.getElementById(id);\r\n    if (el) { el.className = \'arc-notice\'; el.textContent = \'\'; }\r\n  }\r\n\r\n  /* ── Show success ── */\r\n  function arcSuccess(msg) {\r\n    document.querySelectorAll(\'.arc-step\').forEach(function(s) {\r\n      s.classList.remove(\'active\');\r\n    });\r\n    var stamp = document.getElementById(\'arc-success\');\r\n    if (msg) document.getElementById(\'arc-success-msg\').textContent = \'\"\' + msg + \'\"\';\r\n    stamp.classList.add(\'show\');\r\n  }\r\n\r\n	  /* ── Show success (register variant — no hub redirect) ── */\r\n  function arcRegisterSuccess(msg) {\r\n    document.querySelectorAll(\'.arc-step\').forEach(function(s) {\r\n      s.classList.remove(\'active\');\r\n    });\r\n    var stamp = document.getElementById(\'arc-success\');\r\n    if (msg) document.getElementById(\'arc-success-msg\').textContent = \'\"\' + msg + \'\"\';\r\n    stamp.classList.add(\'show\');\r\n    var proceedBtn = stamp.querySelector(\'.arc-btn\');\r\n    if (proceedBtn) {\r\n      proceedBtn.textContent = \'Return to login\';\r\n      proceedBtn.onclick = function() { window.location.reload(); };\r\n    }\r\n  }\r\n  /* ── Proceed after success ── */\r\n  window.arcProceed = function() {\r\n    window.location.href = redirectTo;\r\n  };\r\n\r\n  /* ── AJAX helper ── */\r\n  function arcPost(action, data, cb) {\r\n    data.action = \'chards_arc\';\r\n    data.sub = action;\r\n    fetch(\'/wp-admin/admin-ajax.php\', {\r\n      method: \'POST\',\r\n      headers: { \'Content-Type\': \'application/x-www-form-urlencoded\' },\r\n      body: Object.keys(data).map(function(k) {\r\n        return encodeURIComponent(k) + \'=\' + encodeURIComponent(data[k]);\r\n      }).join(\'&\')\r\n    })\r\n    .then(function(r) { return r.json(); })\r\n    .then(cb)\r\n    .catch(function() { cb({ ok: false, msg: \'Connection error. Please try again.\' }); });\r\n  }\r\n\r\n  /* ── LOGIN ── */\r\n  window.arcDoLogin = function() {\r\n    arcClearNotice(\'login-error\');\r\n    var u = (document.getElementById(\'login-username\') || {}).value || \'\';\r\n    var p = (document.getElementById(\'login-password\') || {}).value || \'\';\r\n    if (!u || !p) { arcNotice(\'login-error\', \'Please fill in all fields.\'); return; }\r\n\r\n    arcPost(\'arc_login\', { username: u, password: p }, function(res) {\r\n      if (res.success) {\r\n		if (res.data && res.data.remember_token && window.AppInventor) {\r\n       		window.AppInventor.setWebViewString(res.data.remember_token); \r\n     	}\r\n        if (res.data && res.data.needs_pin_setup && nfcUid) {\r\n          arcShowStep(\'step-set-pin\');\r\n        } else if (res.data && res.data.needs_claim && nfcUid) {\r\n          arcSuccess(\'Registration complete. The Fragmenta has been logged under your name. Everything in order.\');\r\n        } else {\r\n          arcSuccess(\'Credentials verified. You may proceed, citizen.\');\r\n        }\r\n      } else {\r\n        arcNotice(\'login-error\', (res.data ? res.data.msg : \'\') || \'Those credentials do not match our records.\');\r\n      }\r\n    });\r\n  };\r\n\r\n  /* ── REGISTER ── */\r\n  window.arcDoRegister = function() {\r\n    arcClearNotice(\'reg-error\');\r\n    var u  = document.getElementById(\'reg-username\').value;\r\n    var e  = document.getElementById(\'reg-email\').value;\r\n    var p  = document.getElementById(\'reg-password\').value;\r\n    var p2 = document.getElementById(\'reg-password2\').value;\r\n    if (!u || !e || !p || !p2) { arcNotice(\'reg-error\', \'All fields are required.\'); return; }\r\n    if (p !== p2) { arcNotice(\'reg-error\', \'The passphrases do not match.\'); return; }\r\n    if (p.length < 8) { arcNotice(\'reg-error\', \'Passphrase must be at least 8 characters.\'); return; }\r\n\r\n    arcPost(\'arc_register\', { username: u, email: e, password: p }, function(res) {\r\n      if (res.success) {\r\n        arcRegisterSuccess(\'Your registration has been filed, \' + u + \'. A sealed notice has been sent to your correspondence address\' + String.fromCharCode(8212) + \'confirm it before you may enter the registry.\');\r\n      } else {\r\n        arcNotice(\'reg-error\', (res.data ? res.data.msg : \'\') || \'Registration failed. That username or email may already exist.\');\r\n      }\r\n    });\r\n  };\r\n  /* ── BORROW (scenario C, non-owner) ── */\r\n  window.arcDoBorrow = function() {\r\n    arcClearNotice(\'borrow-error\');\r\n    var u   = document.getElementById(\'borrow-username\').value;\r\n    var p   = document.getElementById(\'borrow-password\').value;\r\n    var pin = document.getElementById(\'borrow-pin\').value;\r\n    if (!u || !p || !pin) { arcNotice(\'borrow-error\', \'All fields are required.\'); return; }\r\n\r\n    arcPost(\'arc_borrow\', { username: u, password: p, pin: pin }, function(res) {\r\n      if (res.success) {\r\n        arcSuccess(\'Temporary access granted. The owner has been noted. Proceed.\');\r\n      } else {\r\n        arcNotice(\'borrow-error\', (res.data ? res.data.msg : \'\') || \'Access denied. Invalid credentials or PIN.\');\r\n      }\r\n    });\r\n  };\r\n\r\n  /* ── PIN (scenario E, already logged in) ── */\r\n  window.arcDoPin = function() {\r\n    arcClearNotice(\'pin-error\');\r\n    var pin = document.getElementById(\'pin-input\').value;\r\n    if (!pin) { arcNotice(\'pin-error\', \'Please enter the clearance PIN.\'); return; }\r\n\r\n    arcPost(\'arc_pin\', { pin: pin }, function(res) {\r\n      if (res.success) {\r\n        arcSuccess(\'PIN accepted. Temporary clearance granted. Proceed.\');\r\n      } else {\r\n        arcNotice(\'pin-error\', (res.data ? res.data.msg : \'\') || \'Incorrect PIN. Access denied.\');\r\n      }\r\n    });\r\n  };\r\n\r\n  /* ── CLAIM (scenario D) ── */\r\n window.arcDoClaim = function() {\r\n    arcClearNotice(\'claim-error\');\r\n    arcPost(\'arc_claim\', {}, function(res) {\r\n      if (res.success) {\r\n        arcSuccess(\'Fragmenta registered to your name. Everything in order. You may proceed.\');\r\n      } else {\r\n        var msg = res.data ? res.data.msg : \'\';\r\n        if (msg === \'UNRECOGNISED_CARD\') {\r\n          arcNotice(\'claim-error\',\r\n            \'This shard is not on our records. \' +\r\n            \'Unregistered Fragmenta are not permitted. \' +\r\n            \'If you believe this is an error, contact the ARC.\',\r\n            \'err\'\r\n          );\r\n        } else {\r\n          arcNotice(\'claim-error\', msg || \'Registration failed. Please try again.\');\r\n        }\r\n      }\r\n    });\r\n  };\r\n\r\n /* ── PIN MANAGE (hub flow — set/update PIN) ── */\r\n  window.arcDoPinManage = function() {\r\n    arcClearNotice(\'pin-manage-error\');\r\n    var pin  = document.getElementById(\'pin-manage-input\').value;\r\n    var pin2 = document.getElementById(\'pin-manage-confirm\').value;\r\n    if (!pin) { arcNotice(\'pin-manage-error\', \'Please enter a PIN.\'); return; }\r\n    if (pin !== pin2) { arcNotice(\'pin-manage-error\', \'PINs do not match.\'); return; }\r\n\r\n    arcPost(\'arc_set_pin\', { pin: pin }, function(res) {\r\n      if (res.success) {\r\n        arcSuccess(\'Clearance PIN updated. Guard it well, citizen.\');\r\n      } else {\r\n        arcNotice(\'pin-manage-error\', (res.data ? res.data.msg : \'\') || \'Error updating PIN.\');\r\n      }\r\n    });\r\n  };\r\n\r\n  /* ── PIN REMOVE (hub flow — remove PIN) ── */\r\n  window.arcDoPinRemove = function() {\r\n    arcClearNotice(\'pin-remove-error\');\r\n    arcPost(\'arc_remove_pin\', {}, function(res) {\r\n      if (res.success) {\r\n        arcSuccess(\'Clearance PIN removed. This Fragmenta can no longer be borrowed.\');\r\n      } else {\r\n        arcNotice(\'pin-remove-error\', (res.data ? res.data.msg : \'\') || \'Error removing PIN.\');\r\n      }\r\n    });\r\n  };\r\n\r\n  /* ── SET PIN (optional, post login/register) ── */\r\n  window.arcDoSetPin = function() {\r\n    var pin = document.getElementById(\'new-pin\').value;\r\n    arcPost(\'arc_set_pin\', { pin: pin }, function(res) {\r\n      arcSuccess(\r\n        pin\r\n          ? \'PIN recorded. Guard it well — it determines who may borrow your Fragmenta.\'\r\n          : \'Noted. You may set a PIN at any time from your account settings. Proceed.\'\r\n      );\r\n    });\r\n  };\r\n\r\n  /* ── Auto-open if triggered by login button or NFC ── */\r\n  /* Called from your login button or from the Android app */\r\n  window.arcOpen = function() { arcOpenPanel(); };\r\n\r\n  /* If page loaded with NFC uid (posted from app), open immediately */\r\n  arcOpenPanel();\r\n\r\n})();\r\n</script>',	'login',	'',	'publish',	'closed',	'closed',	'',	'login',	'',	'',	'2026-07-29 19:24:36',	'2026-07-29 19:24:36',	'',	0,	'https://chards.wasmer.app/index.php/wpcode/login/',	0,	'wpcode',	'',	0),
(144,	1,	'2026-05-10 07:55:54',	'2026-05-10 07:55:54',	'<!-- wp:cover {\"url\":\"https://chards.wasmer.app/wp-content/uploads/2026/04/bg2-768x770-1.png\",\"id\":123,\"hasParallax\":true,\"dimRatio\":50,\"customOverlayColor\":\"#3d3b52\",\"isUserOverlayColor\":false,\"minHeight\":2071,\"minHeightUnit\":\"px\",\"contentPosition\":\"top center\",\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover has-parallax has-custom-content-position is-position-top-center\" style=\"min-height:2071px\"><div class=\"wp-block-cover__image-background wp-image-123 size-full has-parallax\" style=\"background-position:50% 50%;background-image:url(https://chards.wasmer.app/wp-content/uploads/2026/04/bg2-768x770-1.png)\"></div><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\" style=\"background-color:#3d3b52\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:spacer {\"height\":\"73px\"} -->\n<div style=\"height:73px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:shortcode -->\n[wpcode id=\"143\"]\n<!-- /wp:shortcode --></div></div>\n<!-- /wp:cover -->',	'login',	'',	'publish',	'closed',	'closed',	'',	'login',	'',	'',	'2026-05-14 19:43:41',	'2026-05-14 19:43:41',	'',	0,	'https://chards.wasmer.app/?page_id=144',	0,	'page',	'',	0),
(146,	1,	'2026-05-10 08:02:52',	'2026-05-10 08:02:52',	'<!-- wp:cover {\"url\":\"https://chards.wasmer.app/wp-content/uploads/2026/04/bg2.png\",\"id\":120,\"hasParallax\":true,\"dimRatio\":50,\"customOverlayColor\":\"#3d3b52\",\"isUserOverlayColor\":false,\"minHeight\":1226,\"minHeightUnit\":\"px\",\"contentPosition\":\"top center\",\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"100%\"}} -->\n<div class=\"wp-block-cover has-parallax has-custom-content-position is-position-top-center\" style=\"min-height:1226px\"><div class=\"wp-block-cover__image-background wp-image-120 size-full has-parallax\" style=\"background-position:50% 50%;background-image:url(https://chards.wasmer.app/wp-content/uploads/2026/04/bg2.png)\"></div><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\" style=\"background-color:#3d3b52\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:image {\"id\":177,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-large\"><img src=\"https://chards.wasmer.app/wp-content/uploads/2026/05/nf-1024x1024.png\" alt=\"\" class=\"wp-image-177\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:cover -->',	'Blog Home',	'Displays the latest posts as either the site homepage or as the \"Posts page\" as defined under reading settings. If it exists, the Front Page template overrides this template when posts are shown on the homepage.',	'publish',	'closed',	'closed',	'',	'home',	'',	'',	'2026-07-25 22:08:38',	'2026-07-25 22:08:38',	'',	0,	'https://chards.wasmer.app/index.php/home/',	0,	'wp_template',	'',	0),
(147,	1,	'2026-05-11 16:50:51',	'2026-05-11 16:50:51',	'<?php\r\n/* ============================================================\r\n   CHARDS — My Collection\r\n   Hierarchical display: Chapter → Card Name → Rarity tiers\r\n   Ownership tracked via chards_card_ownership table.\r\n   Merge: 5x current tier → 1x next tier up.\r\n============================================================ */\r\nif (!session_id()) session_start();\r\nchards_require_app_access(\'collection\');\r\n$user_id  = $_SESSION[\'chards_user_id\'] ?? null;\r\n$username = $_SESSION[\'chards_username\'] ?? null;\r\n\r\n/* ── AJAX: merge cards ── */\r\nif (isset($_POST[\'action\']) && $_POST[\'action\'] === \'merge_card\') {\r\n    header(\'Content-Type: application/json\');\r\n    if (!$user_id) { echo json_encode([\'ok\' => false, \'msg\' => \'Not logged in.\']); exit; }\r\n\r\n    $card_id = (int)($_POST[\'card_id\'] ?? 0);\r\n    if (!$card_id) { echo json_encode([\'ok\' => false, \'msg\' => \'Invalid card.\']); exit; }\r\n\r\n    try {\r\n        $pdo = new PDO(\r\n            \'mysql:host=db.fr-pari1.bengt.wasmernet.com;port=10272;dbname=dbGQr4derPM6nWoRL4jPwNPN;charset=utf8mb4\',\r\n            \'0074c9f9784980005ded7796ee74\',\r\n            \'06950074-c9fa-7db2-8000-c0aec36ba1ac\',\r\n            [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]\r\n        );\r\n\r\n        /* Get current card and its rarity */\r\n        $card = $pdo->prepare(\"\r\n            SELECT c.*, r.sort_order AS rarity_order\r\n            FROM chards_cards c\r\n            JOIN chards_rarities r ON r.id = c.rarity_id\r\n            WHERE c.id = ?\r\n        \");\r\n        $card->execute([$card_id]);\r\n        $card = $card->fetch();\r\n        if (!$card) { echo json_encode([\'ok\' => false, \'msg\' => \'Card not found.\']); exit; }\r\n\r\n        /* Check ownership >= 5 */\r\n        $qty = $pdo->prepare(\"SELECT quantity FROM chards_card_ownership WHERE user_id = ? AND card_id = ?\");\r\n        $qty->execute([$user_id, $card_id]);\r\n        $qty = (int)($qty->fetchColumn() ?? 0);\r\n        if ($qty < 5) { echo json_encode([\'ok\' => false, \'msg\' => \'Not enough copies to merge.\']); exit; }\r\n\r\n        /* Find next rarity tier of same card family */\r\n        $base_id = $card[\'base_card_id\'] ?: $card[\'id\'];\r\n        $next = $pdo->prepare(\"\r\n            SELECT c.id FROM chards_cards c\r\n            JOIN chards_rarities r ON r.id = c.rarity_id\r\n            WHERE (c.base_card_id = ? OR c.id = ?)\r\n              AND r.sort_order > ?\r\n              AND c.is_active = 1\r\n            ORDER BY r.sort_order ASC\r\n            LIMIT 1\r\n        \");\r\n        $next->execute([$base_id, $base_id, $card[\'rarity_order\']]);\r\n        $next_card = $next->fetch();\r\n        if (!$next_card) { echo json_encode([\'ok\' => false, \'msg\' => \'No higher tier available yet.\']); exit; }\r\n\r\n        /* Perform merge in transaction */\r\n        $pdo->beginTransaction();\r\n\r\n        /* Deduct 5 copies of current tier */\r\n        $pdo->prepare(\"\r\n            UPDATE chards_card_ownership\r\n            SET quantity = quantity - 5\r\n            WHERE user_id = ? AND card_id = ?\r\n        \")->execute([$user_id, $card_id]);\r\n\r\n        /* Remove row if quantity reaches 0 */\r\n        $pdo->prepare(\"\r\n            DELETE FROM chards_card_ownership\r\n            WHERE user_id = ? AND card_id = ? AND quantity <= 0\r\n        \")->execute([$user_id, $card_id]);\r\n\r\n        /* Add 1 copy of next tier */\r\n        $pdo->prepare(\"\r\n            INSERT INTO chards_card_ownership (user_id, card_id, quantity)\r\n            VALUES (?, ?, 1)\r\n            ON DUPLICATE KEY UPDATE quantity = quantity + 1\r\n        \")->execute([$user_id, $next_card[\'id\']]);\r\n\r\n        $pdo->commit();\r\n        echo json_encode([\'ok\' => true]);\r\n\r\n    } catch (PDOException $e) {\r\n        if (isset($pdo)) $pdo->rollBack();\r\n        echo json_encode([\'ok\' => false, \'msg\' => $e->getMessage()]);\r\n    }\r\n    exit;\r\n}\r\n\r\n/* ── DB ── */\r\n$db = null;\r\ntry {\r\n    $db = new PDO(\r\n        \'mysql:host=db.fr-pari1.bengt.wasmernet.com;port=10272;dbname=dbGQr4derPM6nWoRL4jPwNPN;charset=utf8mb4\',\r\n        \'0074c9f9784980005ded7796ee74\',\r\n        \'06950074-c9fa-7db2-8000-c0aec36ba1ac\',\r\n        [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]\r\n    );\r\n} catch (PDOException $e) { $db = null; }\r\n\r\n/* ── FETCH CHAPTERS ── */\r\n$chapters = [];\r\nif ($db) {\r\n    $chapters = $db->query(\"SELECT id, name FROM chards_chapters WHERE is_active = 1 ORDER BY id ASC\")->fetchAll();\r\n}\r\n$selected_chapter = isset($_GET[\'chapter\']) ? (int)$_GET[\'chapter\'] : ($chapters[0][\'id\'] ?? 0);\r\n\r\n/* ── FETCH ALL CARD FAMILIES FOR SELECTED CHAPTER ──\r\n   One row per base card (base_card_id IS NULL).\r\n   Join ownership to get highest rarity owned. ── */\r\n$card_families = [];\r\n$owned_tiers   = []; /* card_id => quantity for all tiers */\r\n\r\nif ($db && $selected_chapter) {\r\n\r\n    /* All base cards for this chapter */\r\n    $stmt = $db->prepare(\"\r\n        SELECT\r\n            c.id, c.name, c.description, c.flavour_text,\r\n            c.image_url, c.artist, c.card_number,\r\n            r.id AS rarity_id, r.label AS rarity_label,\r\n            r.color_hex, r.border_url, r.sort_order AS rarity_order\r\n        FROM chards_cards c\r\n        JOIN chards_rarities r ON r.id = c.rarity_id\r\n        WHERE c.card_type    = \'collectible\'\r\n          AND c.is_active    = 1\r\n          AND c.base_card_id IS NULL\r\n          AND c.chapter_id   = ?\r\n        ORDER BY c.card_number ASC, c.id ASC\r\n    \");\r\n    $stmt->execute([$selected_chapter]);\r\n    $base_cards = $stmt->fetchAll();\r\n\r\n    if ($user_id && !empty($base_cards)) {\r\n        /* Fetch ALL owned tiers for these card families */\r\n        $base_ids = array_column($base_cards, \'id\');\r\n        $placeholders = implode(\',\', array_fill(0, count($base_ids), \'?\'));\r\n\r\n        /* Get ownership for base cards AND all their tier children */\r\n        $own_stmt = $db->prepare(\"\r\n            SELECT o.card_id, o.quantity, c.base_card_id,\r\n                   COALESCE(c.base_card_id, c.id) AS family_id,\r\n                   r.sort_order AS rarity_order, r.label AS rarity_label,\r\n                   r.color_hex, r.border_url, c.image_url,\r\n                   c.name, c.description, c.flavour_text, c.artist, c.id\r\n            FROM chards_card_ownership o\r\n            JOIN chards_cards c ON c.id = o.card_id\r\n            JOIN chards_rarities r ON r.id = c.rarity_id\r\n            WHERE o.user_id = ?\r\n              AND o.quantity > 0\r\n              AND COALESCE(c.base_card_id, c.id) IN ({$placeholders})\r\n            ORDER BY r.sort_order DESC\r\n        \");\r\n        $own_stmt->execute(array_merge([$user_id], $base_ids));\r\n        foreach ($own_stmt->fetchAll() as $row) {\r\n            $owned_tiers[$row[\'family_id\']][] = $row;\r\n        }\r\n    }\r\n\r\n    /* Build card families */\r\n    foreach ($base_cards as $base) {\r\n        $family_id    = $base[\'id\'];\r\n        $owned        = $owned_tiers[$family_id] ?? [];\r\n        $highest_owned = $owned[0] ?? null; /* already sorted DESC by rarity_order */\r\n\r\n        /* Get all tiers for this family (for lightbox) */\r\n        $tiers_stmt = $db->prepare(\"\r\n            SELECT c.id, c.image_url, c.is_active,\r\n                   r.id AS rarity_id, r.label AS rarity_label,\r\n                   r.color_hex, r.border_url, r.sort_order\r\n            FROM chards_cards c\r\n            JOIN chards_rarities r ON r.id = c.rarity_id\r\n            WHERE (c.id = ? OR c.base_card_id = ?)\r\n              AND c.card_type = \'collectible\'\r\n            ORDER BY r.sort_order ASC\r\n        \");\r\n        $tiers_stmt->execute([$family_id, $family_id]);\r\n        $all_tiers = $tiers_stmt->fetchAll();\r\n\r\n        $card_families[] = [\r\n            \'base\'          => $base,\r\n            \'highest_owned\' => $highest_owned,\r\n            \'owned_tiers\'   => $owned,\r\n            \'all_tiers\'     => $all_tiers,\r\n            \'is_owned\'      => !empty($owned),\r\n        ];\r\n    }\r\n}\r\n$total   = 0;\r\n$owned_n = 0;\r\nforeach ($card_families as $fam) {\r\n    /* Max possible = sort_order of the highest tier in this family */\r\n    $max_rarity = 0;\r\n    foreach ($fam[\'all_tiers\'] as $tier) {\r\n        if ((int)$tier[\'sort_order\'] > $max_rarity) $max_rarity = (int)$tier[\'sort_order\'];\r\n    }\r\n    $total += $max_rarity;\r\n\r\n    /* Owned = rarity_order of the highest owned tier */\r\n    if ($fam[\'is_owned\'] && $fam[\'highest_owned\']) {\r\n        $owned_n += (int)$fam[\'highest_owned\'][\'rarity_order\'];\r\n    }\r\n}\r\n?>\r\n<link href=\"https://fonts.googleapis.com/css2?family=Cinzel+Decorative:wght@400;700&family=Cinzel:wght@400;600&family=Crimson+Pro:ital,wght@0,300;0,400;0,600;1,300;1,400&display=swap\" rel=\"stylesheet\">\r\n\r\n<style>\r\n#chards-coll *, #chards-coll *::before, #chards-coll *::after {\r\n  box-sizing: border-box; margin: 0; padding: 0;\r\n}\r\n#chards-coll {\r\n  --bg:       #0a0806;\r\n  --surface:  #13100d;\r\n  --surface2: #1c1712;\r\n  --border:   rgba(201,168,76,0.12);\r\n  --border-hi:rgba(201,168,76,0.35);\r\n  --gold:     #c9a84c;\r\n  --gold-dim: #6b5020;\r\n  --parch:    #e8dcc8;\r\n  --muted:    rgba(232,220,200,0.4);\r\n  --r:        8px;\r\n  background: var(--bg);\r\n  color: var(--parch);\r\n  font-family: \'Crimson Pro\', Georgia, serif;\r\n  min-height: 80vh;\r\n  padding: 0 0 60px;\r\n}\r\n\r\n/* ── HEADER ── */\r\n#chards-coll .coll-header {\r\n  padding: 28px 24px 20px;\r\n  border-bottom: 1px solid var(--border);\r\n  position: relative;\r\n}\r\n#chards-coll .coll-header::before {\r\n  content: \'\';\r\n  position: absolute; inset: 0;\r\n  background: radial-gradient(ellipse at 50% 0%, rgba(201,168,76,0.06) 0%, transparent 70%);\r\n  pointer-events: none;\r\n}\r\n#chards-coll .coll-top-row {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  margin-bottom: 14px;\r\n  gap: 12px;\r\n  flex-wrap: wrap;\r\n}\r\n#chards-coll .coll-title {\r\n  font-family: \'Cinzel Decorative\', serif;\r\n  font-size: clamp(14px, 3vw, 20px);\r\n  color: var(--gold);\r\n  letter-spacing: .06em;\r\n}\r\n#chards-coll .coll-hub-link {\r\n  font-size: 12px;\r\n  color: var(--muted);\r\n  text-decoration: none;\r\n  border: 1px solid var(--border);\r\n  border-radius: 20px;\r\n  padding: 4px 12px;\r\n  font-style: italic;\r\n  transition: color .2s, border-color .2s;\r\n}\r\n#chards-coll .coll-hub-link:hover { color: var(--parch); border-color: var(--border-hi); }\r\n\r\n/* chapter selector */\r\n#chards-coll .coll-chapter-row {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 12px;\r\n  flex-wrap: wrap;\r\n}\r\n#chards-coll .coll-chapter-select {\r\n  background: var(--surface2);\r\n  border: 1px solid var(--border);\r\n  border-radius: var(--r);\r\n  padding: 7px 12px;\r\n  color: var(--parch);\r\n  font-family: \'Crimson Pro\', serif;\r\n  font-size: 15px;\r\n  outline: none;\r\n  cursor: pointer;\r\n  transition: border-color .15s;\r\n}\r\n#chards-coll .coll-chapter-select:focus { border-color: var(--border-hi); }\r\n#chards-coll .coll-chapter-select option { background: var(--surface2); }\r\n\r\n/* progress */\r\n#chards-coll .coll-progress {\r\n  display: flex; align-items: center; gap: 10px;\r\n  font-size: 13px; color: var(--muted);\r\n  flex: 1; min-width: 120px;\r\n}\r\n#chards-coll .coll-pbar {\r\n  flex: 1; height: 3px;\r\n  background: var(--surface2); border-radius: 2px; overflow: hidden;\r\n}\r\n#chards-coll .coll-pfill {\r\n  height: 100%;\r\n  background: linear-gradient(90deg, var(--gold-dim), var(--gold));\r\n  border-radius: 2px; transition: width .6s ease;\r\n}\r\n\r\n/* ── GRID ── */\r\n#chards-coll .coll-wrap {\r\n  max-width: 900px; margin: 0 auto; padding: 24px 16px 0;\r\n}\r\n#chards-coll .coll-grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fill, minmax(110px, 1fr));\r\n  gap: 12px;\r\n}\r\n\r\n/* ── CARD SLOT ── */\r\n#chards-coll .coll-card {\r\n  position: relative;\r\n  aspect-ratio: 3/4;\r\n  border-radius: var(--r);\r\n  overflow: visible;\r\n  cursor: pointer;\r\n  z-index: 1;\r\n  transition: z-index 0s;\r\n}\r\n#chards-coll .coll-card:hover { z-index: 10; }\r\n#chards-coll .coll-card.locked { cursor: default; opacity: .5; }\r\n\r\n#chards-coll .coll-card-inner {\r\n  position: relative; width: 100%; height: 100%;\r\n  border-radius: var(--r); overflow: hidden;\r\n  border: 1px solid var(--border);\r\n  background: var(--surface2);\r\n  transition: border-color .2s, box-shadow .2s, transform .2s;\r\n}\r\n#chards-coll .coll-card:not(.locked):hover .coll-card-inner {\r\n  border-color: var(--border-hi);\r\n  box-shadow: 0 6px 24px rgba(0,0,0,.7), 0 0 12px rgba(201,168,76,.15);\r\n  transform: translateY(-4px) scale(1.03);\r\n}\r\n#chards-coll .coll-card img.coll-art {\r\n  width: 100%; height: 100%; object-fit: cover; display: block;\r\n}\r\n#chards-coll .coll-card img.coll-border {\r\n  position: absolute;\r\n  top: -25%; left: -25%;\r\n  width: 150%; height: 150%;\r\n  pointer-events: none; object-fit: contain;\r\n}\r\n#chards-coll .coll-locked-slot {\r\n  width: 100%; height: 100%;\r\n  display: flex; align-items: center; justify-content: center;\r\n}\r\n#chards-coll .coll-locked-icon { font-size: 22px; opacity: .2; }\r\n\r\n/* card name below */\r\n#chards-coll .coll-card-name {\r\n  text-align: center;\r\n  font-size: 11px;\r\n  color: var(--muted);\r\n  margin-top: 5px;\r\n  white-space: nowrap;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  padding: 0 2px;\r\n}\r\n#chards-coll .coll-card-name.owned { color: var(--parch); }\r\n\r\n/* rarity pip */\r\n#chards-coll .coll-rarity-pip {\r\n  position: absolute; bottom: 4px; left: 50%;\r\n  transform: translateX(-50%);\r\n  font-size: 8px; font-family: \'Cinzel\', serif;\r\n  letter-spacing: .05em; padding: 2px 5px;\r\n  border-radius: 8px; background: rgba(0,0,0,.8);\r\n  white-space: nowrap; pointer-events: none;\r\n}\r\n\r\n/* merge badge */\r\n#chards-coll .coll-merge-badge {\r\n  position: absolute; top: 4px; right: 4px;\r\n  font-size: 9px; font-family: \'Cinzel\', serif;\r\n  padding: 2px 5px; border-radius: 8px;\r\n  background: rgba(201,168,76,0.85);\r\n  color: #0a0806; pointer-events: none;\r\n}\r\n\r\n/* qty badge */\r\n#chards-coll .coll-qty-badge {\r\n  position: absolute; top: 4px; left: 4px;\r\n  font-size: 9px; font-family: \'Cinzel\', serif;\r\n  padding: 2px 5px; border-radius: 8px;\r\n  background: rgba(0,0,0,.75);\r\n  color: var(--parch); pointer-events: none;\r\n}\r\n\r\n/* ── LIGHTBOX ── */\r\n#coll-lightbox {\r\n  display: none; position: fixed; inset: 0; z-index: 1000;\r\n  background: rgba(0,0,0,.88);\r\n  backdrop-filter: blur(6px);\r\n  align-items: center; justify-content: center; padding: 24px;\r\n}\r\n#coll-lightbox.open { display: flex; }\r\n\r\n.coll-lb-wrap {\r\n  display: flex; flex-direction: column;\r\n  max-width: 680px; width: 100%; gap: 16px;\r\n  animation: lbIn .25s ease;\r\n}\r\n@keyframes lbIn {\r\n  from { opacity:0; transform:scale(.93) translateY(10px); }\r\n  to   { opacity:1; transform:scale(1)   translateY(0); }\r\n}\r\n\r\n.coll-lb-main {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  gap: 16px;\r\n}\r\n@media(max-width:520px) { .coll-lb-main { flex-direction: column; align-items: center; } }\r\n\r\n.coll-lb-card {\r\n  position: relative;\r\n  width: 100%;\r\n  max-width: 280px;\r\n  flex-shrink: 0;\r\n  aspect-ratio: 3/4;\r\n  border-radius: var(--r);\r\n  border: 1px solid var(--border-hi);\r\n  box-shadow: 0 12px 40px rgba(0,0,0,.8);\r\n}\r\n	/* Lightbox Card & Border Size */\r\n.coll-lb-card img.lb-art {\r\n  position: absolute; top: -75px; left: -15px;\r\n  width: 112%; height: 112%; object-fit: cover; display: block;\r\n}\r\n.coll-lb-card img.lb-border {\r\n  position: absolute; top: -200px; left: -95px;\r\n  width: 175%; height: 175%;\r\n  pointer-events: none; object-fit: contain;\r\n}\r\n\r\n.coll-lb-info {\r\n  flex: 1;\r\n  min-width: 0;\r\n  width: 100%;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  text-align: center;\r\n}\r\n.coll-lb-rarity {\r\n  font-size: 10px; font-family: \'Cinzel\', serif;\r\n  letter-spacing: .1em; margin-bottom: 6px;\r\n}\r\n.coll-lb-name {\r\n  font-family: \'Cinzel Decorative\', serif;\r\n  font-size: clamp(13px, 3vw, 18px);\r\n  color: var(--gold); margin-bottom: 8px; line-height: 1.3;\r\n}\r\n.coll-lb-desc {\r\n  font-size: 14px; color: var(--parch);\r\n  line-height: 1.6; margin-bottom: 8px;\r\n}\r\n.coll-lb-flavour {\r\n  font-size: 12px;\r\n  font-style: italic;\r\n  color: var(--muted);\r\n  line-height: 1.5;\r\n  border-left: none;\r\n  border-top: 1px solid var(--gold-dim);\r\n  padding: 8px 0 0 0;\r\n  margin-bottom: 10px;\r\n  text-align: center;\r\n}\r\n.coll-lb-meta { font-size: 11px; color: var(--muted); margin-bottom: 14px; }\r\n\r\n/* Rarity tiers row */\r\n.coll-lb-tiers {\r\n  display: flex;\r\n  gap: 8px;\r\n  flex-wrap: wrap;\r\n  margin-bottom: 12px;\r\n  justify-content: center;\r\n  width: 100%;\r\n}\r\n.coll-lb-tier {\r\n  display: flex; flex-direction: column; align-items: center; gap: 4px;\r\n  cursor: pointer; opacity: .35; transition: opacity .2s, transform .2s;\r\n}\r\n.coll-lb-tier.owned   { opacity: 1; }\r\n.coll-lb-tier.active  { transform: scale(1.12); }\r\n.coll-lb-tier:hover   { opacity: .75; }\r\n.coll-lb-tier.owned:hover { opacity: 1; }\r\n.coll-lb-tier-thumb {\r\n  width: 36px; height: 48px; border-radius: 4px; overflow: hidden;\r\n  border: 1px solid var(--border); background: var(--surface2);\r\n  position: relative;\r\n}\r\n.coll-lb-tier-thumb img.t-art {\r\n  width:100%; height:100%; object-fit:cover; display:block;\r\n}\r\n.coll-lb-tier-thumb img.t-border {\r\n  position:absolute; top:-25%; left:-25%;\r\n  width:150%; height:150%; object-fit:contain; pointer-events:none;\r\n}\r\n.coll-lb-tier-label {\r\n  font-size: 8px; font-family: \'Cinzel\', serif;\r\n  letter-spacing: .05em; text-align: center;\r\n}\r\n.coll-lb-tier-qty {\r\n  font-size: 9px; color: var(--muted); font-family: monospace;\r\n}\r\n\r\n/* merge button */\r\n.coll-lb-merge {\r\n  font-family: \'Cinzel\', serif; font-size: 10px;\r\n  letter-spacing: .08em; padding: 8px 18px;\r\n  border-radius: 4px; border: none; cursor: pointer;\r\n  background: rgba(201,168,76,0.85); color: #0a0806;\r\n  transition: background .2s; display: none;\r\n}\r\n.coll-lb-merge:hover { background: var(--gold); }\r\n.coll-lb-merge.show  { display: inline-flex; align-items: center; gap: 6px; }\r\n\r\n.coll-lb-merge-info {\r\n  font-size: 12px; color: var(--muted); font-style: italic;\r\n  margin-top: 4px; display: none;\r\n}\r\n.coll-lb-merge-info.show { display: block; }\r\n\r\n.coll-lb-close {\r\n  position: absolute; top: 16px; right: 16px;\r\n  background: transparent; border: 1px solid var(--border);\r\n  color: var(--muted); font-size: 18px;\r\n  width: 32px; height: 32px; border-radius: 50%;\r\n  cursor: pointer; display: flex; align-items: center; justify-content: center;\r\n  transition: border-color .15s, color .15s;\r\n}\r\n.coll-lb-close:hover { border-color: var(--border-hi); color: var(--parch); }\r\n\r\n/* empty state */\r\n#chards-coll .coll-empty {\r\n  text-align: center; padding: 50px 24px;\r\n  color: var(--muted); font-size: 15px; font-style: italic;\r\n}\r\n#coll-merge-confirm {\r\n  display: none; position: fixed; inset: 0; z-index: 1100;\r\n  background: rgba(0,0,0,.7);\r\n  backdrop-filter: blur(4px);\r\n  align-items: center; justify-content: center; padding: 24px;\r\n}\r\n#coll-merge-confirm.open { display: flex; }\r\n\r\n.coll-mc-wrap {\r\n  background: var(--surface2);\r\n  border: 1px solid var(--border-hi);\r\n  border-radius: var(--r);\r\n  padding: 28px 24px;\r\n  max-width: 320px; width: 100%;\r\n  display: flex; flex-direction: column; align-items: center; gap: 16px;\r\n  animation: lbIn .2s ease;\r\n}\r\n.coll-mc-title {\r\n  font-family: \'Cinzel Decorative\', serif;\r\n  font-size: 14px; color: var(--gold); letter-spacing: .06em;\r\n}\r\n.coll-mc-msg {\r\n  font-size: 14px; color: var(--parch);\r\n  text-align: center; line-height: 1.5;\r\n}\r\n.coll-mc-btns {\r\n  display: flex; gap: 12px;\r\n}\r\n.coll-mc-btn {\r\n  font-family: \'Cinzel\', serif; font-size: 11px;\r\n  letter-spacing: .08em; padding: 8px 20px;\r\n  border-radius: 4px; border: none; cursor: pointer;\r\n  transition: background .2s;\r\n}\r\n.coll-mc-yes {\r\n  background: rgba(201,168,76,0.85); color: #0a0806;\r\n}\r\n.coll-mc-yes:hover { background: var(--gold); }\r\n.coll-mc-no {\r\n  background: var(--surface); color: var(--muted);\r\n  border: 1px solid var(--border);\r\n}\r\n.coll-mc-no:hover { border-color: var(--border-hi); color: var(--parch); }\r\n</style>\r\n\r\n<div id=\"chards-coll\">\r\n\r\n  <header class=\"coll-header\">\r\n    <div class=\"coll-top-row\">\r\n      <div class=\"coll-title\">My Collection</div>\r\n      <a href=\"<?= home_url(\'/index.php/hub/\') ?>\" class=\"coll-hub-link\">⌂ Hub</a>\r\n    </div>\r\n    <div class=\"coll-chapter-row\">\r\n      <select class=\"coll-chapter-select\" id=\"chapter-select\"\r\n              onchange=\"window.location.href=\'?chapter=\'+this.value\">\r\n        <?php foreach ($chapters as $ch): ?>\r\n          <option value=\"<?= $ch[\'id\'] ?>\"\r\n                  <?= $ch[\'id\'] === $selected_chapter ? \'selected\' : \'\' ?>>\r\n            <?= htmlspecialchars($ch[\'name\']) ?>\r\n          </option>\r\n        <?php endforeach; ?>\r\n      </select>\r\n      <?php if ($total > 0): ?>\r\n      <div class=\"coll-progress\">\r\n        <span><?= $owned_n ?></span>\r\n        <div class=\"coll-pbar\">\r\n          <div class=\"coll-pfill\" style=\"width:<?= $total ? round($owned_n/$total*100) : 0 ?>%\"></div>\r\n        </div>\r\n        <span><?= $total ?></span>\r\n      </div>\r\n      <?php endif; ?>\r\n    </div>\r\n  </header>\r\n\r\n  <div class=\"coll-wrap\">\r\n    <?php if (empty($card_families)): ?>\r\n      <div class=\"coll-empty\">No collectible cards in this chapter yet.</div>\r\n    <?php else: ?>\r\n    <div class=\"coll-grid\">\r\n      <?php foreach ($card_families as $fam):\r\n        $owned       = $fam[\'is_owned\'];\r\n        $highest     = $fam[\'highest_owned\'];\r\n        $base        = $fam[\'base\'];\r\n\r\n        /* Highest quantity owned for merge check */\r\n        $top_qty     = $highest ? (int)$highest[\'quantity\'] : 0;\r\n        $can_merge   = $top_qty >= 5;\r\n\r\n        /* Build JS data for lightbox */\r\n        $tiers_js = json_encode(array_map(function($t) use ($fam) {\r\n            $owned_tier = null;\r\n            foreach ($fam[\'owned_tiers\'] as $ot) {\r\n                if ($ot[\'card_id\'] == $t[\'id\']) { $owned_tier = $ot; break; }\r\n            }\r\n            return [\r\n                \'id\'           => $t[\'id\'],\r\n                \'rarity_label\' => $t[\'rarity_label\'],\r\n                \'color_hex\'    => $t[\'color_hex\'] ?? \'#c9a84c\',\r\n                \'border_url\'   => $t[\'border_url\'] ?? \'\',\r\n                \'image_url\'    => $t[\'image_url\'] ?? \'\',\r\n                \'sort_order\'   => $t[\'sort_order\'],\r\n                \'is_active\'    => (bool)$t[\'is_active\'],\r\n                \'owned\'        => $owned_tier !== null,\r\n                \'quantity\'     => $owned_tier ? (int)$owned_tier[\'quantity\'] : 0,\r\n            ];\r\n        }, $fam[\'all_tiers\']));\r\n\r\n        $card_data = htmlspecialchars(json_encode([\r\n            \'name\'       => $base[\'name\'],\r\n            \'desc\'       => $base[\'description\'] ?? \'\',\r\n            \'flavour\'    => $base[\'flavour_text\'] ?? \'\',\r\n            \'artist\'     => $base[\'artist\'] ?? \'\',\r\n            \'tiers\'      => json_decode($tiers_js, true),\r\n        ]), ENT_QUOTES);\r\n      ?>\r\n      <div class=\"coll-card <?= $owned ? \'\' : \'locked\' ?>\"\r\n           <?= $owned ? \"onclick=\\\"openCollLightbox(this)\\\" data-card=\'{$card_data}\'\" : \'\' ?>>\r\n        <div class=\"coll-card-inner\">\r\n          <?php if ($owned && $highest): ?>\r\n            <?php if ($highest[\'image_url\']): ?>\r\n              <img class=\"coll-art\" src=\"<?= htmlspecialchars($highest[\'image_url\']) ?>\"\r\n                   alt=\"<?= htmlspecialchars($base[\'name\']) ?>\" loading=\"lazy\">\r\n            <?php endif; ?>\r\n            <?php if ($highest[\'border_url\']): ?>\r\n              <img class=\"coll-border\" src=\"<?= htmlspecialchars($highest[\'border_url\']) ?>\" alt=\"\">\r\n            <?php endif; ?>\r\n            <span class=\"coll-rarity-pip\"\r\n                  style=\"color:<?= htmlspecialchars($highest[\'color_hex\'] ?? \'#c9a84c\') ?>\">\r\n              <?= htmlspecialchars($highest[\'rarity_label\']) ?>\r\n            </span>\r\n            <?php if ($top_qty > 1): ?>\r\n              <span class=\"coll-qty-badge\">×<?= $top_qty ?></span>\r\n            <?php endif; ?>\r\n            <?php if ($can_merge): ?>\r\n              <span class=\"coll-merge-badge\">MERGE</span>\r\n            <?php endif; ?>\r\n          <?php else: ?>\r\n            <div class=\"coll-locked-slot\">\r\n              <span class=\"coll-locked-icon\">✦</span>\r\n            </div>\r\n          <?php endif; ?>\r\n        </div>\r\n        <div class=\"coll-card-name <?= $owned ? \'owned\' : \'\' ?>\">\r\n          <?= htmlspecialchars($base[\'name\']) ?>\r\n        </div>\r\n      </div>\r\n      <?php endforeach; ?>\r\n    </div>\r\n    <?php endif; ?>\r\n  </div>\r\n\r\n</div><!-- /chards-coll -->\r\n\r\n<!-- Lightbox -->\r\n<div id=\"coll-lightbox\" onclick=\"if(event.target===this)closeCollLightbox()\">\r\n	<!-- Merge Confirm Modal -->\r\n	<div id=\"coll-merge-confirm\" onclick=\"if(event.target===this)closeMergeConfirm()\">\r\n	  <div class=\"coll-mc-wrap\">\r\n		<div class=\"coll-mc-title\">Confirm Merge</div>\r\n		<div class=\"coll-mc-msg\">Combine 5 copies into one higher-tier card?</div>\r\n		<div class=\"coll-mc-btns\">\r\n		  <button class=\"coll-mc-btn coll-mc-yes\" onclick=\"confirmMerge()\">Merge</button>\r\n		  <button class=\"coll-mc-btn coll-mc-no\"  onclick=\"closeMergeConfirm()\">Cancel</button>\r\n		</div>\r\n	  </div>\r\n	</div>\r\n  <div class=\"coll-lb-wrap\">\r\n    <div class=\"coll-lb-main\">\r\n\r\n      <!-- Card display -->\r\n      <div class=\"coll-lb-card\" id=\"lb-card\">\r\n        <img class=\"lb-art\"    id=\"lb-art\"    src=\"\" alt=\"\">\r\n        <img class=\"lb-border\" id=\"lb-border\" src=\"\" alt=\"\" style=\"display:none\">\r\n      </div>\r\n\r\n      <!-- Info -->\r\n      <div class=\"coll-lb-info\">\r\n        <div class=\"coll-lb-rarity\"  id=\"lb-rarity\"></div>\r\n        <div class=\"coll-lb-name\"    id=\"lb-name\"></div>\r\n        <div class=\"coll-lb-desc\"    id=\"lb-desc\"></div>\r\n        <div class=\"coll-lb-flavour\" id=\"lb-flavour\" style=\"display:none\"></div>\r\n        <div class=\"coll-lb-meta\"    id=\"lb-meta\"></div>\r\n\r\n        <!-- Rarity tier selector -->\r\n        <div class=\"coll-lb-tiers\"   id=\"lb-tiers\"></div>\r\n\r\n        <!-- Merge -->\r\n        <button class=\"coll-lb-merge\" id=\"lb-merge-btn\" onclick=\"doMerge()\"></button>\r\n        <div class=\"coll-lb-merge-info\" id=\"lb-merge-info\"></div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n  <button class=\"coll-lb-close\" onclick=\"closeCollLightbox()\">✕</button>\r\n</div>\r\n\r\n<script>\r\nvar COLL_AJAX = \'<?= esc_url(admin_url(\'admin-ajax.php\')) ?>\';\r\nvar currentCard   = null;\r\nvar activeTierId  = null;\r\n\r\nfunction openCollLightbox(el) {\r\n  var data = JSON.parse(el.getAttribute(\'data-card\'));\r\n  currentCard = data;\r\n\r\n  document.getElementById(\'lb-name\').textContent    = data.name    || \'\';\r\n  document.getElementById(\'lb-desc\').textContent    = data.desc    || \'\';\r\n  var flavEl = document.getElementById(\'lb-flavour\');\r\n  flavEl.textContent   = data.flavour || \'\';\r\n  flavEl.style.display = data.flavour ? \'\' : \'none\';\r\n  document.getElementById(\'lb-meta\').textContent =\r\n    data.artist ? \'Art by \' + data.artist : \'\';\r\n\r\n  /* Build tier selector */\r\n  buildTiers(data.tiers);\r\n\r\n  /* Show highest owned tier by default */\r\n  var highestOwned = null;\r\n  data.tiers.slice().reverse().forEach(function(t) {\r\n    if (t.owned && !highestOwned) highestOwned = t;\r\n  });\r\n  if (highestOwned) selectTier(highestOwned);\r\n\r\n  document.getElementById(\'coll-lightbox\').classList.add(\'open\');\r\n}\r\n\r\nfunction buildTiers(tiers) {\r\n  var container = document.getElementById(\'lb-tiers\');\r\n  container.innerHTML = \'\';\r\n  var maxOwnedOrder = false;\r\n  tiers.slice().reverse().forEach(function(t) {\r\n	  if (t.owned) {\r\n		  maxOwnedOrder = true; /* max owned tier found */\r\n	  }\r\n	  if (maxOwnedOrder)\r\n	  	var div = document.createElement(\'div\'); \r\n	  else \r\n		  return;\r\n	  div.className = \'coll-lb-tier\' + (t.owned ? \' owned\' : \'\');\r\n	  div.setAttribute(\'data-tier\', JSON.stringify(t));\r\n	  div.onclick = function() { if (t.owned) selectTier(t); };\r\n\r\n	  var thumb = document.createElement(\'div\');\r\n	  thumb.className = \'coll-lb-tier-thumb\';\r\n    if (t.image_url) {\r\n      var art = document.createElement(\'img\');\r\n      art.className = \'t-art\'; art.src = t.image_url;\r\n      thumb.appendChild(art);\r\n    }\r\n    if (t.border_url) {\r\n      var brd = document.createElement(\'img\');\r\n      brd.className = \'t-border\'; brd.src = t.border_url;\r\n      thumb.appendChild(brd);\r\n    }\r\n\r\n    var label = document.createElement(\'div\');\r\n    label.className = \'coll-lb-tier-label\';\r\n    label.style.color = t.color_hex || \'#c9a84c\';\r\n    label.textContent = t.rarity_label;\r\n\r\n    var qty = document.createElement(\'div\');\r\n    qty.className = \'coll-lb-tier-qty\';\r\n    qty.textContent = t.owned ? \'×\' + t.quantity : \'—\';\r\n\r\n    div.appendChild(thumb);\r\n    div.appendChild(label);\r\n    div.appendChild(qty);\r\n    container.appendChild(div);\r\n  });\r\n}\r\n\r\nfunction selectTier(tier) {\r\n  activeTierId = tier.id;\r\n\r\n  /* Update card display */\r\n  var art = document.getElementById(\'lb-art\');\r\n  var brd = document.getElementById(\'lb-border\');\r\n  art.src = tier.image_url || \'\';\r\n  if (tier.border_url) {\r\n    brd.src = tier.border_url; brd.style.display = \'\';\r\n  } else {\r\n    brd.style.display = \'none\';\r\n  }\r\n\r\n  /* Update rarity label */\r\n  var rarEl = document.getElementById(\'lb-rarity\');\r\n  rarEl.textContent = tier.rarity_label;\r\n  rarEl.style.color = tier.color_hex || \'#c9a84c\';\r\n\r\n  /* Highlight active tier */\r\n  document.querySelectorAll(\'.coll-lb-tier\').forEach(function(el) {\r\n    el.classList.remove(\'active\');\r\n    var t = JSON.parse(el.getAttribute(\'data-tier\'));\r\n    if (t.id === tier.id) el.classList.add(\'active\');\r\n  });\r\n\r\n  /* Merge button */\r\n  var mergeBtn  = document.getElementById(\'lb-merge-btn\');\r\n  var mergeInfo = document.getElementById(\'lb-merge-info\');\r\n  var MERGE_COST = 5;\r\n\r\n  if (tier.owned && tier.quantity >= MERGE_COST) {\r\n    mergeBtn.textContent = \'⚗ Merge (\' + tier.quantity + \'/\' + MERGE_COST + \')\';\r\n    mergeBtn.classList.add(\'show\');\r\n    mergeBtn.setAttribute(\'data-card-id\', tier.id);\r\n    mergeInfo.textContent = \'Combine \' + MERGE_COST + \' copies to upgrade to the next rarity tier.\';\r\n    mergeInfo.classList.add(\'show\');\r\n  } else if (tier.owned) {\r\n    mergeBtn.classList.remove(\'show\');\r\n    mergeInfo.textContent = tier.quantity + \'/\' + MERGE_COST + \' copies — collect more to merge.\';\r\n    mergeInfo.classList.add(\'show\');\r\n  } else {\r\n    mergeBtn.classList.remove(\'show\');\r\n    mergeInfo.classList.remove(\'show\');\r\n  }\r\n}\r\n\r\nfunction doMerge() {\r\n  var cardId = document.getElementById(\'lb-merge-btn\').getAttribute(\'data-card-id\');\r\n  if (!cardId) return;\r\n  document.getElementById(\'coll-merge-confirm\').classList.add(\'open\');\r\n}\r\n\r\nfunction confirmMerge() {\r\n  closeMergeConfirm();\r\n  var cardId = document.getElementById(\'lb-merge-btn\').getAttribute(\'data-card-id\');\r\n  if (!cardId) return;\r\n\r\n  fetch(window.location.href, {\r\n    method: \'POST\',\r\n    headers: { \'Content-Type\': \'application/x-www-form-urlencoded\' },\r\n    body: \'action=merge_card&card_id=\' + cardId\r\n  })\r\n  .then(function(r) { return r.json(); })\r\n  .then(function(res) {\r\n    if (res.ok) {\r\n      closeCollLightbox();\r\n      window.location.reload();\r\n    } else {\r\n      alert(res.msg || \'Merge failed.\');\r\n    }\r\n  });\r\n}\r\n\r\nfunction closeMergeConfirm() {\r\n  document.getElementById(\'coll-merge-confirm\').classList.remove(\'open\');\r\n}\r\n\r\nfunction closeCollLightbox() {\r\n  document.getElementById(\'coll-lightbox\').classList.remove(\'open\');\r\n  currentCard  = null;\r\n  activeTierId = null;\r\n}\r\n\r\ndocument.addEventListener(\'keydown\', function(e) {\r\n  if (e.key === \'Escape\') {\r\n	  closeMergeConfirm();\r\n	  closeCollLightbox();\r\n  } \r\n});\r\n</script>',	'collection',	'',	'publish',	'closed',	'closed',	'',	'collection',	'',	'',	'2026-07-27 19:14:32',	'2026-07-27 19:14:32',	'',	0,	'https://chards.wasmer.app/?post_type=wpcode&#038;p=147',	0,	'wpcode',	'',	0),
