(152,	1,	'2026-05-12 20:52:09',	'2026-05-12 20:52:09',	'if (!function_exists(\'chards_admin_db\')) {\r\n    function chards_admin_db() {\r\n        static $pdo;\r\n        if ($pdo) return $pdo;\r\n        try {\r\n            $pdo = new PDO(\r\n                \'mysql:host=db.fr-pari1.bengt.wasmernet.com;port=10272;dbname=dbGQr4derPM6nWoRL4jPwNPN;charset=utf8mb4\',\r\n                \'0074c9f9784980005ded7796ee74\',\r\n                \'06950074-c9fa-7db2-8000-c0aec36ba1ac\',\r\n                [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]\r\n            );\r\n        } catch (PDOException $e) { $pdo = null; }\r\n        return $pdo;\r\n    }\r\n}\r\n\r\nif (!function_exists(\'chards_admin_ajax_handler\')) {\r\n    function chards_admin_ajax_handler() {\r\n        error_log(\'chards_admin_ajax fired, sub=\' . ($_POST[\'sub\'] ?? \'none\'));\r\n        $sub = isset($_POST[\'sub\']) ? $_POST[\'sub\'] : \'\';\r\n\r\n        /* ── CARDS ── */\r\n\r\n        if ($sub === \'add_collectible\') {\r\n            try {\r\n                chards_admin_db()->beginTransaction();\r\n                $is_event = $_POST[\'card_type\'] === \'event\';\r\n				\r\n				/* Reset auto_increment to eliminate gaps from deleted rows */\r\n				chards_admin_db()->exec(\"ALTER TABLE chards_cards AUTO_INCREMENT = 1\");\r\n				\r\n                $common_rarity = chards_admin_db()->query(\r\n                    \"SELECT id FROM chards_rarities ORDER BY sort_order ASC LIMIT 1\"\r\n                )->fetch();\r\n                $stmt = chards_admin_db()->prepare(\"\r\n                    INSERT INTO chards_cards\r\n                      (name, description, flavour_text, card_type, chapter_id,\r\n                       card_number, rarity_id, is_unique, print_run, upgrade_cost,\r\n                       image_url, artist, is_active)\r\n                    VALUES (?,?,?,?,?,?,?,0,?,5,?,?,1)\r\n                \");\r\n                $stmt->execute([\r\n                    trim($_POST[\'name\']),\r\n                    trim($_POST[\'description\'] ?? \'\'),\r\n                    trim($_POST[\'flavour_text\'] ?? \'\'),\r\n                    $_POST[\'card_type\'],\r\n                    (int)$_POST[\'chapter_id\'],\r\n                    (int)($_POST[\'card_number\'] ?? 0) ?: null,\r\n                    $is_event ? (int)$_POST[\'rarity_id\'] : $common_rarity[\'id\'],\r\n                    (int)($_POST[\'print_run\'] ?? 0) ?: null,\r\n                    trim($_POST[\'image_url\']),\r\n                    trim($_POST[\'artist\'] ?? \'\') ?: null,\r\n                ]);\r\n                $base_id = (int)chards_admin_db()->lastInsertId();\r\n                if (!$is_event) {\r\n                    $other_rarities = chards_admin_db()->query(\r\n                        \"SELECT id FROM chards_rarities ORDER BY sort_order ASC LIMIT 7 OFFSET 1\"\r\n                    )->fetchAll();\r\n                    $tier_stmt = chards_admin_db()->prepare(\"\r\n                        INSERT INTO chards_cards\r\n                          (name, description, flavour_text, card_type, chapter_id,\r\n                           card_number, rarity_id, is_unique, print_run, upgrade_cost,\r\n                           image_url, artist, is_active, base_card_id)\r\n                        VALUES (?,?,?,?,?,?,?,0,?,5,\'\',?,0,?)\r\n                    \");\r\n                    foreach ($other_rarities as $r) {\r\n                        $tier_stmt->execute([\r\n                            trim($_POST[\'name\']),\r\n                            trim($_POST[\'description\'] ?? \'\'),\r\n                            trim($_POST[\'flavour_text\'] ?? \'\'),\r\n                            \'collectible\',\r\n                            (int)$_POST[\'chapter_id\'],\r\n                            (int)($_POST[\'card_number\'] ?? 0) ?: null,\r\n                            $r[\'id\'],\r\n                            (int)($_POST[\'print_run\'] ?? 0) ?: null,\r\n                            trim($_POST[\'artist\'] ?? \'\') ?: null,\r\n                            $base_id,\r\n                        ]);\r\n                    }\r\n                    $msg = \'Collectible card added with 7 rarity tiers.\';\r\n                } else {\r\n                    $msg = \'Event card added successfully.\';\r\n                }\r\n                chards_admin_db()->commit();\r\n                wp_send_json_success([\'msg\' => $msg]);\r\n            } catch (PDOException $e) {\r\n                chards_admin_db()->rollBack();\r\n                wp_send_json_error([\'msg\' => \'Error: \' . $e->getMessage()]);\r\n            }\r\n        }\r\n\r\n        elseif ($sub === \'update_tier\') {\r\n            try {\r\n                chards_admin_db()->prepare(\"\r\n                    UPDATE chards_cards SET image_url=?, is_active=?\r\n                    WHERE id=? AND card_type=\'collectible\'\r\n                \")->execute([\r\n                    trim($_POST[\'image_url\']),\r\n                    isset($_POST[\'is_active\']) ? 1 : 0,\r\n                    (int)$_POST[\'tier_id\'],\r\n                ]);\r\n                wp_send_json_success([\'msg\' => \'Tier updated successfully.\']);\r\n            } catch (PDOException $e) {\r\n                wp_send_json_error([\'msg\' => \'Error: \' . $e->getMessage()]);\r\n            }\r\n        }\r\n\r\n        elseif ($sub === \'add_chapter\') {\r\n            $slug = preg_replace(\'/[^a-z0-9-]/\', \'-\', strtolower(trim($_POST[\'chapter_name\'])));\r\n            try {\r\n                chards_admin_db()->prepare(\r\n                    \"INSERT INTO chards_chapters (slug, name, release_date, is_active) VALUES (?,?,?,?)\"\r\n                )->execute([\r\n                    $slug,\r\n                    trim($_POST[\'chapter_name\']),\r\n                    $_POST[\'release_date\'] ?: null,\r\n                    isset($_POST[\'is_active\']) ? 1 : 0,\r\n                ]);\r\n                wp_send_json_success([\'msg\' => \'Chapter added successfully.\']);\r\n            } catch (PDOException $e) {\r\n                wp_send_json_error([\'msg\' => \'Error: \' . $e->getMessage()]);\r\n            }\r\n        }\r\n\r\n        elseif ($sub === \'add_card\') {\r\n            try {\r\n				/* Reset auto_increment to eliminate gaps from deleted rows */\r\n				chards_admin_db()->exec(\"ALTER TABLE chards_cards AUTO_INCREMENT = 1\");\r\n                chards_admin_db()->prepare(\"\r\n                    INSERT INTO chards_cards\r\n                      (name, description, flavour_text, card_type, chapter_id, card_number,\r\n                       panel_page, panel_number, rarity_id, is_unique, print_run, image_url, artist)\r\n                    VALUES (?,?,?,\'story\',?,?,?,?,?,1,1,?,?)\r\n                \")->execute([\r\n                    trim($_POST[\'name\']),\r\n                    trim($_POST[\'description\'] ?? \'\'),\r\n                    trim($_POST[\'flavour_text\'] ?? \'\'),\r\n                    (int)$_POST[\'chapter_id\'],\r\n                    (int)($_POST[\'card_number\'] ?? 0),\r\n                    (int)$_POST[\'panel_page\'],\r\n                    (int)$_POST[\'panel_number\'],\r\n                    (int)$_POST[\'rarity_id\'],\r\n                    trim($_POST[\'image_url\']),\r\n                    trim($_POST[\'artist\'] ?? \'\') ?: null,\r\n                ]);\r\n                wp_send_json_success([\'msg\' => \'Story card added successfully.\']);\r\n            } catch (PDOException $e) {\r\n                wp_send_json_error([\'msg\' => \'Error: \' . $e->getMessage()]);\r\n            }\r\n        }\r\n\r\n        elseif ($sub === \'reset_finds\') {\r\n            $chapter_id_reset = (int)$_POST[\'reset_chapter_id\'];\r\n            try {\r\n                chards_admin_db()->prepare(\"\r\n                    DELETE sf FROM chards_story_finds sf\r\n                    JOIN chards_cards c ON c.id = sf.card_id\r\n                    WHERE c.chapter_id = ? AND c.card_type = \'story\'\r\n                \")->execute([$chapter_id_reset]);\r\n                chards_admin_db()->prepare(\"\r\n                    UPDATE chards_cards SET is_available = 1\r\n                    WHERE chapter_id = ? AND card_type = \'story\'\r\n                \")->execute([$chapter_id_reset]);\r\n                wp_send_json_success([\'msg\' => \'All story panels reset to unfound.\']);\r\n            } catch (PDOException $e) {\r\n                wp_send_json_error([\'msg\' => \'Error: \' . $e->getMessage()]);\r\n            }\r\n        }\r\n\r\n        elseif ($sub === \'edit_card\') {\r\n            try {\r\n                chards_admin_db()->prepare(\"\r\n                    UPDATE chards_cards SET\r\n                      name=?, description=?, flavour_text=?,\r\n                      chapter_id=?, card_number=?,\r\n                      panel_page=?, panel_number=?,\r\n                      rarity_id=?, image_url=?,\r\n                      artist=?, is_active=?\r\n                    WHERE id=? AND card_type=\'story\'\r\n                \")->execute([\r\n                    trim($_POST[\'name\']),\r\n                    trim($_POST[\'description\'] ?? \'\'),\r\n                    trim($_POST[\'flavour_text\'] ?? \'\'),\r\n                    (int)$_POST[\'chapter_id\'],\r\n                    (int)($_POST[\'card_number\'] ?? 0),\r\n                    (int)$_POST[\'panel_page\'],\r\n                    (int)$_POST[\'panel_number\'],\r\n                    (int)$_POST[\'rarity_id\'],\r\n                    trim($_POST[\'image_url\']),\r\n                    trim($_POST[\'artist\'] ?? \'\') ?: null,\r\n                    isset($_POST[\'is_active\']) ? 1 : 0,\r\n                    (int)$_POST[\'card_id\'],\r\n                ]);\r\n                wp_send_json_success([\'msg\' => \'Card updated successfully.\']);\r\n            } catch (PDOException $e) {\r\n                wp_send_json_error([\'msg\' => \'Error: \' . $e->getMessage()]);\r\n            }\r\n        }\r\n\r\n        /* ── FRAGMENTA TYPES ── */\r\n\r\n        elseif ($sub === \'add_fragmenta_type\') {\r\n            try {\r\n                $min_rarity = (int)($_POST[\'minimum_rarity\'] ?? 0) ?: null;\r\n                chards_admin_db()->prepare(\"\r\n                    INSERT INTO chards_fragmenta_types\r\n                      (name, cooldown_minutes, cards_per_pack, story_chance, minimum_rarity)\r\n                    VALUES (?,?,?,?,?)\r\n                \")->execute([\r\n                    trim($_POST[\'type_name\']),\r\n                    (int)$_POST[\'cooldown_minutes\'],\r\n                    (int)$_POST[\'cards_per_pack\'],\r\n                    (float)$_POST[\'story_chance\'],\r\n                    $min_rarity,\r\n                ]);\r\n                wp_send_json_success([\'msg\' => \'Fragmenta type created.\']);\r\n            } catch (PDOException $e) {\r\n                wp_send_json_error([\'msg\' => \'Error: \' . $e->getMessage()]);\r\n            }\r\n        }\r\n\r\n        elseif ($sub === \'edit_fragmenta_type\') {\r\n            try {\r\n                $min_rarity = (int)($_POST[\'minimum_rarity\'] ?? 0) ?: null;\r\n                chards_admin_db()->prepare(\"\r\n                    UPDATE chards_fragmenta_types SET\r\n                      name=?, cooldown_minutes=?, cards_per_pack=?,\r\n                      story_chance=?, minimum_rarity=?\r\n                    WHERE id=?\r\n                \")->execute([\r\n                    trim($_POST[\'type_name\']),\r\n                    (int)$_POST[\'cooldown_minutes\'],\r\n                    (int)$_POST[\'cards_per_pack\'],\r\n                    (float)$_POST[\'story_chance\'],\r\n                    $min_rarity,\r\n                    (int)$_POST[\'type_id\'],\r\n                ]);\r\n                wp_send_json_success([\'msg\' => \'Type updated.\']);\r\n            } catch (PDOException $e) {\r\n                wp_send_json_error([\'msg\' => \'Error: \' . $e->getMessage()]);\r\n            }\r\n        }\r\n\r\n        elseif ($sub === \'delete_fragmenta_type\') {\r\n            try {\r\n                $in_use = chards_admin_db()->prepare(\r\n                    \"SELECT COUNT(*) AS n FROM chards_fragmenta WHERE type_id = ?\"\r\n                );\r\n                $in_use->execute([(int)$_POST[\'type_id\']]);\r\n                if ((int)$in_use->fetch()[\'n\'] > 0) {\r\n                    wp_send_json_error([\'msg\' => \'Cannot delete — Fragmenta cards are assigned to this type.\']);\r\n                    return;\r\n                }\r\n                chards_admin_db()->prepare(\r\n                    \"DELETE FROM chards_fragmenta_types WHERE id = ?\"\r\n                )->execute([(int)$_POST[\'type_id\']]);\r\n                wp_send_json_success([\'msg\' => \'Type deleted.\']);\r\n            } catch (PDOException $e) {\r\n                wp_send_json_error([\'msg\' => \'Error: \' . $e->getMessage()]);\r\n            }\r\n        }\r\n\r\n        /* ── FRAGMENTA NFC CARDS ── */\r\n\r\n        elseif ($sub === \'register_fragmenta\') {\r\n            try {\r\n                $uid = trim($_POST[\'uid\'] ?? \'\');\r\n                if (!$uid) {\r\n                    wp_send_json_error([\'msg\' => \'UID is required.\']);\r\n                    return;\r\n                }\r\n                $exists = chards_admin_db()->prepare(\r\n                    \"SELECT id FROM chards_fragmenta WHERE uid = ?\"\r\n                );\r\n                $exists->execute([$uid]);\r\n                if ($exists->fetch()) {\r\n                    wp_send_json_error([\'msg\' => \'A Fragmenta with this UID already exists.\']);\r\n                    return;\r\n                }\r\n                chards_admin_db()->prepare(\"\r\n                    INSERT INTO chards_fragmenta (uid, type_id, is_locked)\r\n                    VALUES (?,?,0)\r\n                \")->execute([\r\n                    $uid,\r\n                    (int)$_POST[\'type_id\'],\r\n                ]);\r\n                wp_send_json_success([\'msg\' => \'Fragmenta registered: \' . $uid]);\r\n            } catch (PDOException $e) {\r\n                wp_send_json_error([\'msg\' => \'Error: \' . $e->getMessage()]);\r\n            }\r\n        }\r\n\r\n        elseif ($sub === \'toggle_fragmenta_lock\') {\r\n            try {\r\n                $frag = chards_admin_db()->prepare(\r\n                    \"SELECT id, is_locked FROM chards_fragmenta WHERE id = ?\"\r\n                );\r\n                $frag->execute([(int)$_POST[\'frag_id\']]);\r\n                $row = $frag->fetch();\r\n                if (!$row) {\r\n                    wp_send_json_error([\'msg\' => \'Fragmenta not found.\']);\r\n                    return;\r\n                }\r\n                $new_state = $row[\'is_locked\'] ? 0 : 1;\r\n                chards_admin_db()->prepare(\r\n                    \"UPDATE chards_fragmenta SET is_locked = ? WHERE id = ?\"\r\n                )->execute([$new_state, (int)$_POST[\'frag_id\']]);\r\n                wp_send_json_success([\r\n                    \'msg\'       => $new_state ? \'Fragmenta locked.\' : \'Fragmenta unlocked.\',\r\n                    \'is_locked\' => $new_state,\r\n                ]);\r\n            } catch (PDOException $e) {\r\n                wp_send_json_error([\'msg\' => \'Error: \' . $e->getMessage()]);\r\n            }\r\n        }\r\n\r\n        elseif ($sub === \'delete_fragmenta\') {\r\n            try {\r\n                chards_admin_db()->prepare(\r\n                    \"DELETE FROM chards_fragmenta WHERE id = ?\"\r\n                )->execute([(int)$_POST[\'frag_id\']]);\r\n                wp_send_json_success([\'msg\' => \'Fragmenta deleted.\']);\r\n            } catch (PDOException $e) {\r\n                wp_send_json_error([\'msg\' => \'Error: \' . $e->getMessage()]);\r\n            }\r\n        }\r\n\r\n        elseif ($sub === \'fragmenta_log\') {\r\n            try {\r\n                $rows = chards_admin_db()->prepare(\"\r\n                    SELECT\r\n                        pl.opened_at,\r\n                        pl.user_id,\r\n                        u.username,\r\n                        p.finder_name,\r\n                        p.card_ids\r\n                    FROM chards_pack_log pl\r\n                    LEFT JOIN chards_packs p ON p.id   = pl.pack_id\r\n                    LEFT JOIN chards_users u ON u.id   = pl.user_id\r\n                    WHERE pl.fragmenta_id = ?\r\n                    ORDER BY pl.opened_at DESC\r\n                    LIMIT 20\r\n                \");\r\n                $rows->execute([(int)$_POST[\'frag_id\']]);\r\n                wp_send_json_success([\'log\' => $rows->fetchAll()]);\r\n            } catch (PDOException $e) {\r\n                wp_send_json_error([\'msg\' => \'Error: \' . $e->getMessage()]);\r\n            }\r\n        }\r\n\r\n        wp_die();\r\n    }\r\n}\r\n\r\nadd_action(\'wp_ajax_chards_admin\',        \'chards_admin_ajax_handler\');\r\nadd_action(\'wp_ajax_nopriv_chards_admin\', \'chards_admin_ajax_handler\');',	'settings help file',	'',	'publish',	'closed',	'closed',	'',	'settings-help-file',	'',	'',	'2026-07-27 18:41:38',	'2026-07-27 18:41:38',	'',	0,	'https://chards.wasmer.app/index.php/wpcode/settings-help-file/',	0,	'wpcode',	'',	0),
(153,	1,	'2026-05-14 19:39:18',	'2026-05-14 19:39:18',	'/* ============================================================\r\n   CHARDS — Landing Page Logic\r\n   Runs on the \'template_redirect\' hook so headers aren\'t sent yet.\r\n   Deploy via Code Snippets, Run Everywhere.\r\n   WordPress page slug: \'landing\'\r\n============================================================ */\r\n\r\nif (!function_exists(\'chards_landing_redirect\')) {\r\n    function chards_landing_redirect() {\r\necho \'<div style=\"position:fixed;top:0;left:0;z-index:9999;background:red;color:white;padding:20px;font-size:20px\">SHORTCODE IS RUNNING</div>\';\r\n       if (!session_id()) session_start();\r\n\r\n        /* ── Capture card ID ── */\r\n        $_SESSION[\'cardID\'] = isset($_GET[\'card\']) && $_GET[\'card\'] !== \'\'\r\n            ? trim($_GET[\'card\'])\r\n            : null;\r\n\r\n        /* ── DB ── */\r\n        $pdo = null;\r\n        try {\r\n            $pdo = new PDO(\r\n                \'mysql:host=db.fr-pari1.bengt.wasmernet.com;port=10272;dbname=dbGQr4derPM6nWoRL4jPwNPN;charset=utf8mb4\',\r\n                \'0074c9f9784980005ded7796ee74\',\r\n                \'06950074-c9fa-7db2-8000-c0aec36ba1ac\',\r\n                [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]\r\n            );\r\n        } catch (PDOException $e) {\r\n			echo \'<script type=\"text/javascript\">\r\n			window.location = \"https://chards.wasmer.app/index.php/login/\"\r\n			</script>\';\r\n        }\r\n\r\n        $logged_in = !empty($_SESSION[\'chards_user_id\']);\r\n\r\n        if ($logged_in) {\r\n            $user_id = (int)$_SESSION[\'chards_user_id\'];\r\n\r\n            if ($_SESSION[\'cardID\']) {\r\n                $stmt = $pdo->prepare(\"\r\n                    SELECT f.*, ft.cooldown_minutes, ft.cards_per_pack, ft.story_chance, ft.minimum_rarity\r\n                    FROM chards_fragmenta f\r\n                    JOIN chards_fragmenta_types ft ON ft.id = f.type_id\r\n                    WHERE f.uid = ?\r\n                \");\r\n                $stmt->execute([$_SESSION[\'cardID\']]);\r\n                $fragmenta = $stmt->fetch();\r\n\r\n                if (!$fragmenta) {\r\n                    $_SESSION[\'arc_scenario\'] = \'unknown_card\';\r\n					echo \'<script type=\"text/javascript\">\r\n					window.location = \"https://chards.wasmer.app/index.php/login/\"\r\n					</script>\';\r\n                }\r\n\r\n                $owner_id = $fragmenta[\'owner_user_id\'] ? (int)$fragmenta[\'owner_user_id\'] : null;\r\n\r\n                if ($owner_id === null) {\r\n                    /* Scenario D — logged in, unassigned NFC */\r\n                    $_SESSION[\'arc_scenario\']  = \'D\';\r\n                    $_SESSION[\'arc_fragmenta\'] = $fragmenta;\r\n                    echo \'<script type=\"text/javascript\">\r\n					window.location = \"https://chards.wasmer.app/index.php/login/\"\r\n					</script>\';\r\n                }\r\n\r\n                if ($owner_id === $user_id) {\r\n                    /* Scenario F — own card, go straight to pack opening */\r\n                    $_SESSION[\'arc_scenario\']         = \'F\';\r\n                    $_SESSION[\'chards_fragmenta_uid\'] = $_SESSION[\'cardID\'];\r\n					echo \'<script type=\"text/javascript\">\r\n					window.location = \"https://chards.wasmer.app/index.php/pack-opening/\"\r\n					</script>\';\r\n                }\r\n\r\n                /* Someone else\'s card — check if sharing is enabled */\r\n                $owner_row = $pdo->prepare(\"SELECT pin_hash FROM chards_users WHERE id = ?\");\r\n                $owner_row->execute([$owner_id]);\r\n                $owner_data = $owner_row->fetch();\r\n\r\n                if (!$fragmenta[\'is_locked\'] && !empty($owner_data[\'pin_hash\'])) {\r\n                    $_SESSION[\'arc_scenario\'] = \'E\';\r\n                } else {\r\n                    $_SESSION[\'arc_scenario\'] = \'no_pin_set\';\r\n                }\r\n                $_SESSION[\'arc_fragmenta\'] = $fragmenta;\r\n                echo \'<script type=\"text/javascript\">\r\n				window.location = \"https://chards.wasmer.app/index.php/login/\"\r\n				</script>\';\r\n\r\n            } else {\r\n                /* Logged in, no card — free play */\r\n                $_SESSION[\'arc_scenario\'] = \'free\';\r\n                echo \'<script type=\"text/javascript\">\r\n				window.location = \"https://chards.wasmer.app/index.php/login/\"\r\n				</script>\';\r\n            }\r\n\r\n        } else {\r\n            /* Not logged in */\r\n            if ($_SESSION[\'cardID\']) {\r\n                $stmt = $pdo->prepare(\"\r\n                    SELECT f.*, ft.cooldown_minutes, ft.cards_per_pack, ft.story_chance, ft.minimum_rarity\r\n                    FROM chards_fragmenta f\r\n                    JOIN chards_fragmenta_types ft ON ft.id = f.type_id\r\n                    WHERE f.uid = ?\r\n                \");\r\n                $stmt->execute([$_SESSION[\'cardID\']]);\r\n                $fragmenta = $stmt->fetch();\r\n\r\n                if (!$fragmenta) {\r\n                    $_SESSION[\'arc_scenario\']  = \'B_new_card\';\r\n                    $_SESSION[\'arc_fragmenta\'] = null;\r\n                   echo \' <script type=\"text/javascript\">\r\n					window.location = \"https://chards.wasmer.app/index.php/login/\"\r\n					</script>\';\r\n                }\r\n\r\n                if ($fragmenta[\'owner_user_id\'] === null) {\r\n                    /* Scenario B — unassigned NFC */\r\n                    $_SESSION[\'arc_scenario\']  = \'B\';\r\n                    $_SESSION[\'arc_fragmenta\'] = $fragmenta;\r\n                } else {\r\n                    /* Check sharing */\r\n                    $owner = $pdo->prepare(\"SELECT username, pin_hash FROM chards_users WHERE id = ?\");\r\n                    $owner->execute([$fragmenta[\'owner_user_id\']]);\r\n                    $owner_data = $owner->fetch();\r\n\r\n                    if (!$fragmenta[\'is_locked\'] && !empty($owner_data[\'pin_hash\'])) {\r\n                        $_SESSION[\'arc_scenario\'] = \'C\';\r\n                    } else {\r\n                        $_SESSION[\'arc_scenario\'] = \'no_pin_set\';\r\n                    }\r\n                    $_SESSION[\'arc_fragmenta\']       = $fragmenta;\r\n                    $_SESSION[\'arc_fragmenta_owner\'] = $owner_data[\'username\'] ?? \'\';\r\n                }\r\n\r\n            } else {\r\n                /* Scenario A — no card, not logged in */\r\n                $_SESSION[\'arc_scenario\']  = \'A\';\r\n                $_SESSION[\'arc_fragmenta\'] = null;\r\n            }\r\n\r\n          echo \'<script type=\"text/javascript\">\r\n			window.location = \"https://chards.wasmer.app/index.php/login/\"\r\n			</script>\';\r\n\r\n        }\r\n    }\r\n}\r\nadd_action(\'template_redirect\', \'chards_landing_redirect\');',	'landing',	'',	'trash',	'closed',	'closed',	'',	'landing__trashed',	'',	'',	'2026-05-18 19:51:25',	'2026-05-18 19:51:25',	'',	0,	'https://chards.wasmer.app/?post_type=wpcode&#038;p=153',	0,	'wpcode',	'',	0),
