(164,	1,	'2026-05-15 21:12:26',	'2026-05-15 21:12:26',	' if (!session_id()) session_start();\r\n\r\n        /* ── Capture card ID ── */\r\n        $_SESSION[\'cardID\'] = isset($_GET[\'card\']) && $_GET[\'card\'] !== \'\'\r\n            ? trim($_GET[\'card\'])\r\n            : null;\r\n\r\n        /* ── Check action flags set by hub buttons ── */\r\n        $register_card = $_SESSION[\'REGISTER_CARD\'] ?? false;\r\n        $set_pin       = $_SESSION[\'SET_PIN\']       ?? false;\r\n        $remove_pin    = $_SESSION[\'REMOVE_PIN\']    ?? false;\r\n\r\n        /* ── DB ── */\r\n        $pdo = null;\r\n        try {\r\n            $pdo = new PDO(\r\n                \'mysql:host=db.fr-pari1.bengt.wasmernet.com;port=10272;dbname=dbGQr4derPM6nWoRL4jPwNPN;charset=utf8mb4\',\r\n                \'0074c9f9784980005ded7796ee74\',\r\n                \'06950074-c9fa-7db2-8000-c0aec36ba1ac\',\r\n                [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]\r\n            );\r\n        } catch (PDOException $e) {\r\n			echo \'<script type=\"text/javascript\">\r\n			window.location = \"https://chards.wasmer.app/index.php/login/\"\r\n			</script>\';\r\n        }\r\n\r\n        $logged_in = !empty($_SESSION[\'chards_user_id\']);\r\n\r\n        if ($logged_in) {\r\n            $user_id = (int)$_SESSION[\'chards_user_id\'];\r\n\r\n            if ($_SESSION[\'cardID\']) {\r\n                $stmt = $pdo->prepare(\"\r\n                    SELECT f.*, ft.cooldown_minutes, ft.cards_per_pack, ft.story_chance, ft.minimum_rarity\r\n                    FROM chards_fragmenta f\r\n                    JOIN chards_fragmenta_types ft ON ft.id = f.type_id\r\n                    WHERE f.uid = ?\r\n                \");\r\n                $stmt->execute([$_SESSION[\'cardID\']]);\r\n                $fragmenta = $stmt->fetch();\r\n\r\n                if (!$fragmenta) {\r\n                    $_SESSION[\'arc_scenario\'] = \'unknown_card\';\r\n					echo \'<script type=\"text/javascript\">\r\n					window.location = \"https://chards.wasmer.app/index.php/login/\"\r\n					</script>\';\r\n                }\r\n\r\n                $owner_id = $fragmenta[\'owner_user_id\'] ? (int)$fragmenta[\'owner_user_id\'] : null;\r\n\r\n                  if ($owner_id === null) {\r\n                    if ($register_card) {\r\n                        /* Hub register flow — claim this card */\r\n                        $_SESSION[\'arc_scenario\']  = \'D\';\r\n                        $_SESSION[\'REGISTER_CARD\'] = false;\r\n                    } else {\r\n                        /* Standard scenario D */\r\n                        $_SESSION[\'arc_scenario\']  = \'D\';\r\n                    }\r\n                    $_SESSION[\'arc_fragmenta\'] = $fragmenta;\r\n                    wp_redirect(home_url(\'/index.php/login/\'));\r\n                    exit;\r\n                }\r\n\r\n                if ($owner_id === $user_id) {\r\n                    if ($set_pin) {\r\n                        /* Hub set/edit PIN flow */\r\n                        $_SESSION[\'arc_scenario\']   = \'pin_manage\';\r\n                        $_SESSION[\'PIN_TARGET_UID\'] = $_SESSION[\'cardID\'];\r\n                        $_SESSION[\'SET_PIN\']        = false;\r\n                        wp_redirect(home_url(\'/index.php/login/\'));\r\n                        exit;\r\n                    }\r\n                    if ($remove_pin) {\r\n                        /* Hub remove PIN flow */\r\n                        $_SESSION[\'arc_scenario\']   = \'pin_remove\';\r\n                        $_SESSION[\'PIN_TARGET_UID\'] = $_SESSION[\'cardID\'];\r\n                        $_SESSION[\'REMOVE_PIN\']     = false;\r\n                        wp_redirect(home_url(\'/index.php/login/\'));\r\n                        exit;\r\n                    }\r\n                    if ($register_card) {\r\n                        /* Already owns this card */\r\n                        $_SESSION[\'arc_scenario\']  = \'already_owned\';\r\n                        $_SESSION[\'REGISTER_CARD\'] = false;\r\n                        wp_redirect(home_url(\'/index.php/login/\'));\r\n                        exit;\r\n                    }\r\n                    /* Scenario F — own card, go straight to pack opening */\r\n                    $_SESSION[\'arc_scenario\']         = \'F\';\r\n                    $_SESSION[\'chards_fragmenta_uid\'] = $_SESSION[\'cardID\'];\r\n                    wp_redirect(home_url(\'/index.php/pack-opening/\'));\r\n                    exit;\r\n                }\r\n				/* Someone else\'s card */\r\n                if ($register_card) {\r\n                    /* Can\'t register someone else\'s card */\r\n                    $_SESSION[\'arc_scenario\']  = \'register_taken\';\r\n                    $_SESSION[\'REGISTER_CARD\'] = false;\r\n                    wp_redirect(home_url(\'/index.php/login/\'));\r\n                    exit;\r\n                }\r\n                if ($set_pin || $remove_pin) {\r\n                    /* Can\'t manage PIN on someone else\'s card */\r\n                    $_SESSION[\'arc_scenario\'] = \'pin_not_owner\';\r\n                    $_SESSION[\'SET_PIN\']      = false;\r\n                    $_SESSION[\'REMOVE_PIN\']   = false;\r\n                    wp_redirect(home_url(\'/index.php/login/\'));\r\n                    exit;\r\n                }\r\n\r\n                /* Someone else\'s card — check if sharing is enabled */\r\n                $owner_row = $pdo->prepare(\"SELECT pin_hash FROM chards_users WHERE id = ?\");\r\n                $owner_row->execute([$owner_id]);\r\n                $owner_data = $owner_row->fetch();\r\n\r\n                if (!$fragmenta[\'is_locked\'] && !empty($owner_data[\'pin_hash\'])) {\r\n                    $_SESSION[\'arc_scenario\'] = \'E\';\r\n                } else {\r\n                    $_SESSION[\'arc_scenario\'] = \'no_pin_set\';\r\n                }\r\n                $_SESSION[\'arc_fragmenta\'] = $fragmenta;\r\n                echo \'<script type=\"text/javascript\">\r\n				window.location = \"https://chards.wasmer.app/index.php/login/\"\r\n				</script>\';\r\n\r\n            } else {\r\n                /* Logged in, no card — free play */\r\n                $_SESSION[\'arc_scenario\'] = \'free\';\r\n                echo \'<script type=\"text/javascript\">\r\n				window.location = \"https://chards.wasmer.app/index.php/login/\"\r\n				</script>\';\r\n            }\r\n\r\n        } else {\r\n            /* Not logged in */\r\n            if ($_SESSION[\'cardID\']) {\r\n                $stmt = $pdo->prepare(\"\r\n                    SELECT f.*, ft.cooldown_minutes, ft.cards_per_pack, ft.story_chance, ft.minimum_rarity\r\n                    FROM chards_fragmenta f\r\n                    JOIN chards_fragmenta_types ft ON ft.id = f.type_id\r\n                    WHERE f.uid = ?\r\n                \");\r\n                $stmt->execute([$_SESSION[\'cardID\']]);\r\n                $fragmenta = $stmt->fetch();\r\n\r\n                if (!$fragmenta) {\r\n                    $_SESSION[\'arc_scenario\']  = \'B_new_card\';\r\n                    $_SESSION[\'arc_fragmenta\'] = null;\r\n                   echo \' <script type=\"text/javascript\">\r\n					window.location = \"https://chards.wasmer.app/index.php/login/\"\r\n					</script>\';\r\n                }\r\n\r\n                if ($fragmenta[\'owner_user_id\'] === null) {\r\n                    /* Scenario B — unassigned NFC */\r\n                    $_SESSION[\'arc_scenario\']  = \'B\';\r\n                    $_SESSION[\'arc_fragmenta\'] = $fragmenta;\r\n                } else {\r\n                    /* Check sharing */\r\n                    $owner = $pdo->prepare(\"SELECT username, pin_hash FROM chards_users WHERE id = ?\");\r\n                    $owner->execute([$fragmenta[\'owner_user_id\']]);\r\n                    $owner_data = $owner->fetch();\r\n\r\n                    if (!$fragmenta[\'is_locked\'] && !empty($owner_data[\'pin_hash\'])) {\r\n                        $_SESSION[\'arc_scenario\'] = \'C\';\r\n                    } else {\r\n                        $_SESSION[\'arc_scenario\'] = \'no_pin_set\';\r\n                    }\r\n                    $_SESSION[\'arc_fragmenta\']       = $fragmenta;\r\n                    $_SESSION[\'arc_fragmenta_owner\'] = $owner_data[\'username\'] ?? \'\';\r\n                }\r\n\r\n            } else {\r\n                /* Scenario A — no card, not logged in */\r\n                $_SESSION[\'arc_scenario\']  = \'A\';\r\n                $_SESSION[\'arc_fragmenta\'] = null;\r\n            }\r\n\r\n          echo \'<script type=\"text/javascript\">\r\n			window.location = \"https://chards.wasmer.app/index.php/login/\"\r\n			</script>\';\r\n\r\n        }\r\n\r\n',	'landing page redirect',	'',	'publish',	'closed',	'closed',	'',	'test-template_redirect',	'',	'',	'2026-05-24 19:22:26',	'2026-05-24 19:22:26',	'',	0,	'https://chards.wasmer.app/index.php/wpcode/test-template_redirect/',	0,	'wpcode',	'',	0),
(166,	1,	'2026-05-18 19:58:44',	'2026-05-18 19:58:44',	'if (!function_exists(\'chards_arc_ajax_handler\')) {\r\n\r\n   function chards_arc_ajax_handler() {\r\n\r\n    if (!session_id()) session_start();\r\n        if (!session_id()) session_start();\r\n        \r\n        $pdo = null;\r\n        try {\r\n            $pdo = new PDO(\r\n                \'mysql:host=db.fr-pari1.bengt.wasmernet.com;port=10272;dbname=dbGQr4derPM6nWoRL4jPwNPN;charset=utf8mb4\',\r\n                \'0074c9f9784980005ded7796ee74\',\r\n                \'06950074-c9fa-7db2-8000-c0aec36ba1ac\',\r\n                [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]\r\n            );\r\n        } catch (PDOException $e) {\r\n            wp_send_json_error([\'msg\' => \'Database connection failed.\']);\r\n        }\r\n\r\n        $sub = $_POST[\'sub\'] ?? \'\';\r\n        $nfc = $_SESSION[\'cardID\'] ?? null;\r\n\r\n        /* ── LOGIN ── */\r\n        if ($sub === \'arc_login\') {\r\n            $u    = trim($_POST[\'username\'] ?? \'\');\r\n            $p    = trim($_POST[\'password\'] ?? \'\');\r\n            $user = chards_get_user_by_username($pdo, $u);\r\n           if (!$user || !chards_verify_password($p, $user[\'password_hash\'])) {\r\n                wp_send_json_error([\'msg\' => \'Those credentials do not match our records.\']);\r\n            }\r\n            if (!$user[\'is_active\']) {\r\n                wp_send_json_error([\'msg\' => \'This account has been suspended by the ARC.\']);\r\n            }\r\n            if (!$user[\'email_verified\']) {\r\n                wp_send_json_error([\'msg\' => \'Your registration has not yet been confirmed. Check your correspondence for the confirmation notice from the ARC.\']);\r\n            }\r\n            $_SESSION[\'chards_user_id\']  = $user[\'id\'];\r\n            $_SESSION[\'chards_username\'] = $user[\'username\'];\r\n			\r\n            /* ── Set remember me cookie ── */\r\n            $raw_token = bin2hex(random_bytes(32));\r\n            $pdo->prepare(\"\r\n                INSERT INTO chards_remember_tokens (user_id, token_hash, expires_at)\r\n                VALUES (?, ?, DATE_ADD(NOW(), INTERVAL 30 DAY))\r\n            \")->execute([$user[\'id\'], hash(\'sha256\', $raw_token)]);\r\n            setcookie(\'chards_remember\', $raw_token, time() + (30 * 24 * 3600), \'/\', \'\', true, true);\r\n\r\n            $needs_claim     = false;\r\n            $needs_pin_setup = false;\r\n            if ($nfc) {\r\n                $frag = chards_get_fragmenta_by_uid($pdo, $nfc);\r\n                if ($frag && $frag[\'owner_user_id\'] === null) {\r\n                    chards_claim_fragmenta($pdo, $nfc, $user[\'id\']);\r\n                    $needs_claim     = true;\r\n                    $needs_pin_setup = !$user[\'pin_hash\'];\r\n                }\r\n            }\r\n            wp_send_json_success([\'needs_claim\' => $needs_claim, \'needs_pin_setup\' => $needs_pin_setup, \'remember_token\'  => $raw_token]);\r\n        }\r\n		\r\n        /* ── REGISTER ── */\r\n        elseif ($sub === \'arc_register\') {\r\n            $u = trim($_POST[\'username\'] ?? \'\');\r\n            $e = trim($_POST[\'email\']    ?? \'\');\r\n            $p = trim($_POST[\'password\'] ?? \'\');\r\n            try {\r\n                $result = chards_register_user($pdo, $u, $p, $e);\r\n\r\n				$verify_link = home_url(\'/index.php/verify-app/\') . \'?token=\' . urlencode($result[\'token\']);\r\n\r\n                wp_mail(\r\n                    $e,\r\n                    \'Confirm your ARC registration\',\r\n                    \"Citizen {$u},\\n\\nYour registration with the Aenephsy Regulation Compendium is nearly complete. Confirm your correspondence address to finalise your record:\\n\\n{$verify_link}\\n\\nIf you did not request this, disregard this notice.\\n\\n\" . chr(8212) . \" Aldric Voss, Senior Registrar\"\r\n                );\r\n\r\n                wp_send_json_success([]);\r\n            } catch (PDOException $e2) {\r\n                wp_send_json_error([\'msg\' => \'That username or email is already registered.\']);\r\n            }\r\n        }\r\n		\r\n        /* ── BORROW ── */\r\n        elseif ($sub === \'arc_borrow\') {\r\n            $u    = trim($_POST[\'username\'] ?? \'\');\r\n            $p    = trim($_POST[\'password\'] ?? \'\');\r\n            $pin  = trim($_POST[\'pin\']      ?? \'\');\r\n            $user = chards_get_user_by_username($pdo, $u);\r\n            if (!$user || !chards_verify_password($p, $user[\'password_hash\'])) {\r\n                wp_send_json_error([\'msg\' => \'Invalid credentials.\']);\r\n            }\r\n            $frag = $nfc ? chards_get_fragmenta_by_uid($pdo, $nfc) : null;\r\n            if (!$frag) wp_send_json_error([\'msg\' => \'Fragmenta not found.\']);\r\n\r\n            $access = chards_check_fragmenta_access($pdo, $frag, (int)$user[\'id\'], $pin);\r\n            if ($access === \'guest\' || $access === \'owner\') {\r\n                $_SESSION[\'chards_user_id\']      = $user[\'id\'];\r\n                $_SESSION[\'chards_username\']      = $user[\'username\'];\r\n                $_SESSION[\'chards_fragmenta_uid\'] = $nfc;\r\n                wp_send_json_success([]);\r\n            } elseif ($access === \'no_pin_set\') {\r\n                wp_send_json_error([\'msg\' => \'This Fragmenta has not been cleared for shared access.\']);\r\n            } elseif ($access === \'locked\') {\r\n                wp_send_json_error([\'msg\' => \'This Fragmenta is locked by its owner.\']);\r\n            } else {\r\n                wp_send_json_error([\'msg\' => \'Incorrect PIN. Access denied.\']);\r\n            }\r\n        }\r\n\r\n        /* ── PIN ONLY (scenario E) ── */\r\n        elseif ($sub === \'arc_pin\') {\r\n            $pin  = trim($_POST[\'pin\'] ?? \'\');\r\n            $frag = $nfc ? chards_get_fragmenta_by_uid($pdo, $nfc) : null;\r\n            if (!$frag) wp_send_json_error([\'msg\' => \'Fragmenta not found.\']);\r\n\r\n            $uid    = $_SESSION[\'chards_user_id\'] ?? 0;\r\n            $access = chards_check_fragmenta_access($pdo, $frag, (int)$uid, $pin);\r\n            if ($access === \'guest\') {\r\n                $_SESSION[\'chards_fragmenta_uid\'] = $nfc;\r\n                wp_send_json_success([]);\r\n            } elseif ($access === \'no_pin_set\') {\r\n                wp_send_json_error([\'msg\' => \'This Fragmenta has not been cleared for shared access.\']);\r\n            } elseif ($access === \'locked\') {\r\n                wp_send_json_error([\'msg\' => \'This Fragmenta is locked. The owner has disabled sharing.\']);\r\n            } else {\r\n                wp_send_json_error([\'msg\' => \'Incorrect PIN. Access denied.\']);\r\n            }\r\n        }\r\n /* ── CLAIM (scenario D — logged in, unassigned NFC) ── */\r\n        elseif ($sub === \'arc_claim\') {\r\n            $uid = $_SESSION[\'chards_user_id\'] ?? null;\r\n            if (!$uid || !$nfc) wp_send_json_error([\'msg\' => \'Session or NFC error.\']);\r\n\r\n            /* Check if this UID exists in the system at all */\r\n            $exists = $pdo->prepare(\r\n                \"SELECT COUNT(id) FROM chards_fragmenta WHERE uid = ?\"\r\n            );\r\n            $exists->execute([$nfc]);\r\n            $count = (int)$exists->fetchColumn();\r\n\r\n            if ($count === 0) {\r\n                /* UID not in DB — not an official card */\r\n                wp_send_json_error([\'msg\' => \'UNRECOGNISED_CARD\']);\r\n            }\r\n\r\n            $ok = chards_claim_fragmenta($pdo, $nfc, $uid);\r\n            if ($ok) {\r\n                $_SESSION[\'chards_fragmenta_uid\'] = $nfc;\r\n                wp_send_json_success([]);\r\n            } else {\r\n                wp_send_json_error([\'msg\' => \'This Fragmenta is already registered to another citizen.\']);\r\n            }\r\n        }\r\n\r\n /* ── SET PIN ── */\r\n        elseif ($sub === \'arc_set_pin\') {\r\n            $uid = $_SESSION[\'chards_user_id\'] ?? null;\r\n            $pin = trim($_POST[\'pin\'] ?? \'\');\r\n            if (!$uid) wp_send_json_error([\'msg\' => \'Session error.\']);\r\n            if ($pin) chards_set_pin($pdo, $uid, $pin);\r\n            if ($nfc) $_SESSION[\'chards_fragmenta_uid\'] = $nfc;\r\n            wp_send_json_success();\r\n        }\r\n\r\n        /* ── REMOVE PIN ── */\r\n        elseif ($sub === \'arc_remove_pin\') {\r\n            $uid = $_SESSION[\'chards_user_id\'] ?? null;\r\n            if (!$uid) wp_send_json_error([\'msg\' => \'Session error.\']);\r\n            $pdo->prepare(\r\n                \"UPDATE chards_users SET pin_hash = NULL WHERE id = ?\"\r\n            )->execute([$uid]);\r\n            $_SESSION[\'PIN_TARGET_UID\'] = null;\r\n            wp_send_json_success();\r\n        }\r\n\r\n     	/* ── SET ACTION FLAGS ── */\r\n        elseif ($sub === \'set_register_flag\') {\r\n            $_SESSION[\'REGISTER_CARD\'] = true;\r\n            $_SESSION[\'SET_PIN\']       = false;\r\n            $_SESSION[\'REMOVE_PIN\']    = false;\r\n            wp_send_json_success();\r\n        }\r\n        elseif ($sub === \'set_pin_flag\') {\r\n            $_SESSION[\'SET_PIN\']        = true;\r\n            $_SESSION[\'REGISTER_CARD\']  = false;\r\n            $_SESSION[\'REMOVE_PIN\']     = false;\r\n            wp_send_json_success();\r\n        }\r\n        elseif ($sub === \'set_remove_pin_flag\') {\r\n            $_SESSION[\'REMOVE_PIN\']     = true;\r\n            $_SESSION[\'REGISTER_CARD\']  = false;\r\n            $_SESSION[\'SET_PIN\']        = false;\r\n            wp_send_json_success();\r\n        }\r\n\r\n        /* ── RESET FLAGS ── */\r\n        elseif ($sub === \'reset_flags\') {\r\n            $_SESSION[\'REGISTER_CARD\']  = false;\r\n            $_SESSION[\'SET_PIN\']        = false;\r\n            $_SESSION[\'REMOVE_PIN\']     = false;\r\n            $_SESSION[\'PIN_TARGET_UID\'] = null;\r\n            wp_send_json_success();\r\n        }\r\n        wp_die();\r\n    }\r\n}\r\nadd_action(\'wp_ajax_chards_arc\',        \'chards_arc_ajax_handler\');\r\nadd_action(\'wp_ajax_nopriv_chards_arc\', \'chards_arc_ajax_handler\');',	'admin-ajax',	'',	'publish',	'closed',	'closed',	'',	'admin-ajax',	'',	'',	'2026-07-28 20:18:03',	'2026-07-28 20:18:03',	'',	0,	'https://chards.wasmer.app/?post_type=wpcode&#038;p=166',	0,	'wpcode',	'',	0),
(167,	1,	'2026-05-19 18:23:21',	'2026-05-19 18:23:21',	'<?php\r\n/* ============================================================\r\n   CHARDS — Player Hub\r\n   User dashboard: Fragmenta status, pack stats, navigation.\r\n   Deploy via Code Snippets on a WordPress page (slug: hub)\r\n============================================================ */\r\nif (!session_id()) session_start();\r\nchards_require_app_access(\'hub\');\r\n/* Redirect to login if not logged in }\r\nif (empty($_SESSION[\'chards_user_id\'])) {\r\n    wp_redirect(home_url(\'/index.php/login/\'));\r\n    exit;\r\n}*/\r\n\r\n/* ── DB ── */\r\n$pdo = null;\r\ntry {\r\n    $pdo = new PDO(\r\n        \'mysql:host=db.fr-pari1.bengt.wasmernet.com;port=10272;dbname=dbGQr4derPM6nWoRL4jPwNPN;charset=utf8mb4\',\r\n        \'0074c9f9784980005ded7796ee74\',\r\n        \'06950074-c9fa-7db2-8000-c0aec36ba1ac\',\r\n        [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]\r\n    );\r\n} catch (PDOException $e) { $pdo = null; }\r\n\r\n$user_id  = (int)$_SESSION[\'chards_user_id\'];\r\n$username = $_SESSION[\'chards_username\'] ?? \'Citizen\';\r\n\r\n/* ── FETCH USER\'S FRAGMENTA ── */\r\n$fragmenta_list = [];\r\nif ($pdo) {\r\n    $stmt = $pdo->prepare(\"\r\n        SELECT f.id, f.uid, f.is_locked, f.last_used_at,\r\n               ft.name AS type_name, ft.cooldown_minutes,\r\n               ft.cards_per_pack, ft.story_chance,\r\n               (u.pin_hash IS NOT NULL) AS pin_set\r\n        FROM chards_fragmenta f\r\n        JOIN chards_fragmenta_types ft ON ft.id = f.type_id\r\n        JOIN chards_users u ON u.id = f.owner_user_id\r\n        WHERE f.owner_user_id = ?\r\n        ORDER BY f.registered_at ASC\r\n    \");\r\n    $stmt->execute([$user_id]);\r\n    $fragmenta_list = $stmt->fetchAll();\r\n}\r\n\r\n/* ── FETCH PACK STATS ── */\r\n$total_packs = 0;\r\nif ($pdo) {\r\n    $stmt = $pdo->prepare(\"\r\n        SELECT COUNT(*) FROM chards_packs\r\n        WHERE finder_name = ? AND status = \'opened\'\r\n    \");\r\n    $stmt->execute([$username]);\r\n    $total_packs = (int)$stmt->fetchColumn();\r\n}\r\n\r\n/* ── COMPUTE COOLDOWN STATUS FOR EACH FRAGMENTA ── */\r\n/* Free account cooldown */\r\n$free_cooldown_mins = 1440;\r\n$free_last_pack     = null;\r\n$free_available     = true;\r\nif ($pdo) {\r\n    $stmt = $pdo->prepare(\"\r\n        SELECT MAX(opened_at) FROM chards_pack_log\r\n        WHERE user_id = ? AND fragmenta_id IS NULL\r\n    \");\r\n    $stmt->execute([$user_id]);\r\n    $free_last_pack = $stmt->fetchColumn();\r\n    if ($free_last_pack) {\r\n        $next = strtotime($free_last_pack) + ($free_cooldown_mins * 60);\r\n        $free_available = time() >= $next;\r\n        $free_secs_left = max(0, $next - time());\r\n    }\r\n}\r\n\r\nforeach ($fragmenta_list as &$frag) {\r\n    $frag[\'available\']  = true;\r\n    $frag[\'secs_left\']  = 0;\r\n    if ($frag[\'last_used_at\']) {\r\n        $next = strtotime($frag[\'last_used_at\']) + ((int)$frag[\'cooldown_minutes\'] * 60);\r\n        $frag[\'available\'] = time() >= $next;\r\n        $frag[\'secs_left\'] = max(0, $next - time());\r\n    }\r\n}\r\nunset($frag);\r\n\r\n$has_fragmenta    = !empty($fragmenta_list);\r\n$any_frag_ready   = $has_fragmenta && count(array_filter($fragmenta_list, fn($f) => $f[\'available\'])) > 0;\r\n?>\r\n<link href=\"https://fonts.googleapis.com/css2?family=Cinzel+Decorative:wght@400;700&family=Cinzel:wght@400;600&family=Crimson+Pro:ital,wght@0,300;0,400;0,600;1,300;1,400&family=JetBrains+Mono:wght@400;500&display=swap\" rel=\"stylesheet\">\r\n\r\n<style>\r\n#chards-hub *, #chards-hub *::before, #chards-hub *::after {\r\n  box-sizing: border-box; margin: 0; padding: 0;\r\n}\r\n#chards-hub {\r\n  --bg:       #0a0806;\r\n  --surface:  #13100d;\r\n  --surface2: #1c1712;\r\n  --border:   rgba(201,168,76,0.12);\r\n  --border-hi:rgba(201,168,76,0.35);\r\n  --gold:     #c9a84c;\r\n  --gold-dim: #6b5020;\r\n  --parch:    #e8dcc8;\r\n  --muted:    rgba(232,220,200,0.45);\r\n  --ok:       #4a8c5c;\r\n  --err:      #8c4a4a;\r\n  --r:        8px;\r\n\r\n  background: var(--bg);\r\n  color: var(--parch);\r\n  font-family: \'Crimson Pro\', Georgia, serif;\r\n  min-height: 80vh;\r\n  padding: 40px 20px 60px;\r\n}\r\n\r\n/* ── HEADER ── */\r\n#chards-hub .hub-header {\r\n  text-align: center;\r\n  margin-bottom: 36px;\r\n  position: relative;\r\n}\r\n#chards-hub .hub-header::after {\r\n  content: \'\';\r\n  display: block;\r\n  width: 60px; height: 1px;\r\n  background: var(--gold-dim);\r\n  margin: 16px auto 0;\r\n}\r\n#chards-hub .hub-welcome {\r\n  font-family: \'Cinzel Decorative\', serif;\r\n  font-size: clamp(11px, 2vw, 14px);\r\n  color: var(--gold-dim);\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  margin-bottom: 6px;\r\n}\r\n#chards-hub .hub-username {\r\n  font-family: \'Cinzel\', serif;\r\n  font-size: clamp(22px, 5vw, 36px);\r\n  color: var(--gold);\r\n  letter-spacing: 0.05em;\r\n  text-shadow: 0 0 30px rgba(201,168,76,0.25);\r\n}\r\n\r\n/* ── LAYOUT ── */\r\n#chards-hub .hub-wrap {\r\n  max-width: 700px;\r\n  margin: 0 auto;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 24px;\r\n}\r\n\r\n/* ── CARDS / SECTIONS ── */\r\n#chards-hub .hub-section {\r\n  background: var(--surface);\r\n  border: 1px solid var(--border);\r\n  border-radius: var(--r);\r\n  padding: 20px 24px;\r\n}\r\n#chards-hub .hub-section-title {\r\n  font-family: \'Cinzel\', serif;\r\n  font-size: 11px;\r\n  letter-spacing: 0.15em;\r\n  text-transform: uppercase;\r\n  color: var(--gold-dim);\r\n  margin-bottom: 16px;\r\n  padding-bottom: 10px;\r\n  border-bottom: 1px solid var(--border);\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n}\r\n\r\n/* ── STATS ROW ── */\r\n#chards-hub .hub-stats {\r\n  display: flex;\r\n  gap: 16px;\r\n  flex-wrap: wrap;\r\n}\r\n#chards-hub .hub-stat {\r\n  flex: 1;\r\n  min-width: 100px;\r\n  text-align: center;\r\n  padding: 14px 10px;\r\n  background: var(--surface2);\r\n  border-radius: var(--r);\r\n  border: 1px solid var(--border);\r\n}\r\n#chards-hub .hub-stat-value {\r\n  font-family: \'Cinzel\', serif;\r\n  font-size: 28px;\r\n  color: var(--gold);\r\n  line-height: 1;\r\n  margin-bottom: 4px;\r\n}\r\n#chards-hub .hub-stat-label {\r\n  font-size: 11px;\r\n  color: var(--muted);\r\n  letter-spacing: 0.08em;\r\n  text-transform: uppercase;\r\n}\r\n\r\n/* ── FRAGMENTA LIST ── */\r\n#chards-hub .hub-frag-item {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 14px;\r\n  padding: 12px 0;\r\n  border-bottom: 1px solid var(--border);\r\n}\r\n#chards-hub .hub-frag-item:last-child { border-bottom: none; }\r\n\r\n#chards-hub .hub-frag-icon {\r\n  width: 42px; height: 42px;\r\n  border-radius: 50%;\r\n  background: var(--surface2);\r\n  border: 1px solid var(--border);\r\n  display: flex; align-items: center; justify-content: center;\r\n  font-size: 18px;\r\n  flex-shrink: 0;\r\n  color: var(--gold);\r\n}\r\n#chards-hub .hub-frag-icon.ready {\r\n  border-color: var(--gold);\r\n  box-shadow: 0 0 12px rgba(201,168,76,0.2);\r\n}\r\n\r\n#chards-hub .hub-frag-info { flex: 1; min-width: 0; }\r\n#chards-hub .hub-frag-name {\r\n  font-family: \'Cinzel\', serif;\r\n  font-size: 13px;\r\n  color: var(--parch);\r\n  margin-bottom: 3px;\r\n}\r\n#chards-hub .hub-frag-meta {\r\n  font-size: 12px;\r\n  color: var(--muted);\r\n  font-family: \'JetBrains Mono\', monospace;\r\n}\r\n#chards-hub .hub-frag-meta.ready { color: #8fcc9f; }\r\n#chards-hub .hub-frag-meta.cooldown { color: rgba(201,168,76,0.5); }\r\n\r\n#chards-hub .hub-frag-open {\r\n  font-family: \'Cinzel\', serif;\r\n  font-size: 10px;\r\n  letter-spacing: 0.08em;\r\n  padding: 8px 14px;\r\n  border-radius: 4px;\r\n  border: none;\r\n  cursor: pointer;\r\n  text-decoration: none;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  transition: background 0.2s;\r\n  white-space: nowrap;\r\n}\r\n#chards-hub .hub-frag-open.ready {\r\n  background: rgba(201,168,76,0.9);\r\n  color: #0a0806;\r\n}\r\n#chards-hub .hub-frag-open.ready:hover { background: var(--gold); }\r\n#chards-hub .hub-frag-open.waiting {\r\n  background: transparent;\r\n  border: 1px solid var(--border);\r\n  color: var(--muted);\r\n  cursor: default;\r\n  pointer-events: none;\r\n}\r\n\r\n/* ── FREE PACK SECTION ── */\r\n#chards-hub .hub-free-prominent {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  gap: 12px;\r\n  padding: 8px 0 4px;\r\n}\r\n#chards-hub .hub-free-btn {\r\n  font-family: \'Cinzel\', serif;\r\n  font-size: 13px;\r\n  letter-spacing: 0.08em;\r\n  padding: 14px 36px;\r\n  border-radius: 50px;\r\n  border: none;\r\n  cursor: pointer;\r\n  text-decoration: none;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  background: linear-gradient(135deg, #5b3fbe 0%, #3a2a8a 100%);\r\n  color: #fff;\r\n  box-shadow: 0 6px 28px rgba(80,50,200,0.35);\r\n  transition: transform 0.15s, box-shadow 0.15s;\r\n}\r\n#chards-hub .hub-free-btn:hover {\r\n  transform: translateY(-2px);\r\n  box-shadow: 0 8px 36px rgba(80,50,200,0.5);\r\n}\r\n#chards-hub .hub-free-btn.disabled {\r\n  background: var(--surface2);\r\n  color: var(--muted);\r\n  box-shadow: none;\r\n  cursor: default;\r\n  pointer-events: none;\r\n  border: 1px solid var(--border);\r\n}\r\n#chards-hub .hub-free-countdown {\r\n  font-family: \'JetBrains Mono\', monospace;\r\n  font-size: 12px;\r\n  color: var(--muted);\r\n  letter-spacing: 0.05em;\r\n}\r\n\r\n/* ── FREE PACK SUBTLE LINK (when Fragmenta present) ── */\r\n#chards-hub .hub-free-subtle {\r\n  text-align: center;\r\n  padding-top: 4px;\r\n}\r\n#chards-hub .hub-free-subtle a,\r\n#chards-hub .hub-free-subtle span {\r\n  font-size: 12px;\r\n  color: var(--muted);\r\n  font-style: italic;\r\n  text-decoration: none;\r\n  border-bottom: 1px solid transparent;\r\n  transition: color 0.2s, border-color 0.2s;\r\n  cursor: pointer;\r\n}\r\n#chards-hub .hub-free-subtle a:hover { color: var(--parch); border-bottom-color: var(--border); }\r\n#chards-hub .hub-free-subtle span { cursor: default; }\r\n\r\n/* ── NAV BUTTONS ── */\r\n#chards-hub .hub-nav {\r\n  display: grid;\r\n  grid-template-columns: 1fr 1fr;\r\n  gap: 12px;\r\n}\r\n#chards-hub .hub-nav-btn {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 8px;\r\n  padding: 20px 16px;\r\n  background: var(--surface2);\r\n  border: 1px solid var(--border);\r\n  border-radius: var(--r);\r\n  text-decoration: none;\r\n  color: var(--parch);\r\n  transition: border-color 0.2s, background 0.2s, transform 0.15s;\r\n  cursor: pointer;\r\n}\r\n#chards-hub .hub-nav-btn:hover {\r\n  border-color: var(--border-hi);\r\n  background: rgba(201,168,76,0.05);\r\n  transform: translateY(-2px);\r\n}\r\n#chards-hub .hub-nav-icon { font-size: 24px; color: var(--gold); }\r\n#chards-hub .hub-nav-label {\r\n  font-family: \'Cinzel\', serif;\r\n  font-size: 11px;\r\n  letter-spacing: 0.1em;\r\n  text-transform: uppercase;\r\n  color: var(--parch);\r\n}\r\n#chards-hub .hub-nav-sub {\r\n  font-size: 12px;\r\n  color: var(--muted);\r\n  font-style: italic;\r\n  text-align: center;\r\n}\r\n\r\n/* ── LOGOUT ── */\r\n#chards-hub .hub-logout {\r\n  text-align: center;\r\n  padding-top: 8px;\r\n}\r\n#chards-hub .hub-logout a {\r\n  font-size: 12px;\r\n  color: var(--muted);\r\n  text-decoration: none;\r\n  font-style: italic;\r\n  transition: color 0.2s;\r\n}\r\n#chards-hub .hub-logout a:hover { color: var(--parch); }\r\n	\r\n#chards-hub .hub-action-btn {\r\n  font-family: \'Cinzel\', serif;\r\n  font-size: 9px;\r\n  letter-spacing: 0.1em;\r\n  padding: 5px 12px;\r\n  border-radius: 4px;\r\n  border: 1px solid var(--border-hi);\r\n  background: transparent;\r\n  color: var(--gold);\r\n  cursor: pointer;\r\n  transition: background 0.2s;\r\n}\r\n#chards-hub .hub-action-btn:hover {\r\n  background: rgba(201,168,76,0.1);\r\n}\r\n#chards-hub .hub-pin-btn {\r\n  font-family: \'JetBrains Mono\', monospace;\r\n  font-size: 9px;\r\n  padding: 4px 8px;\r\n  border-radius: 4px;\r\n  border: 1px solid var(--border);\r\n  background: transparent;\r\n  color: var(--muted);\r\n  cursor: pointer;\r\n  transition: border-color 0.2s, color 0.2s;\r\n}\r\n#chards-hub .hub-pin-btn:hover {\r\n  border-color: var(--border-hi);\r\n  color: var(--parch);\r\n}\r\n#chards-hub .hub-pin-btn.remove:hover {\r\n  border-color: rgba(140,74,74,0.5);\r\n  color: #cc8f8f;\r\n}\r\n\r\n/* ── SCAN POPUP ── */\r\n#hub-scan-overlay {\r\n  display: none;\r\n  position: fixed; inset: 0;\r\n  z-index: 9999;\r\n  background: rgba(5,3,2,0.85);\r\n  backdrop-filter: blur(4px);\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n#hub-scan-overlay.open { display: flex; }\r\n\r\n#hub-scan-popup {\r\n  background: #0e0b08;\r\n  border: 1px solid rgba(201,168,76,0.25);\r\n  border-radius: 12px;\r\n  padding: 36px 40px;\r\n  text-align: center;\r\n  max-width: 320px;\r\n  width: 90%;\r\n  box-shadow: 0 20px 60px rgba(0,0,0,0.7);\r\n  animation: popIn 0.3s cubic-bezier(0.34,1.4,0.64,1) forwards;\r\n}\r\n@keyframes popIn {\r\n  from { transform: scale(0.85); opacity: 0; }\r\n  to   { transform: scale(1);    opacity: 1; }\r\n}\r\n#hub-scan-icon {\r\n  font-size: 48px;\r\n  margin-bottom: 16px;\r\n  animation: pulse 2s ease-in-out infinite;\r\n}\r\n@keyframes pulse {\r\n  0%,100% { opacity: 0.6; transform: scale(1); }\r\n  50%      { opacity: 1;   transform: scale(1.08); }\r\n}\r\n#hub-scan-title {\r\n  font-family: \'Cinzel\', serif;\r\n  font-size: 14px;\r\n  letter-spacing: 0.1em;\r\n  color: rgba(201,168,76,0.9);\r\n  margin-bottom: 10px;\r\n}\r\n#hub-scan-msg {\r\n  font-family: \'Crimson Pro\', serif;\r\n  font-style: italic;\r\n  font-size: 15px;\r\n  color: rgba(232,220,200,0.6);\r\n  line-height: 1.5;\r\n  margin-bottom: 24px;\r\n}\r\n#hub-scan-cancel {\r\n  font-family: \'Cinzel\', serif;\r\n  font-size: 10px;\r\n  letter-spacing: 0.1em;\r\n  padding: 9px 24px;\r\n  border-radius: 4px;\r\n  border: 1px solid rgba(201,168,76,0.2);\r\n  background: transparent;\r\n  color: rgba(201,168,76,0.5);\r\n  cursor: pointer;\r\n  transition: border-color 0.2s, color 0.2s;\r\n}\r\n#hub-scan-cancel:hover {\r\n  border-color: rgba(201,168,76,0.5);\r\n  color: rgba(201,168,76,0.9);\r\n}\r\n</style>\r\n\r\n<div id=\"chards-hub\">\r\n  <div class=\"hub-header\">\r\n    <div class=\"hub-welcome\">Welcome back, Citizen</div>\r\n    <div class=\"hub-username\"><?= htmlspecialchars($username) ?></div>\r\n  </div>\r\n\r\n  <div class=\"hub-wrap\">\r\n\r\n    <!-- Stats -->\r\n    <div class=\"hub-section\">\r\n      <div class=\"hub-section-title\">Registry Record</div>\r\n      <div class=\"hub-stats\">\r\n        <div class=\"hub-stat\">\r\n          <div class=\"hub-stat-value\"><?= $total_packs ?></div>\r\n          <div class=\"hub-stat-label\">Packs Opened</div>\r\n        </div>\r\n        <div class=\"hub-stat\">\r\n          <div class=\"hub-stat-value\"><?= count($fragmenta_list) ?></div>\r\n          <div class=\"hub-stat-label\">Fragmenta</div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n<!-- Fragmenta section — always visible -->\r\n<div class=\"hub-section\">\r\n  <div class=\"hub-section-title\">\r\n    Your Fragmenta\r\n    <button class=\"hub-action-btn\" onclick=\"hubScanPrompt(\'register\')\">+ Register New</button>\r\n  </div>\r\n  \r\n<?php if ($has_fragmenta): ?>\r\n  <?php foreach ($fragmenta_list as $frag): ?>\r\n    <?php\r\n      $ready    = $frag[\'available\'];\r\n      $h        = floor($frag[\'secs_left\'] / 3600);\r\n      $m        = floor(($frag[\'secs_left\'] % 3600) / 60);\r\n      $s        = $frag[\'secs_left\'] % 60;\r\n      $countdown = sprintf(\'%02d:%02d:%02d\', $h, $m, $s);\r\n      $pack_url = home_url(\'/index.php/pack-opening/?frag=\' . $frag[\'id\']);\r\n    ?>\r\n    <div class=\"hub-frag-item\">\r\n      <div class=\"hub-frag-icon <?= $ready ? \'ready\' : \'\' ?>\">◈</div>\r\n      <div class=\"hub-frag-info\">\r\n        <div class=\"hub-frag-name\"><?= htmlspecialchars($frag[\'type_name\']) ?></div>\r\n        <div class=\"hub-frag-meta <?= $ready ? \'ready\' : \'cooldown\' ?>\">\r\n          <?php if ($ready): ?>\r\n            Ready to open\r\n          <?php else: ?>\r\n            Available in <?= $countdown ?>\r\n          <?php endif; ?>\r\n        </div>\r\n      </div>\r\n      <div style=\"display:flex; flex-direction:column; gap:6px; align-items:flex-end;\">\r\n        <a href=\"<?= $ready ? $pack_url : \'#\' ?>\"\r\n           class=\"hub-frag-open <?= $ready ? \'ready\' : \'waiting\' ?>\">\r\n          <?= $ready ? \'Open Pack\' : \'Cooling Down\' ?>\r\n        </a>F\r\n        <div style=\"display:flex; gap:6px;\">\r\n          <button class=\"hub-pin-btn\" onclick=\"hubScanPrompt(\'pin\')\">\r\n            <?= $frag[\'is_locked\'] || !empty($frag[\'pin_set\']) ? \'✎ Edit PIN\' : \'+ Set PIN\' ?>\r\n          </button>\r\n          <?php if (!empty($frag[\'pin_set\'])): ?>\r\n          <button class=\"hub-pin-btn remove\" onclick=\"hubScanPrompt(\'remove_pin\')\">✕ PIN</button>\r\n          <?php endif; ?>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  <?php endforeach; ?>\r\n\r\n  <!-- Subtle free pack option (shown when user HAS fragmenta) -->\r\n  <div class=\"hub-free-subtle\" style=\"margin-top:14px\">\r\n    <?php if ($free_available): ?>F\r\n      <a href=\"<?= home_url(\'/index.php/pack-opening/\') ?>\">\r\n        Or open a free pack instead\r\n      </a>\r\n    <?php else: ?>\r\n      <span>Free pack available in\r\n        <span id=\"hub-free-timer\"><?php\r\n          $fl = isset($free_secs_left) ? $free_secs_left : 0;\r\n          echo sprintf(\'%02d:%02d:%02d\', floor($fl/3600), floor(($fl%3600)/60), $fl%60);\r\n        ?></span>\r\n      </span>\r\n    <?php endif; ?>\r\n  </div>\r\n\r\n</div> <!-- Close the hub-section -->\r\n\r\n<?php else: ?>\r\n<!-- No Fragmenta — prominent free pack CTA -->\r\n<div class=\"hub-section\">\r\n  <div class=\"hub-section-title\">Pack Opening</div>\r\n  <div class=\"hub-free-prominent\">\r\n    <?php if ($free_available): ?>\r\n      <a href=\"<?= home_url(\'/index.php/pack-opening/\') ?>\" class=\"hub-free-btn\">\r\n        ✦ Open a Free Pack\r\n      </a>\r\n      <div class=\"hub-free-countdown\">Your daily pack is ready</div>\r\n    <?php else: ?>\r\n      <a class=\"hub-free-btn disabled\">✦ Open a Free Pack</a>\r\n      <div class=\"hub-free-countdown\">\r\n        Next free pack in <span id=\"hub-free-timer\"><?php\r\n          $fl = isset($free_secs_left) ? $free_secs_left : 0;\r\n          echo sprintf(\'%02d:%02d:%02d\', floor($fl/3600), floor(($fl%3600)/60), $fl%60);\r\n        ?></span>\r\n      </div>\r\n    <?php endif; ?> \r\n  </div>\r\n</div>\r\n<?php endif; ?>\r\n\r\n    <!-- Navigation -->\r\n    <div class=\"hub-section\">\r\n      <div class=\"hub-section-title\">Compendium</div>\r\n      <div class=\"hub-nav\">\r\n        <a href=\"<?= home_url(\'/index.php/story/\') ?>\" class=\"hub-nav-btn\">\r\n          <div class=\"hub-nav-icon\">📖</div>\r\n          <div class=\"hub-nav-label\">Story</div>\r\n          <div class=\"hub-nav-sub\">The Fragmenta Chronicles</div>\r\n        </a>\r\n        <a href=\"<?= home_url(\'/index.php/collection/\') ?>\" class=\"hub-nav-btn\">\r\n          <div class=\"hub-nav-icon\">✦</div>\r\n          <div class=\"hub-nav-label\">Collection</div>\r\n          <div class=\"hub-nav-sub\">Your collected cards</div>\r\n        </a>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Logout -->\r\n    <div class=\"hub-logout\">\r\n      <a href=\"<?= home_url(\'/index.php/logout/\') ?>\">Sign out of the registry</a>\r\n    </div>\r\n	  <!-- Scan Popup -->\r\n	  <div id=\"hub-scan-overlay\">\r\n		<div id=\"hub-scan-popup\">\r\n		  <div id=\"hub-scan-icon\">𒋝</div>\r\n		  <div id=\"hub-scan-title\">ARC Registration Terminal</div>\r\n		  <div id=\"hub-scan-msg\">\r\n			Please present your Fragmenta for Analysis.\r\n		  </div>\r\n		  <button id=\"hub-scan-cancel\" onclick=\"hubCancelScan()\">Cancel</button>\r\n		</div>\r\n	  </div>\r\n  </div>\r\n</div>\r\n\r\n<script>\r\n/* Live countdown for free pack timer */\r\n(function() {\r\n  var timerEl = document.getElementById(\'hub-free-timer\');\r\n  if (!timerEl) return;\r\n\r\n  var secs = <?= isset($free_secs_left) ? (int)$free_secs_left : 0 ?>;\r\n  if (secs <= 0) return;\r\n\r\n  var interval = setInterval(function() {\r\n    secs--;\r\n    if (secs <= 0) {\r\n      clearInterval(interval);\r\n      window.location.reload();\r\n      return;\r\n    }\r\n    var h = Math.floor(secs / 3600);\r\n    var m = Math.floor((secs % 3600) / 60);\r\n    var s = secs % 60;\r\n    timerEl.textContent =\r\n      (h < 10 ? \'0\' : \'\') + h + \':\' +\r\n      (m < 10 ? \'0\' : \'\') + m + \':\' +\r\n      (s < 10 ? \'0\' : \'\') + s;\r\n  }, 1000);\r\n})();\r\n	/* ── SCAN POPUP ── */\r\nvar AJAX_URL = \'<?= esc_url(admin_url(\'admin-ajax.php\')) ?>\';\r\nconsole.log(AJAX_URL)\r\n	\r\nfunction hubScanPrompt(action) {\r\n  /* Set session flag via AJAX then show popup */\r\n  var sub = action === \'register\'   ? \'set_register_flag\'   :\r\n            action === \'pin\'        ? \'set_pin_flag\'        :\r\n                                      \'set_remove_pin_flag\' ;\r\n\r\n  fetch(AJAX_URL, {\r\n    method: \'POST\',\r\n    headers: { \'Content-Type\': \'application/x-www-form-urlencoded\' },\r\n    body: \'action=chards_arc&sub=\' + sub\r\n  }).then(function() {\r\n    document.getElementById(\'hub-scan-overlay\').classList.add(\'open\');\r\n  });\r\n}\r\n\r\nfunction hubCancelScan() {\r\n  /* Reset all flags and close popup */\r\n  fetch(AJAX_URL, {\r\n    method: \'POST\',\r\n    headers: { \'Content-Type\': \'application/x-www-form-urlencoded\' },\r\n    body: \'action=chards_arc&sub=reset_flags\'\r\n  }).then(function() {\r\n    document.getElementById(\'hub-scan-overlay\').classList.remove(\'open\');\r\n  });\r\n}\r\n</script>',	'hub',	'',	'publish',	'closed',	'closed',	'',	'hub',	'',	'',	'2026-07-27 19:14:59',	'2026-07-27 19:14:59',	'',	0,	'https://chards.wasmer.app/?post_type=wpcode&#038;p=167',	0,	'wpcode',	'',	0),
