(171,	1,	'2026-05-23 11:11:55',	'2026-05-23 11:11:55',	'<!-- wp:cover {\"url\":\"https://chards.wasmer.app/wp-content/uploads/2026/04/bg2-768x770-1.png\",\"id\":123,\"hasParallax\":true,\"dimRatio\":50,\"customOverlayColor\":\"#3d3b52\",\"isUserOverlayColor\":false,\"minHeight\":2071,\"minHeightUnit\":\"px\",\"contentPosition\":\"top center\",\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover has-parallax has-custom-content-position is-position-top-center\" style=\"min-height:2071px\"><div class=\"wp-block-cover__image-background wp-image-123 size-full has-parallax\" style=\"background-position:50% 50%;background-image:url(https://chards.wasmer.app/wp-content/uploads/2026/04/bg2-768x770-1.png)\"></div><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\" style=\"background-color:#3d3b52\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:spacer {\"height\":\"73px\"} -->\n<div style=\"height:73px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:shortcode -->\n[wpcode id=\"172\"]\n<!-- /wp:shortcode --></div></div>\n<!-- /wp:cover -->',	'logout',	'',	'publish',	'closed',	'closed',	'',	'logout',	'',	'',	'2026-05-23 11:13:18',	'2026-05-23 11:13:18',	'',	0,	'https://chards.wasmer.app/?page_id=171',	0,	'page',	'',	0),
(172,	1,	'2026-05-23 11:12:30',	'2026-05-23 11:12:30',	'if (!session_id()) session_start();\r\n\r\n/* ── Delete remember token from DB if cookie exists ── */\r\nif (!empty($_COOKIE[\'chards_remember\'])) {\r\n    try {\r\n        $pdo = new PDO(\r\n            \'mysql:host=db.fr-pari1.bengt.wasmernet.com;port=10272;dbname=dbGQr4derPM6nWoRL4jPwNPN;charset=utf8mb4\',\r\n            \'0074c9f9784980005ded7796ee74\',\r\n            \'06950074-c9fa-7db2-8000-c0aec36ba1ac\',\r\n            [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]\r\n        );\r\n        $pdo->prepare(\r\n            \"DELETE FROM chards_remember_tokens WHERE token_hash = ?\"\r\n        )->execute([hash(\'sha256\', $_COOKIE[\'chards_remember\'])]);\r\n    } catch (PDOException $e) { /* fail silently */ }\r\n\r\n    /* Clear the cookie */\r\n    setcookie(\'chards_remember\', \'\', time() - 3600, \'/\', \'\', true, true);\r\n}\r\n\r\n/* ── Destroy session ── */\r\n$_SESSION = [];\r\nsession_destroy();\r\n\r\n/* ── Redirect to front page ── */\r\necho \'<script>window.location.href = \"\' . home_url(\'/index.php\') . \'\";</script>\';',	'logout',	'',	'publish',	'closed',	'closed',	'',	'logout',	'',	'',	'2026-05-23 11:13:50',	'2026-05-23 11:13:50',	'',	0,	'https://chards.wasmer.app/index.php/wpcode/logout/',	0,	'wpcode',	'',	0),
