(200,	1,	'2026-07-25 20:57:01',	'2026-07-25 20:57:01',	'/* ============================================================\r\n   CHARDS — In-App Email Verification Endpoint\r\n   Loaded inside the Android WebView after a deep link.\r\n   No login/register UI — confirmation only.\r\n============================================================ */\r\n\r\n$dsn = \'mysql:host=db.fr-pari1.bengt.wasmernet.com;port=10272;dbname=dbGQr4derPM6nWoRL4jPwNPN;charset=utf8mb4\';\r\ntry {\r\n    $pdo = new PDO($dsn, \'0074c9f9784980005ded7796ee74\', \'06950074-c9fa-7db2-8000-c0aec36ba1ac\', [\r\n        PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,\r\n        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,\r\n    ]);\r\n} catch (PDOException $e) {\r\n    $pdo = null;\r\n}\r\n\r\n$token  = trim($_GET[\'token\'] ?? \'\');\r\n$result = ($pdo && $token) ? chards_confirm_email($pdo, $token) : false;\r\n$login_url = home_url(\'/index.php/login/\');\r\n?>\r\n<!DOCTYPE html>\r\n<html>\r\n<head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"></head>\r\n<body style=\"margin:0; background:#0a0806; min-height:100vh; display:flex; align-items:center; justify-content:center; padding:40px 20px; font-family:Georgia,serif;\">\r\n  <div style=\"max-width:360px; text-align:center; color:#e8dcc8;\">\r\n    <div style=\"font-size:44px; margin-bottom:18px; color:#c9a84c;\"><?= $result ? \'✦\' : \'✕\' ?></div>\r\n    <div style=\"font-size:16px; letter-spacing:0.08em; color:#c9a84c; margin-bottom:14px; text-transform:uppercase;\">\r\n      <?= $result ? \'Registration Confirmed\' : \'Link Invalid\' ?>\r\n    </div>\r\n    <div style=\"font-style:italic; font-size:16px; line-height:1.6; color:rgba(232,220,200,0.75); margin-bottom:28px;\">\r\n      <?= $result\r\n          ? \'Your record has been finalised, citizen. You may now log in.\'\r\n          : \'This confirmation link is invalid or has already been used.\' ?>\r\n    </div>\r\n	<p>\r\n	  Please return to the App to login.\r\n	</p>\r\n  </div>\r\n</body>\r\n</html>',	'verify app',	'',	'publish',	'closed',	'closed',	'',	'verify-app',	'',	'',	'2026-07-30 20:03:50',	'2026-07-30 20:03:50',	'',	0,	'https://chards.wasmer.app/index.php/wpcode/verify-app/',	0,	'wpcode',	'',	0),
